// 周/天/任务/讲义/资源 数据 (由旧版HTML自动提取 + 多轮补充讲义)
export const weeksData = [{"id": "w1", "badge": "W1", "title": "原理与规格：DRAM基础 + DDR4/DDR5 + 时序 + 命名", "sub": "阶段 P1 · 用一周建立\"内存是怎么回事\"的底层认知", "accept": "能口述D4/D5差异（电压/速率/架构），解释CL/tRCD/tRP/tRAS对稳定性与性能的影响。", "tools": "JEDEC规范、产品Datasheet、CPU-Z", "phase": "P1", "weekend": "周末加油站：把 D4 vs D5 对比表贴在工位；用 CPU-Z 看家里/公司所有电脑的内存并做记录；预习下周一《产品硬件结构》拆解视频。 可选：找一条坏内存/旧内存备用下周拆解", "days": [{"id": "d1", "title": "DRAM 工作原理与产品线认知", "date": "Day 1 · 周一", "dot": "1", "tasks": ["DRAM基本结构：1T1C单元、Bank/Rank/行列、刷新原理（为什么内存要刷新）", "浏览公司产品线：DDR4/DDR5 的 UDIMM/SODIMM/RDIMM 区别、SSD/PSSD/嵌入式 eMMC/UFS/LPDDR/eMCP/uMCP", "读 1 份 HOGE 产品 Datasheet，找出容量/速率/电压/时序关键页", "安装 CPU-Z，看懂 Memory 和 SPD 页布局"], "tools": "JESD79-4 前言、公司产品规格书、CPU-Z", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1Htr8YhELV", "label": "▶ 用最好的动画为你讲解--内存的原理（Redknot-乔红 · 343.7万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19v4y1P7Cv", "label": "▶ 一条视频了解内存条·如何挑选（宅机侠 · 37.8万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1yqTuzeEKC", "label": "▶ 内存？显存？缓存？4分钟解释存储（超极氪 · 3.1万播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Dynamic_random-access_memory", "label": "📄 维基百科·DRAM详解"}, {"type": "off", "url": "https://www.hogestorage.com/", "label": "📄 汇钜存储官网"}], "lectures": [{"title": "DRAM 工作原理（1T1C、Bank/Rank、刷新）", "html": "<h5>1. 基本存储单元：1T1C</h5>\n<p>每个 bit 由 <b>1 个晶体管 + 1 个电容</b>（1T1C）组成：电容存电荷代表 1/0，晶体管负责读写控制。相比 SRAM（6 个晶体管），1T1C 密度高、成本低、功耗相对高，所以必须<b>周期性刷新</b>——因为电容会漏电，电荷慢慢消失。</p>\n<h5>2. 层级结构：Channel → DIMM → Rank → Chip → Bank</h5>\n<ul><li><b>Channel（通道）</b>：CPU 内存控制器到内存条的数据通路。双通道 = 两条 64bit 通路并行。</li>\n<li><b>Rank（秩）</b>：内存条上一组颗粒组成的 64bit（ECC 为 72bit）数据位宽。单面 1Rank、双面 2Rank（1Rx8=单面8颗粒，2Rx8=双面16颗粒）。</li>\n<li><b>Chip（颗粒）</b>：单颗 DRAM 芯片，有 x4/x8/x16 位宽之分。</li>\n<li><b>Bank（库）</b>：颗粒内部划分的存储阵列，Bank 多 → 并行度高。</li></ul>\n<h5>3. 读写流程（为什么需要那么多时序）</h5>\n<ol><li><b>激活（ACT）</b>：选中一行（Row），把整行复制到 Sense Amplifier（感应放大器）。</li>\n<li><b>列读写</b>：在激活的行中按列（Column）读/写数据。</li>\n<li><b>预充电（PRE）</b>：写回并关闭该行，为下次访问准备。</li></ol>\n<p>这三个动作对应时序：<code>tRCD</code>（激活到读）、<code>CL</code>（读到数据）、<code>tRP</code>（预充电）、<code>tRAS</code>（激活保持最小时间）。</p>\n<h5>4. 刷新（Refresh）</h5>\n<p>因为电容漏电，必须每 64ms（高温更频繁）把每行重写一遍。刷新期间该 Bank 不能正常读写，这就是 <code>tRFC</code>/<code>tREFI</code> 的来源。DDR5 支持 per-bank 刷新，刷新干扰更小。</p>\n<div class=\"tip\">💡 FAE 理解重点：所有内存\"玄学\"故障的根源都在这里——时序太紧 → 数据没写稳 → 偶发错误；温度高 → 漏电快 → 同样参数更容易出错。</div>"}, {"title": "产品线认知：UDIMM/SODIMM/RDIMM + 存储全家桶", "html": "<h5>1. 内存模组四大形态（FAE 必须一眼分清）</h5>\n<table><tr><th>形态</th><th>全称</th><th>用在哪儿</th><th>特点</th></tr>\n<tr><td><b>UDIMM</b></td><td>Unbuffered DIMM 无缓冲</td><td>台式机</td><td>最常见；288pin（D4/D5）</td></tr>\n<tr><td><b>SODIMM</b></td><td>Small Outline DIMM 小型</td><td>笔记本/迷你主机</td><td>小尺寸；DDR4=260pin、DDR5=262pin</td></tr>\n<tr><td><b>RDIMM</b></td><td>Registered DIMM 带寄存器</td><td>服务器</td><td>有RCD芯片，可挂更多Rank/更大容量，需服务器主板</td></tr>\n<tr><td><b>LRDIMM</b></td><td>Load Reduced DIMM</td><td>高端服务器</td><td>带数据缓冲，容量更大</td></tr></table>\n<p>注意：<b>RDIMM 外观和 UDIMM 不一样</b>（PCB 上有 RCD 芯片），插到普通台式机主板上不识别——这是常见客诉场景之一。</p>\n<h5>2. 存储产品全家桶（汇钜业务全景）</h5>\n<ul><li><b>SSD 固态硬盘</b>：M.2 SATA / M.2 PCIe / 2.5寸 SATA / mSATA——按接口和协议分，速度差异大；</li>\n<li><b>PSSD 移动固态</b>：Type-C 接口便携硬盘；</li>\n<li><b>嵌入式存储</b>：\n  <ul><li><b>eMMC</b>：手机/平板的闪存，焊在主板上；</li>\n  <li><b>UFS</b>：新一代手机闪存，比 eMMC 快；</li>\n  <li><b>LPDDR4X/5X</b>：低功耗内存，手机平板用；</li>\n  <li><b>eMCP</b>：eMMC（闪存）+ LPDDR（内存）融合封装在一个芯片里；</li>\n  <li><b>uMCP</b>：UFS + LPDDR 融合封装版本。</li></ul></li></ul>\n<h5>3. FAE 为什么要知道产品全貌</h5>\n<p>客户可能从一条内存问到整套存储方案。你能讲清楚\"UDIMM 和 RDIMM 的区别、SSD 和 UFS 是什么\"，客户才会信任你在内存问题上也专业。</p>\n<div class=\"tip\">💡 记忆口诀：DIMM 按\"缓冲\"分 UDIMM（无）/RDIMM（有）；按\"大小\"分 DIMM（台式）/SODIMM（笔记本）；嵌入式看接口（eMMC/UFS）和融合（eMCP/uMCP）。</div>"}, {"title": "CPU-Z：Memory 页和 SPD 页怎么看", "html": "<h5>1. CPU-Z 是什么</h5>\n<p>CPUID 出的免费硬件检测工具，能读出 CPU/主板/内存的详细信息。FAE 用它做三件事：<b>核实内存身份、核实时序、确认频率</b>。</p>\n<h5>2. Memory 页（看\"实际运行状态\"）</h5>\n<ul><li><b>Type</b>：DDR4 还是 DDR5；</li>\n<li><b>Channel #</b>：Single/Dual/Quad——单通道还是双通道（性能差一倍）；</li>\n<li><b>DRAM Frequency</b>：实际运行频率（注意：DDR 显示的是时钟频率，实际带宽=×2，如显示 3000 = DDR4-6000？不——CPU-Z 显示的 DRAM Frequency 是实际时钟，DDR4-3200 显示 1600MHz）；</li>\n<li><b>FSB:DRAM</b>：内存与总线比例；</li>\n<li><b>CL/tRCD/tRP/tRAS</b>：当前实际时序（开了 XMP 会显示 XMP 档时序）。</li></ul>\n<h5>3. SPD 页（看\"条子身份\"）</h5>\n<ul><li><b>Memory Slot Selection</b>：选中插槽，看该条 SPD；</li>\n<li><b>Module Size</b>：容量；<b>Max Bandwidth</b>：标称最高带宽（如 DDR4-3200 = PC4-25600）；</li>\n<li><b>Manufacturer / Part Number</b>：厂商和型号——对比标签；</li>\n<li><b>Timings Table</b>：频率档位对应的时序矩阵（JEDEC 档 + XMP 档）；</li>\n<li><b>XMP/EXPO 档</b>：如果有额外 Profile 会显示更高频率及时序。</li></ul>\n<h5>4. FAE 实操四步（今天完成）</h5>\n<ol><li>下载安装 CPU-Z（官网 cpuid.com）；</li>\n<li>打开 Memory 页，截图当前频率/通道/时序；</li>\n<li>打开 SPD 页，截图条子容量/型号/时序矩阵；</li>\n<li>对照答：我的条子标称多少？实际跑多少？开没开 XMP？</li></ol>\n<div class=\"warn\">⚠️ 常见坑：客户报\"内存频率只有 1600\"——其实是 CPU-Z 显示的时钟频率（1600MHz=DDR4-3200 等效）。看频率时先确认是不是忘了 ×2。</div>"}, {"title": "读 HOGE 产品 Datasheet：找到 4 个关键页", "html": "<h5>1. 拿到 Datasheet 先看什么（FAE 焦点）</h5>\n<p>一份模组 Datasheet 几十页，FAE 只需要快速锁定 4 类关键信息：<b>容量、速率、电压、时序</b>。</p>\n<h5>2. 四个关键页速查</h5>\n<table><tr><th>关键信息</th><th>通常在哪个章节</th><th>FAE 怎么用</th></tr>\n<tr><td><b>容量/配置</b></td><td>Product Description / Ordering</td><td>核对客户订单型号=多少GB、1R/2R、x8/x16</td></tr>\n<tr><td><b>速率档位</b></td><td>Speed Grades 表</td><td>确认支持 DDR5-4800/5600/6000 哪几档</td></tr>\n<tr><td><b>电压</b></td><td>Electrical Characteristics</td><td>DDR5 1.1V / VPP 1.8V；漏标电压会误判供电问题</td></tr>\n<tr><td><b>时序表</b></td><td>Timing Parameters</td><td>各速率档对应的 CL/tRCD/tRP/tRAS 参考值</td></tr></table>\n<h5>3. 实操动作（今天就要做）</h5>\n<ol><li>从公司知识库下载 1 份 HOGE 内存 Datasheet；</li>\n<li>用 Ctrl+F 搜 \"Speed\"、\"Voltage\"、\"Timing\" 定位章节；</li>\n<li>把\"型号→容量→速率档→电压→时序\"抄成一张速查卡；</li>\n<li>对照一条实物/标签验证：标签上的型号能否在 Datasheet 找到对应参数。</li></ol>\n<h5>4. 读时序表的技巧</h5>\n<p>时序表通常是\"速率档 × 时序参数\"的矩阵：行=频率（4800/5200/5600…），列=CL/tRCD/tRP/tRAS/tRFC。查\"标称档位的时序\"用来对照 CPU-Z 实测——实测时序比表格紧说明开了 XMP，比表格松说明降频了。</p>\n<div class=\"tip\">💡 FAE 面试/考核经典题：\"拿一根条子你能说出它的规格吗？\"答案就在 Datasheet 四个关键页里。</div>"}], "out": "\"内存原理一页纸\"笔记 + CPU-Z 截图归档"}, {"id": "d2", "title": "DDR4 vs DDR5 系统对比", "date": "Day 2 · 周二", "dot": "2", "tasks": ["电压：DDR4 1.2V vs DDR5 1.1V，功耗差异与信号裕量", "速率：DDR4-2133~3200 vs DDR5-4800~6400（JEDEC标准），超过JEDEC的如7200/8000多为XMP/EXPO超频表现；预取16n vs 8n、BL16", "信道架构：DDR5 单条=2个32bit通道（非ECC），DDR4 单条=1个64bit通道", "架构升级点：DDR5 突发长度 BL16（D4=BL8）、Bank Groups 8组（D4=4组）、片内ECC（ODECC，注意≠服务器RDIMM的ECC）", "Gear1 / Gear2：内存控制器与内存频率比值（Gear1=1:1 低延迟；Gear2=2:1 可冲高频；DDR5 平台常用 Gear2）", "向同事/导师口述一遍 D4/D5 三大差异"], "tools": "JEDEC JESD79-4/JESD79-5 对比、产品规格书", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1V8411o7XA", "label": "▶ DDR4和DDR5内存能混用吗？（电脑装机馆 · 4.1万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1ue12YKENw", "label": "▶ 笔记本DDR4和DDR5有什么区别（海滨稻香 · 7100播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/DDR5_SDRAM", "label": "📄 维基百科·DDR5 SDRAM"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/DDR4_SDRAM", "label": "📄 维基百科·DDR4 SDRAM"}], "lectures": [{"title": "DDR4 vs DDR5 全面对比", "html": "<h5>1. 核心参数对比表</h5>\n<table><tr><th>项目</th><th>DDR4</th><th>DDR5</th></tr>\n<tr><td>标准电压 VDD</td><td>1.2V</td><td>1.1V</td></tr>\n<tr><td>速率（JEDEC）</td><td>2133~3200 MT/s</td><td>4800~6400 MT/s（XMP 可 7200+）</td></tr>\n<tr><td>预取长度</td><td>8n（BL8）</td><td>16n（BL16）</td></tr>\n<tr><td>Bank Groups</td><td>4 组</td><td>8 组（每 2 个 bank group 对应一个 32bit 通道）</td></tr>\n<tr><td>通道架构</td><td>单条 1×64bit</td><td>单条 2×32bit（非ECC）</td></tr>\n<tr><td>电源管理</td><td>主板 VRM 控制</td><td>PMIC 上板（模组自管理 VDD/VDDQ/VPP）</td></tr>\n<tr><td>SPD</td><td>EEPROM（I²C，串行）</td><td>SPD Hub（I3C，速率更高、可级联）</td></tr>\n<tr><td>片内 ECC</td><td>无</td><td>有 on-die ECC（纠颗粒内部偶发位错，≠服务器 RDIMM ECC）</td></tr>\n</table>\n<h5>2. 为什么 DDR5 更快</h5>\n<ul><li>预取 16n 一次拿 16 个数据 → 在相同 I/O 频率下吞吐翻倍；</li>\n<li>BL16 每次突发传输 16 字节（64bit 通道一次突发 16×64bit）；</li>\n<li>片内 ECC 允许内部纠错，为更高频率提供余量。</li></ul>\n<h5>3. 关键架构差异</h5>\n<ul><li><b>PMIC 上板</b>：DDR5 模组自带电源管理芯片，主板不再统一调内存电压；PMIC 坏了 → 整条不工作。</li>\n<li><b>SPD Hub</b>：I3C 总线，支持更高带宽 SPD 读取和温度轮询，也支持多设备连接。</li>\n<li><b>双 32bit 通道</b>：一条 DDR5 相当于内部\"两条通道\"，信道效率更高。</li></ul>\n<div class=\"warn\">⚠️ 注意：DDR5 的\"ECC\"是 on-die ECC，纠的是颗粒内部错误；服务器内存条的 ECC 是系统级纠错（RDIMM），两者不是一回事，别混淆。</div>"}, {"title": "Gear 模式与 XMP/EXPO 补充", "html": "<h5>1. Gear1 / Gear2 到底是什么</h5>\n<p>Gear = 内存控制器（IMC）频率与内存频率的<b>比值</b>。<b>Gear1（1:1）</b>：控制器和内存同频，延迟最低，但高频上不去（DDR4 常见）；<b>Gear2（2:1）</b>：控制器只有内存一半频率，延迟略增但能冲更高频率（DDR5 平台主流）。</p>\n<h5>2. 和客户解释的口吻</h5>\n<p>\"频率上不去不一定是条子问题——CPU 的 IMC 和 Gear 模式共同决定上限。DDR5 默认 Gear2 是为了高频可达，追求极限延迟才手动 Gear1。\"</p>\n<h5>3. XMP vs EXPO 快速区分</h5>\n<table><tr><th>机制</th><th>谁提出的</th><th>用在</th></tr>\n<tr><td>XMP</td><td>Intel</td><td>Intel 平台（DDR4/DDR5）</td></tr>\n<tr><td>EXPO</td><td>AMD</td><td>AMD 平台（DDR5）</td></tr></table>\n<p>本质一样：SPD 里存一组超频预设（频率+时序+电压），BIOS 一键开启。客户说\"开不了 XMP\"先确认平台和 Profile 是否正确。</p>"}], "out": "《D4 vs D5 对比表》（电压/速率/架构/功耗/用途）"}, {"id": "d3", "title": "时序参数：CL/tRCD/tRP/tRAS", "date": "Day 3 · 周三", "dot": "3", "tasks": ["理解 CL（CAS延迟）：读命令发出到数据返回的时钟数，越小延迟越低", "理解 tRCD/tRP/tRAS 三个时序的完整过程（激活→读→预充电）", "理解时序与稳定性关系：时序太紧→不良率上升；时序太松→性能下降", "用 CPU-Z 读本机内存时序，对照 Datasheet 标称值", "常见频率对应时序档位记忆：DDR4-3200 CL16/18/22，DDR5-5600 CL46 等"], "tools": "JEDEC 时序定义、产品Datasheet、CPU-Z Memory页", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1Zd4y1377s", "label": "▶ DDR4时序的作用pt.3: tRP/tRAS（Tacoma213 · 2592播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19h4y1c75g", "label": "▶ Uclk分频·内存时序控制详解（羽人过境 · 4025播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Memory_timing", "label": "📄 维基百科·Memory Timings"}], "lectures": [{"title": "时序参数 CL/tRCD/tRP/tRAS 详解", "html": "<h5>1. 五大时序速查</h5>\n<table><tr><th>时序</th><th>全称</th><th>含义</th><th>大小对性能的影响</th></tr>\n<tr><td><code>CL</code></td><td>CAS Latency</td><td>列选通到数据返回的延时（读命令发出→数据出来）</td><td>越小延迟越低，越激进</td></tr>\n<tr><td><code>tRCD</code></td><td>RAS to CAS Delay</td><td>行激活（ACT）到列读（READ）的间隔</td><td>越小越好</td></tr>\n<tr><td><code>tRP</code></td><td>Row Precharge</td><td>预充电时间（关闭当前行）</td><td>越小越快换行</td></tr>\n<tr><td><code>tRAS</code></td><td>Active to Precharge</td><td>行激活后最少保持时间</td><td><b>不能太小</b>，太小数据来不及写回</td></tr>\n<tr><td><code>tRFC</code></td><td>Refresh Cycle</td><td>一次刷新所需时间</td><td>越大刷新越慢 → 压带宽</td></tr>\n</table>\n<h5>2. 怎么记忆</h5>\n<p>一次完整读操作：<code>ACT 激活行 → 等 tRCD → 发 READ → 等 CL → 数据返回 → 等 tRAS 结束 → PRE 预充电 → 等 tRP → 下一行</code></p>\n<div class=\"tip\">💡 一句话：CL/tRCD/tRP 越小越好但太紧会不稳；tRAS 有下限（约 tRCD+CL），设太小会丢数据；tRFC 影响刷新效率。</div>\n<h5>3. 对稳定性的意义（FAE 必考）</h5>\n<ul><li>时序越紧 → 留给信号建立/保持的时间窗口越小 → 颗粒体质/温度稍差就出错；</li>\n<li>速查卡：CL16-18-18-38 这种\"4 个数字\"常见于 DDR4-3200 高配；JEDEC 默认 DDR4-3200 通常是 CL22。</li></ul>"}, {"title": "CPU-Z：Memory 页和 SPD 页怎么看", "html": "<h5>1. CPU-Z 是什么</h5>\n<p>CPUID 出的免费硬件检测工具，能读出 CPU/主板/内存的详细信息。FAE 用它做三件事：<b>核实内存身份、核实时序、确认频率</b>。</p>\n<h5>2. Memory 页（看\"实际运行状态\"）</h5>\n<ul><li><b>Type</b>：DDR4 还是 DDR5；</li>\n<li><b>Channel #</b>：Single/Dual/Quad——单通道还是双通道（性能差一倍）；</li>\n<li><b>DRAM Frequency</b>：实际运行频率（注意：DDR 显示的是时钟频率，实际带宽=×2，如显示 3000 = DDR4-6000？不——CPU-Z 显示的 DRAM Frequency 是实际时钟，DDR4-3200 显示 1600MHz）；</li>\n<li><b>FSB:DRAM</b>：内存与总线比例；</li>\n<li><b>CL/tRCD/tRP/tRAS</b>：当前实际时序（开了 XMP 会显示 XMP 档时序）。</li></ul>\n<h5>3. SPD 页（看\"条子身份\"）</h5>\n<ul><li><b>Memory Slot Selection</b>：选中插槽，看该条 SPD；</li>\n<li><b>Module Size</b>：容量；<b>Max Bandwidth</b>：标称最高带宽（如 DDR4-3200 = PC4-25600）；</li>\n<li><b>Manufacturer / Part Number</b>：厂商和型号——对比标签；</li>\n<li><b>Timings Table</b>：频率档位对应的时序矩阵（JEDEC 档 + XMP 档）；</li>\n<li><b>XMP/EXPO 档</b>：如果有额外 Profile 会显示更高频率及时序。</li></ul>\n<h5>4. FAE 实操四步（今天完成）</h5>\n<ol><li>下载安装 CPU-Z（官网 cpuid.com）；</li>\n<li>打开 Memory 页，截图当前频率/通道/时序；</li>\n<li>打开 SPD 页，截图条子容量/型号/时序矩阵；</li>\n<li>对照答：我的条子标称多少？实际跑多少？开没开 XMP？</li></ol>\n<div class=\"warn\">⚠️ 常见坑：客户报\"内存频率只有 1600\"——其实是 CPU-Z 显示的时钟频率（1600MHz=DDR4-3200 等效）。看频率时先确认是不是忘了 ×2。</div>"}, {"title": "读 HOGE 产品 Datasheet：找到 4 个关键页", "html": "<h5>1. 拿到 Datasheet 先看什么（FAE 焦点）</h5>\n<p>一份模组 Datasheet 几十页，FAE 只需要快速锁定 4 类关键信息：<b>容量、速率、电压、时序</b>。</p>\n<h5>2. 四个关键页速查</h5>\n<table><tr><th>关键信息</th><th>通常在哪个章节</th><th>FAE 怎么用</th></tr>\n<tr><td><b>容量/配置</b></td><td>Product Description / Ordering</td><td>核对客户订单型号=多少GB、1R/2R、x8/x16</td></tr>\n<tr><td><b>速率档位</b></td><td>Speed Grades 表</td><td>确认支持 DDR5-4800/5600/6000 哪几档</td></tr>\n<tr><td><b>电压</b></td><td>Electrical Characteristics</td><td>DDR5 1.1V / VPP 1.8V；漏标电压会误判供电问题</td></tr>\n<tr><td><b>时序表</b></td><td>Timing Parameters</td><td>各速率档对应的 CL/tRCD/tRP/tRAS 参考值</td></tr></table>\n<h5>3. 实操动作（今天就要做）</h5>\n<ol><li>从公司知识库下载 1 份 HOGE 内存 Datasheet；</li>\n<li>用 Ctrl+F 搜 \"Speed\"、\"Voltage\"、\"Timing\" 定位章节；</li>\n<li>把\"型号→容量→速率档→电压→时序\"抄成一张速查卡；</li>\n<li>对照一条实物/标签验证：标签上的型号能否在 Datasheet 找到对应参数。</li></ol>\n<h5>4. 读时序表的技巧</h5>\n<p>时序表通常是\"速率档 × 时序参数\"的矩阵：行=频率（4800/5200/5600…），列=CL/tRCD/tRP/tRAS/tRFC。查\"标称档位的时序\"用来对照 CPU-Z 实测——实测时序比表格紧说明开了 XMP，比表格松说明降频了。</p>\n<div class=\"tip\">💡 FAE 面试/考核经典题：\"拿一根条子你能说出它的规格吗？\"答案就在 Datasheet 四个关键页里。</div>"}], "out": "时序参数速查卡（含每个时序一句话解释）"}, {"id": "d4", "title": "产品命名规则 + 颗粒规格", "date": "Day 4 · 周四", "dot": "4", "tasks": ["学习 HOGE 模组命名规则：前缀/容量/频率/电压/温度等级/颗粒厂商编码（⚠️ 以公司《产品命名规则》最新版为准）", "学习 DRAM 颗粒命名（⚠️ 型号前缀务必以厂商最新Datasheet为准）：三星 K4A=DDR4（DDR5为K4M/K4R等）、美光 MT40A=DDR4（DDR5为MT60B等）、SK海力士 H5AN=DDR4（DDR5为H5CG等）", "区分 x4/x8/x16 颗粒位宽、单面/双面、1R/2R 的意义", "读懂一条真实模组标签：PN/SN/容量/频率/序列号"], "tools": "公司《产品命名规则》、颗粒厂商Datasheet目录", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1DT421S7Yj", "label": "▶ 内存颗粒有哪些？你用的是哪个级别（陈墨啥都玩 · 29.3万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1PNPTetEak", "label": "▶ 如何快速鉴别自己的内存颗粒（人民的帧数优化师 · 19.0万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1GD6iBxE9d", "label": "▶ 颗粒厂不同也能通用吗（二哈是个拆家能手 · 2.0万播放）"}, {"type": "off", "url": "https://www.samsung.com/us/semiconductor/", "label": "📄 三星半导体官网"}, {"type": "off", "url": "https://www.micron.com/", "label": "📄 美光科技官网"}, {"type": "off", "url": "https://www.skhynix.com/", "label": "📄 SK海力士官网"}], "lectures": [{"title": "HOOE 模组命名 + 三大厂颗粒命名", "html": "<h5>1. DRAM 颗粒命名（三大厂）</h5>\n<p>（⚠️ 具体型号前缀以厂商最新 Datasheet 为准，以下为规律）</p>\n<table><tr><th>厂商</th><th>DDR4 前缀</th><th>DDR5 前缀</th><th>示例解读</th></tr>\n<tr><td>三星 Samsung</td><td>K4A…</td><td>K4M/K4R…</td><td>K4A8G165WC：K4A=DDR4，8G=8Gbit，165=x16，WC=版本</td></tr>\n<tr><td>美光 Micron</td><td>MT40A…</td><td>MT60B…</td><td>MT40A2G4WE：40=DDR4，2G=2Gbit，4=x4</td></tr>\n<tr><td>海力士 SK hynix</td><td>H5AN…</td><td>H5CG…</td><td>H5AN8G6NDJR：H5AN=DDR4，8G=8Gbit，6=x16</td></tr>\n</table>\n<h5>2. 颗粒规格位</h5>\n<ul><li><b>位宽 x4/x8/x16</b>：x8 颗粒 ×8 颗 = 64bit（1Rank）；x16 颗粒 ×4 颗 = 64bit。x4 多用于 RDIMM/服务器。</li>\n<li><b>1R vs 2R</b>：1Rx8 = 8 颗 ×8bit；2Rx8 = 16 颗 ×8bit 分两面。2R 并行度高但 IMC 负载重。</li></ul>\n<h5>3. HOGE 模组命名（⚠️ 以公司《产品命名规则》为准）</h5>\n<p>一般包含：品牌 + 系列 + 容量 + 频率 + 电压等级 + 温级 + 颗粒厂商代码。例如某条 <code>HG 16GB DDR5-5600 UDIMM</code>，字段逐一解析。入职第一周务必向导师要到命名规则文档背熟。</p>\n<div class=\"warn\">⚠️ 命名规则是 FAE 的\"身份证阅读器\"——客户报一个型号，你要能立刻说出容量/频率/颗粒。背不熟会显得很不专业。</div>"}, {"title": "读 HOGE 产品 Datasheet：找到 4 个关键页", "html": "<h5>1. 拿到 Datasheet 先看什么（FAE 焦点）</h5>\n<p>一份模组 Datasheet 几十页，FAE 只需要快速锁定 4 类关键信息：<b>容量、速率、电压、时序</b>。</p>\n<h5>2. 四个关键页速查</h5>\n<table><tr><th>关键信息</th><th>通常在哪个章节</th><th>FAE 怎么用</th></tr>\n<tr><td><b>容量/配置</b></td><td>Product Description / Ordering</td><td>核对客户订单型号=多少GB、1R/2R、x8/x16</td></tr>\n<tr><td><b>速率档位</b></td><td>Speed Grades 表</td><td>确认支持 DDR5-4800/5600/6000 哪几档</td></tr>\n<tr><td><b>电压</b></td><td>Electrical Characteristics</td><td>DDR5 1.1V / VPP 1.8V；漏标电压会误判供电问题</td></tr>\n<tr><td><b>时序表</b></td><td>Timing Parameters</td><td>各速率档对应的 CL/tRCD/tRP/tRAS 参考值</td></tr></table>\n<h5>3. 实操动作（今天就要做）</h5>\n<ol><li>从公司知识库下载 1 份 HOGE 内存 Datasheet；</li>\n<li>用 Ctrl+F 搜 \"Speed\"、\"Voltage\"、\"Timing\" 定位章节；</li>\n<li>把\"型号→容量→速率档→电压→时序\"抄成一张速查卡；</li>\n<li>对照一条实物/标签验证：标签上的型号能否在 Datasheet 找到对应参数。</li></ol>\n<h5>4. 读时序表的技巧</h5>\n<p>时序表通常是\"速率档 × 时序参数\"的矩阵：行=频率（4800/5200/5600…），列=CL/tRCD/tRP/tRAS/tRFC。查\"标称档位的时序\"用来对照 CPU-Z 实测——实测时序比表格紧说明开了 XMP，比表格松说明降频了。</p>\n<div class=\"tip\">💡 FAE 面试/考核经典题：\"拿一根条子你能说出它的规格吗？\"答案就在 Datasheet 四个关键页里。</div>"}], "out": "命名规则速查卡（模组+颗粒两套规则）"}, {"id": "d5", "title": "周复盘 + 口述自测", "date": "Day 5 · 周五", "dot": "5", "tasks": ["整理本周全部笔记，归档到案例库/知识库目录", "口述自测：D4/D5差异 + 时序4个参数 + 命名规则（录音复盘）", "用\"讲授法\"：把本周内容讲给导师/同事听，收集盲点", "完成《12周计划》W1格子的验收点打勾"], "tools": "本周笔记、《00_发展规划》W1验收点", "resources": [], "lectures": [{"title": "周复盘方法论：把一周学到的变成自己的", "html": "<h5>1. 为什么每周五必须复盘</h5>\n<p>学习的本质是\"输入→加工→输出\"。周五复盘的三个动作缺一不可：<b>整理归档（防止遗忘）→ 口述讲解（检验是否真懂）→ 查漏补缺（确定下周方向）</b>。没有复盘的学习，一周后只剩 30%。</p>\n<h5>2. 周复盘四步法（35分钟）</h5>\n<ol><li><b>整理（10分钟）</b>：把本周所有笔记/截图/产出物归入知识库对应目录，编号命名；</li>\n<li><b>口述（15分钟）</b>：对着大纲讲给导师/同事听，重点讲\"为什么\"而不是\"是什么\"；用\"讲授法\"——能讲明白才算学会；</li>\n<li><b>自查（5分钟）</b>：对照《12周计划》本周验收点逐个打勾，标出\"以为会了其实不会\"的知识点；</li>\n<li><b>计划（5分钟）</b>：写下本周 3 个最大收获 + 下周最想突破的 1 件事。</li></ol>\n<h5>3. 口述自测清单（W1 版）</h5>\n<ul><li>DDR4 vs DDR5 差异能讲出 ≥5 条；</li>\n<li>CL/tRCD/tRP/tRAS 各自含义能一句话讲清；</li>\n<li>一眼看懂一条内存标签的容量/频率/时序。</li></ul>\n<div class=\"tip\">💡 口述时手机录音，回放你会发现自己\"以为懂其实讲不通\"的地方——这就是下周要补的。</div>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。</p>\n<h5>2. 每例 <200 字的推荐格式</h5>\n<pre>案例编号：FAE-2026-XXX\n现象：一句话\n平台：主板/CPU/OS/内存型号\n根因：一句话\n证据：日志/截图路径\n对策：临时+永久\n状态：已闭环/复核中</pre>\n<h5>3. 什么案例值得记</h5>\n<ul><li>第一次遇到的故障类型；</li>\n<li>排查过程走弯路的（教训最值钱）；</li>\n<li>证据链完整、能当培训材料的；</li>\n<li>客户高频问题（同问必记）。</li></ul>\n<h5>4. 归档节奏</h5>\n<p>客诉闭环当天顺手记一例（30 秒的事），月底统一补标签和索引。目标：<b>12 周 ≥10 例，一年 ≥30 例</b>。</p>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。</div>"}], "out": "W1周复盘记录 + 笔记归档完成"}]}, {"id": "w2", "badge": "W2", "title": "产品硬件结构：物理拆解 + 器件认知 + 制程瑕疵", "sub": "阶段 P1 · 把知识焊到实物上", "accept": "能对着实物指出各器件并说明作用，识别金手指/颗粒外观不良。", "tools": "实物拆解、颗粒Datasheet、PCB叠层资料", "phase": "P1", "weekend": "周末加油站：观察家里电脑内存插拔方向与锁定结构；阅读《JEDEC DDR4 模组外形规范》金手指部分； 可选：学习 RDIMM 上 RCD（寄存器）的用途，为后续服务器场景打底", "days": [{"id": "d6", "title": "内存条拆解总览", "date": "Day 6 · 周一", "dot": "1", "tasks": ["实物拆解：找到 DRAM 颗粒、SPD EEPROM/SPD Hub、PMIC、金手指、热敏电阻、标签", "对照 Datasheet 认识 PCB 上的主要走线区域（数据、地址、电源）", "拍摄拆解照片并标注每个器件名称与作用（存档）", "学习金手指引脚：UDIMM/RDIMM 都是 288pin（DDR4/DDR5）；SODIMM 是 DDR4=260pin、DDR5=262pin，注意缺口位置防插错"], "tools": "实物内存条、拆解视频、产品规格书", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV18t421L7oa", "label": "▶ 笔记本加内存条·拆装方法（想想3c数码 · 18.7万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1zp411f7h2", "label": "▶ 内存条的拆装（KOTIN京天售后 · 4.3万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1G2dhBmESw", "label": "▶ 学会看内存条出厂日期（政雨Rich · 2.8万播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/DIMM", "label": "📄 维基百科·DIMM"}], "lectures": [{"title": "内存条拆解与器件识别", "html": "<h5>1. 内存条上的主要器件</h5>\n<ul><li><b>DRAM 颗粒（黑色方块）</b>：数据的家。排成 8/9/18 颗（x8 ECC 会多一颗）。</li>\n<li><b>SPD EEPROM（DDR4）或 SPD Hub（DDR5）</b>：小芯片，存容量/时序/厂商信息，主板开机读取。</li>\n<li><b>PMIC（DDR5 才有板载）</b>：电源管理芯片，产生 VDD/VDDQ/VPP。</li>\n<li><b>金手指（edge fingers）</b>：与插槽接触的镀金引脚，288pin（DIMM）/260pin（DDR4 SODIMM）/262pin（DDR5 SODIMM）。</li>\n<li><b>热敏电阻（TS）</b>：温度传感器，DDR5 温控降频依据。</li>\n<li><b>标签</b>：型号/PN/SN/容量/频率/电压 等身份信息。</li></ul>\n<h5>2. 引脚数速记</h5>\n<table><tr><th>类型</th><th>DDR4</th><th>DDR5</th></tr>\n<tr><td>UDIMM/RDIMM（台式/服务器）</td><td>288</td><td>288</td></tr>\n<tr><td>SODIMM（笔记本）</td><td>260</td><td>262</td></tr></table>\n<div class=\"tip\">💡 引脚数不同 + 缺口位置不同，DDR4/DDR5 物理上无法混插——这也是客诉中\"插不进去/点不亮\"的最初排查点。</div>"}, {"title": "读 HOGE 产品 Datasheet：找到 4 个关键页", "html": "<h5>1. 拿到 Datasheet 先看什么（FAE 焦点）</h5>\n<p>一份模组 Datasheet 几十页，FAE 只需要快速锁定 4 类关键信息：<b>容量、速率、电压、时序</b>。</p>\n<h5>2. 四个关键页速查</h5>\n<table><tr><th>关键信息</th><th>通常在哪个章节</th><th>FAE 怎么用</th></tr>\n<tr><td><b>容量/配置</b></td><td>Product Description / Ordering</td><td>核对客户订单型号=多少GB、1R/2R、x8/x16</td></tr>\n<tr><td><b>速率档位</b></td><td>Speed Grades 表</td><td>确认支持 DDR5-4800/5600/6000 哪几档</td></tr>\n<tr><td><b>电压</b></td><td>Electrical Characteristics</td><td>DDR5 1.1V / VPP 1.8V；漏标电压会误判供电问题</td></tr>\n<tr><td><b>时序表</b></td><td>Timing Parameters</td><td>各速率档对应的 CL/tRCD/tRP/tRAS 参考值</td></tr></table>\n<h5>3. 实操动作（今天就要做）</h5>\n<ol><li>从公司知识库下载 1 份 HOGE 内存 Datasheet；</li>\n<li>用 Ctrl+F 搜 \"Speed\"、\"Voltage\"、\"Timing\" 定位章节；</li>\n<li>把\"型号→容量→速率档→电压→时序\"抄成一张速查卡；</li>\n<li>对照一条实物/标签验证：标签上的型号能否在 Datasheet 找到对应参数。</li></ol>\n<h5>4. 读时序表的技巧</h5>\n<p>时序表通常是\"速率档 × 时序参数\"的矩阵：行=频率（4800/5200/5600…），列=CL/tRCD/tRP/tRAS/tRFC。查\"标称档位的时序\"用来对照 CPU-Z 实测——实测时序比表格紧说明开了 XMP，比表格松说明降频了。</p>\n<div class=\"tip\">💡 FAE 面试/考核经典题：\"拿一根条子你能说出它的规格吗？\"答案就在 Datasheet 四个关键页里。</div>"}], "out": "标注版拆解照片（器件名称+作用）"}, {"id": "d7", "title": "DRAM 颗粒特性（三星/美光/海力士）", "date": "Day 7 · 周二", "dot": "2", "tasks": ["学习三大颗粒厂产品线：DDR4/DDR5 各自主流颗粒型号、速率档", "读懂颗粒 Datasheet 中的时序表、ODT 配置、刷新参数", "认识颗粒等级：商业级/工业级/车规级温度范围差异", "实战：认出一根真实模组上的颗粒厂商与型号，解析规格"], "tools": "三星/美光/海力士 Datasheet、颗粒实物照片", "resources": [], "lectures": [{"title": "三大厂 DRAM 颗粒深度对比", "html": "<h5>1. 为什么我们必须懂颗粒</h5>\n<p>内存条的核心就是颗粒。FAE 看一条条子的第一件事：<b>什么颗粒？几代？什么速度等级？</b>颗粒决定了条子的上限体质，也决定了超频能力和故障模式。</p>\n<h5>2. 三大厂主流颗粒谱系</h5>\n<table><tr><th>厂商</th><th>DDR4 代表</th><th>DDR5 代表</th><th>特性</th></tr>\n<tr><td>三星 Samsung</td><td>K4A8G165WC（8Gb x16）</td><td>K4M/K4R 系列（16Gb 起）</td><td>密度高、兼容性好</td></tr>\n<tr><td>美光 Micron</td><td>MT40A2G4（2Gb x4）等</td><td>MT60B 系列（16/24Gb）</td><td>低功耗表现好</td></tr>\n<tr><td>海力士 SK hynix</td><td>H5AN8G6NDJR（8Gb x16）</td><td>H5CG 系列（16Gb 起）</td><td>超频体质常更好</td></tr></table>\n<p>（⚠️ 型号前缀以厂商最新 Datasheet 为准；上面用于建立手感）</p>\n<h5>3. 颗粒规格位怎么读</h5>\n<ul><li><b>容量</b>：8Gbit / 16Gbit 指单颗容量，16Gb 颗 ×8 颗 = 16GB（1Rx8 非ECC）</li>\n<li><b>位宽 x4/x8/x16</b>：x8 颗粒×8颗=64bit 一 Rank；x16 颗粒×4颗=64bit（笔记本常见）</li>\n<li><b>速率档/时序表</b>：Datasheet 里查对应频率下的 CL/tRCD/tRP 参考值，是超频/稳定性判断基准</li></ul>\n<h5>4. 颗粒等级与温度范围</h5>\n<p>商业级（0~85℃ 结温）/ 工业级（-40~95℃）/ 车规级（-40~105℃+）。客诉\"高温死机\"先查用的是哪个等级颗粒、环境温度有没有超规格。</p>\n<div class=\"tip\">💡 颗粒 Datasheet 是 FAE 的工具书，学会查\"时序表+温度范围\"这两页，客诉 80% 的场景都能用上。</div>"}, {"title": "读 HOGE 产品 Datasheet：找到 4 个关键页", "html": "<h5>1. 拿到 Datasheet 先看什么（FAE 焦点）</h5>\n<p>一份模组 Datasheet 几十页，FAE 只需要快速锁定 4 类关键信息：<b>容量、速率、电压、时序</b>。</p>\n<h5>2. 四个关键页速查</h5>\n<table><tr><th>关键信息</th><th>通常在哪个章节</th><th>FAE 怎么用</th></tr>\n<tr><td><b>容量/配置</b></td><td>Product Description / Ordering</td><td>核对客户订单型号=多少GB、1R/2R、x8/x16</td></tr>\n<tr><td><b>速率档位</b></td><td>Speed Grades 表</td><td>确认支持 DDR5-4800/5600/6000 哪几档</td></tr>\n<tr><td><b>电压</b></td><td>Electrical Characteristics</td><td>DDR5 1.1V / VPP 1.8V；漏标电压会误判供电问题</td></tr>\n<tr><td><b>时序表</b></td><td>Timing Parameters</td><td>各速率档对应的 CL/tRCD/tRP/tRAS 参考值</td></tr></table>\n<h5>3. 实操动作（今天就要做）</h5>\n<ol><li>从公司知识库下载 1 份 HOGE 内存 Datasheet；</li>\n<li>用 Ctrl+F 搜 \"Speed\"、\"Voltage\"、\"Timing\" 定位章节；</li>\n<li>把\"型号→容量→速率档→电压→时序\"抄成一张速查卡；</li>\n<li>对照一条实物/标签验证：标签上的型号能否在 Datasheet 找到对应参数。</li></ol>\n<h5>4. 读时序表的技巧</h5>\n<p>时序表通常是\"速率档 × 时序参数\"的矩阵：行=频率（4800/5200/5600…），列=CL/tRCD/tRP/tRAS/tRFC。查\"标称档位的时序\"用来对照 CPU-Z 实测——实测时序比表格紧说明开了 XMP，比表格松说明降频了。</p>\n<div class=\"tip\">💡 FAE 面试/考核经典题：\"拿一根条子你能说出它的规格吗？\"答案就在 Datasheet 四个关键页里。</div>"}, {"title": "ODT 端接电阻带来的信号质量", "html": "<h5>1. ODT（On-Die Termination）是什么</h5>\n<p>ODT 是<b>做在颗粒内部的端接电阻</b>（终结电阻），用来吸收信号在传输线末端的反射、保持信号完整性。传统方案要在主板上布一排终结电阻，DDR4/DDR5 直接内置到 Die 里，还支持动态开关——这就是名字里 \"On-Die\" 的含义。</p>\n<h5>2. ODT 的三个参数（BIOS 里常缩写 RTT_*）</h5>\n<table><tr><th>参数</th><th>全称含义</th><th>作用</th></tr>\n<tr><td>RTT_NOM</td><td>正常运行时的端接阻值</td><td>读写数据时匹配总线阻抗，吸收反射</td></tr>\n<tr><td>RTT_WR</td><td>写入期间的动态端接</td><td>写操作瞬间切换的阻值（动态模式）</td></tr>\n<tr><td>RTT_PARK</td><td>空闲（Park）时端接</td><td>颗粒不工作时的保持阻值，防浮动</td></tr></table>\n<p>阻值档位一般是 34Ω/40Ω/48Ω/60Ω/80Ω/120Ω/240Ω 等（DDR5 还新增基于训练的自适应）——选错档 = 阻抗失配 = 反射变差。</p>\n<h5>3. 为什么 FAE 必须知道 ODT</h5>\n<ul><li>ODT 阻值需要与<b>主板板级阻抗 + 颗粒特性 + 频率</b>匹配，BIOS 通常自动配置，但排障时要能想到它；</li>\n<li>配置不对的典型表现：<b>低频没事、高频偶尔错</b>（反射在高速下才致命）、单条稳定 vs 多插不稳（动态端接数量变化）；</li>\n<li>颗粒 Datasheet 有 ODT 推荐表：同型号颗粒在不同 Rank 组合下的建议 RTT，查表可核对 BIOS 是否给歪了。</li></ul>\n<h5>4. 排障实战：什么时候怀疑 ODT</h5>\n<p>同一规格条子在 A 主板稳定、B 主板偶发错误 → 除 IMC/散热/BIOS 微码外，<b>ODT 训练结果差异</b>也是方向。排查动作：</p>\n<ol><li>先看 BIOS 是否\"Auto ODT\"/\"Memory Training\"——先恢复默认/开启自动训练再测；</li><li>用 BIOS 手动项对比（RTT_NOM/PARK 各尝试一档）看是否变化；</li><li>记录平台差异：Intel/AMD 对 ODT 的默认策略不同，AMD EXPO 与 Intel XMP 加载的参数也不同；</li><li>同条子在两台机器 A/B 交叉复测，确认是\"条子 vs 平台配合\"问题而非单条损坏。</li></ol>\n<div class=\"tip\">💡 一句话定位：ODT 问题通常\"换平台就好、复测偶发、与频率强相关\"——别一上来就说条子坏，先排除平台侧训练/端接差异。</div>"}], "out": "三大厂颗粒型号速查表"}, {"id": "d8", "title": "SPD EEPROM / SPD Hub / PMIC", "date": "Day 8 · 周三", "dot": "3", "tasks": ["理解 SPD 作用：存储容量/频率/时序/厂商信息，主板开机第一步读取", "DDR4 EEPROM（I2C） vs DDR5 SPD Hub（I3C）：总线与安全升级", "理解 PMIC 作用（DDR5 板载）：VDD/VDDQ/VPP 供电，主板上不再统一管理", "认识热敏电阻（TS）：DDR5 温控的基础，过热降频依据", "用 CPU-Z SPD 页读取一根条子的 SPD 内容并解读"], "tools": "JEDEC SPD 规范、CPU-Z SPD页、实物照片", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV113411i7eS", "label": "▶ 简谈内存SPD、刷写XMP（吗吗哈哈 · 8625播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1r8zTBWExD", "label": "▶ DIMM？CUDIMM？类型区别（TFLASH-DIY · 7975播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Serial_presence_detect", "label": "📄 维基百科·SPD"}, {"type": "off", "url": "https://www.jedec.org/", "label": "📄 JEDEC 标准官网"}], "lectures": [{"title": "SPD / EEPROM / SPD Hub / PMIC 详解", "html": "<h5>1. SPD 是什么</h5>\n<p>SPD（Serial Presence Detect）是模组上保存内存\"身份证\"的存储区：容量、频率、时序表、厂商、SN、XMP/EXPO 参数等。主板开机第一步就是读 SPD，才知道怎么配置内存。</p>\n<h5>2. DDR4 EEPROM vs DDR5 SPD Hub</h5>\n<table><tr><th>项目</th><th>DDR4 EEPROM</th><th>DDR5 SPD Hub</th></tr>\n<tr><td>总线</td><td>I²C（SMBus 兼容）</td><td>I3C（更快、支持多设备组网）</td></tr>\n<tr><td>功能</td><td>只读 SPD 数据</td><td>SPD + 温度轮询 + 安全防护 + 可级联多个 Hub</td></tr>\n<tr><td>失效影响</td><td>不识别/容量错</td><td>不识别/容量错/温度读取失败</td></tr></table>\n<h5>3. PMIC（DDR5）</h5>\n<p>PMIC 在模组上产生三路电压：<code>VDD=1.1V</code>（核心）、<code>VDDQ=1.1V</code>（I/O）、<code>VPP=1.8V</code>（字线）。PMIC 坏 → 供电异常 → 整条不稳定/不识别。用万用表测金手指供电脚可快速验证。</p>\n<div class=\"warn\">⚠️ 客诉中\"SPD 问题\"很常见：刷坏 SPD、SPD 数据与实物不符（标 5600 实际写 4800）、SPD 丢失 → 容量错/频率不对。判定要导出 SPD 二进制与标准模板比对。</div>"}, {"title": "CPU-Z：Memory 页和 SPD 页怎么看", "html": "<h5>1. CPU-Z 是什么</h5>\n<p>CPUID 出的免费硬件检测工具，能读出 CPU/主板/内存的详细信息。FAE 用它做三件事：<b>核实内存身份、核实时序、确认频率</b>。</p>\n<h5>2. Memory 页（看\"实际运行状态\"）</h5>\n<ul><li><b>Type</b>：DDR4 还是 DDR5；</li>\n<li><b>Channel #</b>：Single/Dual/Quad——单通道还是双通道（性能差一倍）；</li>\n<li><b>DRAM Frequency</b>：实际运行频率（注意：DDR 显示的是时钟频率，实际带宽=×2，如显示 3000 = DDR4-6000？不——CPU-Z 显示的 DRAM Frequency 是实际时钟，DDR4-3200 显示 1600MHz）；</li>\n<li><b>FSB:DRAM</b>：内存与总线比例；</li>\n<li><b>CL/tRCD/tRP/tRAS</b>：当前实际时序（开了 XMP 会显示 XMP 档时序）。</li></ul>\n<h5>3. SPD 页（看\"条子身份\"）</h5>\n<ul><li><b>Memory Slot Selection</b>：选中插槽，看该条 SPD；</li>\n<li><b>Module Size</b>：容量；<b>Max Bandwidth</b>：标称最高带宽（如 DDR4-3200 = PC4-25600）；</li>\n<li><b>Manufacturer / Part Number</b>：厂商和型号——对比标签；</li>\n<li><b>Timings Table</b>：频率档位对应的时序矩阵（JEDEC 档 + XMP 档）；</li>\n<li><b>XMP/EXPO 档</b>：如果有额外 Profile 会显示更高频率及时序。</li></ul>\n<h5>4. FAE 实操四步（今天完成）</h5>\n<ol><li>下载安装 CPU-Z（官网 cpuid.com）；</li>\n<li>打开 Memory 页，截图当前频率/通道/时序；</li>\n<li>打开 SPD 页，截图条子容量/型号/时序矩阵；</li>\n<li>对照答：我的条子标称多少？实际跑多少？开没开 XMP？</li></ol>\n<div class=\"warn\">⚠️ 常见坑：客户报\"内存频率只有 1600\"——其实是 CPU-Z 显示的时钟频率（1600MHz=DDR4-3200 等效）。看频率时先确认是不是忘了 ×2。</div>"}, {"title": "热敏电阻 TS：DDR5 温控的\"体温计\"", "html": "<h5>1. 热敏电阻（TS / Thermal Sensor）作用</h5>\n<p>DDR5 模组上有一颗（或多颗）<b>温度传感器 TS（Thermal Sensor）</b>，通过 I3C/SPD Hub 向系统上报颗粒温度，是<b>温控降频（Thermal Throttling）的依据</b>——温度逼近阈值时，系统可主动降低内存频率/放宽时序保护芯片。</p>\n<h5>2. 能读到哪些数据（HWiNFO64 实操）</h5>\n<ul><li>打开 HWiNFO64 → Sensors 面板 → 找 <b>DIMM Thermal Sensor / Memory Module Temperature</b>；</li>\n<li>每条 DIMM 通常独立一个读数，部分还带 <b>累计工作时间（TS 自带计时器）</b>；</li>\n<li>同一位置可对比：待机 vs 满载（AIDA64 Cache&Memory / 压力测试）温度差，正常 10~25℃。</li></ul>\n<h5>3. 温度阈值参考（DDR5 商用级颗粒）</h5>\n<table><tr><th>区间</th><th>含义</th><th>建议动作</th></tr>\n<tr><td>&lt; 70℃</td><td>正常</td><td>无需处理</td></tr>\n<tr><td>70~85℃</td><td>偏高</td><td>检查风道/马甲贴合，记录趋势</td></tr>\n<tr><td>85~95℃</td><td>警戒</td><td>降频/停机风险，查散热贴装</td></tr>\n<tr><td>&gt; 95℃</td><td>危险</td><td>可能触发降频/不稳定，立即排查</td></tr></table>\n<p>⚠️ 具体上限以颗粒 Datasheet 的 Tj（结温）规格为准（商业级一般 0~85℃，工业级更高），不同颗粒/密度有差异，别拿一张表套所有型号。</p>\n<h5>4. 客诉价值：“高温死机/降速”怎么接</h5>\n<ul><li>客户报高温死机 → 要求 HWiNFO64 抓 DIMM 温度曲线 + 故障时间点；</li>\n<li><b>散热片（马甲）贴装不良 / 导热垫缺失 / 贴歪</b> → TS 读数异常偏高（同负载比其他条高 15℃+）；</li>\n<li>降频保护被触发 → 性能异常——要能区分“主动降频（温度高）”与“颗粒异常发热（电流大/早期失效）”；</li>\n<li>TS 曲线也是 NTF 偶发问题的重要环境证据：录下 30 分钟曲线，故障点温度是否超限一目了然。</li></ul>\n<h5>5. 判断动作清单</h5>\n<p>①查 Datasheet 温度范围 → ②对比故障时间点温度曲线 → ③检查散热贴装（马甲/导热垫/厚度） → ④必要时做高低温箱复现（55℃/85℃ 温区看差异）。</p>\n<div class=\"tip\">💡 考核点：能在 HWiNFO 里 10 秒内找到 DIMM 温度并读得懂的人，才配聊“高温客诉”。</div>"}], "out": "SPD/PMIC 工作原理笔记 + CPU-Z SPD 截图"}, {"id": "d9", "title": "PCB 层数与走线", "date": "Day 9 · 周四", "dot": "4", "tasks": ["学习 PCB 层数概念：常见 8/10/16 层，层数对信号完整性影响", "认识走线：等长走线保证 DQS/DQ 同步、蛇形线补偿", "学习生产工艺：贴片、回流焊、点胶、测试流程、常见制程瑕疵", "认识常见外观不良：金手指氧化/划伤、颗粒崩角/鼓包、虚焊、PCB翘曲"], "tools": "PCB叠层资料、生产工艺流程图、不良品图库", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1mM4y1e72g", "label": "▶ PCB走线的串扰很难理解吗（JT硬件乐趣 · 9.2万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1d1421X7yd", "label": "▶ 高速信号如何走线·规则（凡亿教育 · 2.0万播放）"}], "lectures": [{"title": "PCB 层数 / 走线 / 制程瑕疵", "html": "<h5>1. 为什么 PCB 层数重要</h5>\n<p>内存条 PCB 常见 8/10/16 层。层数多 → 信号层/电源层分离好 → 信号完整性（SI）更好，能支持更高频率。DDR5-6400+ 的条子普遍层数更多。</p>\n<h5>2. 走线概念</h5>\n<ul><li><b>等长走线</b>：DQ/DQS 等信号要走同样长，保证同组信号同时到达 → 蛇形线补偿。</li>\n<li><b>差分对</b>：DQS（数据选通）等差分信号两条线并行走，抗干扰强。</li>\n<li><b>电源层/地层</b>：完整平面，减少噪声与串扰。</li></ul>\n<h5>3. 常见制程瑕疵（外观检查必会）</h5>\n<ul><li>金手指氧化/划伤/掉点 → 接触不良、点不亮；</li>\n<li>颗粒鼓包/崩角/开裂 → 存储失效；</li>\n<li>虚焊（颗粒引脚或电阻电容）→ 偶发不稳定；</li>\n<li>PCB 翘曲 → 插槽接触不均；</li>\n<li>标签贴错/印刷错误 → 信息混乱（客诉重灾区）。</li></ul>\n<div class=\"tip\">💡 FAE 现场第一步就是\"外观检查\"：用放大镜/手电看金手指和颗粒，很多问题一眼就能定性。</div>"}, {"title": "生产工艺与回流焊常见问题", "html": "<h5>1. 内存条生产主要工序（知道每步会出什么不良）</h5>\n<p>来料检验 → 烘烤除湿 → 锡膏印刷 → 贴片（SMT 贴颗粒/电容/SPD/PMIC）→ <b>回流焊</b>（加热熔锡固定）→ AOI 光学检测 → X-ray（必要时）→ 点胶加固 → 分板 → 功能测试（ATE/老化）→ 贴标签包装。</p>\n<h5>2. 回流焊温区曲线（FAE 至少要懂概念）</h5>\n<p>典型无铅曲线分四段：<b>预热（升温）→ 保温（活化助焊剂）→ 回流（峰值 235~250℃，熔锡润湿）→ 冷却</b>。曲线偏差是很多焊接类不良的根源：峰值不足→虚焊；升温过陡→冷焊/立碑；冷却过快→焊点应力裂纹。</p>\n<h5>3. 焊接类不良对照表（成因 → 现场特征）</h5>\n<table><tr><th>不良</th><th>机理</th><th>现场/测试特征</th></tr>\n<tr><td><b>虚焊</b></td><td>锡膏不足/曲线不佳，引脚未完全润湿</td><td>偶发不稳定、敲击/晃动触发、温度升高变差、换槽可能好转</td></tr>\n<tr><td><b>桥连</b></td><td>相邻引脚锡连</td><td>短路：上电异常、发热、直接不开机</td></tr>\n<tr><td><b>立碑/偏移</b></td><td>贴装偏移、回流应力不平衡</td><td>开路/接触不良，外观可见</td></tr>\n<tr><td><b>冷焊</b></td><td>回流温度不足/时间太短</td><td>焊点灰暗无光泽，振动后可能失效</td></tr>\n<tr><td><b>锡球</b></td><td>锡膏喷溅/污染</td><td>潜在短路风险，X-ray 可见</td></tr>\n<tr><td><b>焊点空洞</b></td><td>助焊剂排气残留</td><td>高功率下过热，可靠性隐患，X-ray 可见</td></tr></table>\n<h5>4. X-ray 与 AOI 检查（FAE 怎么用）</h5>\n<p>AOI 看表面（缺件/偏移/桥连），<b>X-ray 看内部</b>（BGA 焊球空洞、虚焊）。FAE 遇到疑焊接不良时：先请客户拍外观微距，必要时内部用 X-ray 复查——\"焊点空洞 X% 以内\"有行业标准可对照。</p>\n<h5>5. 与客诉的关联（FAE 判定链）</h5>\n<p>虚焊类不良的<b>三连特征</b>：<b>敲击/晃动可能触发、温度升高变差、特定插槽/特定位置复现</b>。对于这类案件：请客户录制触发过程（手机拍晃动+现象），内部复现时用\"振动+高低温\"组合测试，确证后返修/换料，并把位置、批次、生产记录对齐。</p>\n<div class=\"tip\">💡 这是\"制程问题\"与\"颗粒问题\"的判别关键：焊接不良=位置相关+机械敏感；颗粒失效=地址相关+概率出现。判断错方向，白查一周。</div>"}], "out": "制程瑕疵图鉴（每种瑕疵配图+成因）"}, {"id": "d10", "title": "实物指认考核 + 周复盘", "date": "Day 10 · 周五", "dot": "5", "tasks": ["导师考核：对着实物 30 秒内指出颗粒/SPD/PMIC/金手指并说明作用", "外观不良识别考核：给出5张图判断正常/异常并说明理由", "整理归档：本周照片+笔记入案例库/知识库", "完成《12周计划》W2 验收点打勾"], "tools": "实物、不良品图库、验收清单", "resources": [], "lectures": [{"title": "实物指认：对着内存条把器件讲一遍", "html": "<h5>1. 考核标准</h5>\n<p>30 秒内指认：<b>DRAM 颗粒、SPD（DDR4 EEPROM / DDR5 SPD Hub）、PMIC（DDR5）、金手指、标签、热敏电阻（如有）</b>，并说清各自作用。外观不良图 5 张判断正常/异常并给理由。</p>\n<h5>2. 指认话术模板（背熟）</h5>\n<ul><li>\"这是 DRAM 颗粒，存数据的地方，x8 位宽共 N 颗组成一 Rank\"；</li>\n<li>\"这是 SPD，存容量/频率/时序的身份信息，主板开机第一步读它\"；</li>\n<li>\"这是 PMIC（DDR5 特有），给颗粒供 VDD/VDDQ/VPP，坏了整条瘫痪\"；</li>\n<li>\"这是金手指，和插槽通信的触点，氧化/划伤会导致接触不良\"。</li></ul>\n<h5>3. 外观不良速认</h5>\n<ul><li>金手指氧化（发暗/发绿）→ 接触不良；</li>\n<li>颗粒鼓包/崩角 → 存储失效风险；</li>\n<li>PCB 翘曲 → 插槽接触不均；</li>\n<li>标签印刷模糊/型号不明 → 物料身份存疑。</li></ul>\n<h5>4. 考核技巧</h5>\n<p>拿一条自己的条子练\"闭眼盲摸+指认\"：摸到位置就能报出器件名。考官问\"这里是什么\"时先报名字、再补一句作用，稳拿分。</p>\n<div class=\"tip\">💡 复盘时把 W2 的知识（引脚数、SPD 总线、PMIC 电压）和实物对一遍，形成\"看得见摸得着\"的记忆。</div>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。</p>\n<h5>2. 每例 <200 字的推荐格式</h5>\n<pre>案例编号：FAE-2026-XXX\n现象：一句话\n平台：主板/CPU/OS/内存型号\n根因：一句话\n证据：日志/截图路径\n对策：临时+永久\n状态：已闭环/复核中</pre>\n<h5>3. 什么案例值得记</h5>\n<ul><li>第一次遇到的故障类型；</li>\n<li>排查过程走弯路的（教训最值钱）；</li>\n<li>证据链完整、能当培训材料的；</li>\n<li>客户高频问题（同问必记）。</li></ul>\n<h5>4. 归档节奏</h5>\n<p>客诉闭环当天顺手记一例（30 秒的事），月底统一补标签和索引。目标：<b>12 周 ≥10 例，一年 ≥30 例</b>。</p>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。</div>"}], "out": "W2 考核通过记录 + 周复盘"}]}, {"id": "w3", "badge": "W3", "title": "平台适配与BIOS：Intel/AMD + QVL + XMP/EXPO", "sub": "阶段 P1 · 理解\"内存装进电脑后发生什么\"", "accept": "能针对不同平台给出推荐频率/时序/电压组合；会恢复BIOS默认并开XMP/EXPO。", "tools": "主板QVL、BIOS手册、HWiNFO64", "phase": "P1", "weekend": "周末加油站：预习 W4 测试工具的官方文档；收集 3 个\"客户常见的兼容性问题\"提问并预习答案。 可选：学习 \"MemTest86 为什么是行业标准\" 维基页", "days": [{"id": "d11", "title": "Intel 12/13/14代内存规则", "date": "Day 11 · 周一", "dot": "1", "tasks": ["学习 Intel 官方内存支持：DDR4/DDR5 各代 IMC 上限频率表", "理解 Intel Gear1/Gear2 对高频的影响（D4 高频 Gear2 是常态）", "学习\"同频不同代\"平台差异：12代支持D4+D5、13/14代D5为主", "记录 2 个典型 Intel 平台的推荐内存配置并背诵"], "tools": "Intel ARK/规格页、主板内存支持页、BIOS手册", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1br4y1E7jv", "label": "▶ 保姆级教程·老主板调内存频率（宇轩tech科技 · 2.8万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV11N4y1q733", "label": "▶ 阿斯加特内存超频教程（张师傅电脑 · 7991播放）"}, {"type": "off", "url": "https://ark.intel.com/content/www/us/en/ark.html", "label": "📄 Intel ARK 规格库"}], "lectures": [{"title": "Intel 12/13/14代平台内存规则", "html": "<h5>1. IMC 与内存频率上限</h5>\n<p>内存频率最终由 <b>CPU 内置内存控制器（IMC）</b>决定，主板只是提供 BIOS 选项。12/13/14 代桌面平台 IMC 通常能上 DDR5-6000+，但具体体质随 CPU 而异。</p>\n<h5>2. Gear 模式（重点）</h5>\n<ul><li><b>Gear1（1:1）</b>：IMC 频率 = 内存频率。延迟最小，适合 DDR4/低频 DDR5。</li>\n<li><b>Gear2（2:1）</b>：IMC 频率 = 内存频率一半。延迟略增，但可支持更高内存频率（DDR5 高频主流方案）。</li></ul>\n<p>记忆：<b>高频选 Gear2，低延迟选 Gear1</b>。DDR5 平台默认常是 Gear2。</p>\n<h5>3. 兼容性判断套路</h5>\n<ol><li>查 Intel 官方支持页/CPU 规格（不是主板页面）确认平台上限；</li>\n<li>查主板 QVL 确认具体型号测过没有；</li>\n<li>客户报\"频率上不去\"：先让他开 XMP→看是否 Gear2→再查 IMC 体质/散热。</li></ol>\n<div class=\"tip\">💡 FAE 话术：\"这颗 CPU 的 IMC 体质决定了能稳的档位，主板 QVL 只是保证能点亮的基线。\"</div>"}], "out": "Intel 平台内存规则速查卡"}, {"id": "d12", "title": "AMD 平台内存规则", "date": "Day 12 · 周二", "dot": "2", "tasks": ["学习 AMD AM4/AM5 内存支持：Ryzen 5000(D4)/7000(D5) 上限", "理解 FCLK/内存频率关系、Infinity Fabric 同步/异步影响", "认识 AMD EXPO（扩展内存配置）与 Intel XMP 的异同", "对比记录：同规格条子在 Intel vs AMD 平台的推荐设置差异"], "tools": "AMD 规格页、主板 QVL、BIOS手册", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1CXAzeDEZ3", "label": "▶ AMD正确配置FCLK降低延迟（陈墨啥都玩 · 7.5万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1L8411N7mZ", "label": "▶ 全网最强AMD DDR4内存超频（安油果 · 53.7万播放）"}, {"type": "off", "url": "https://www.amd.com/en/products/processors", "label": "📄 AMD 处理器官网"}], "lectures": [{"title": "AMD 平台内存规则（AM4/AM5 + EXPO）", "html": "<h5>1. AMD 平台特点</h5>\n<p>AMD 桌面平台（AM4 Ryzen 5000 / AM5 Ryzen 7000+）内存行为由 IMC + Infinity Fabric（IF）互联决定。</p>\n<h5>2. FCLK / UCLK / MEMCLK 三角关系</h5>\n<ul><li><b>MEMCLK</b>：内存频率；<b>UCLK</b>：内存控制器频率；<b>FCLK</b>：IF 总线频率。</li>\n<li>DDR4 常见 1:1:1（如 3600 配 FCLK 1800）。</li>\n<li>DDR5 高频时 UCLK 与 MEMCLK 可能分频（2:1），FCLK 与内存频率非严格 1:1 → 存在最佳甜点区。</li></ul>\n<h5>3. EXPO vs XMP</h5>\n<p><b>EXPO</b>（AMD Extended Profiles for Overclocking）是 AMD 为 DDR5 推出的扩展内存配置，类似 Intel XMP，写入 SPD 扩展区，一键开启高频配置。AMD 平台也可识别 XMP 条子，但理想是用 EXPO 认证型号。</p>\n<div class=\"tip\">💡 AM5 平台上 FCLK 过高（如 2200）可能反而性能下降或偶发不稳定，所以\"越高越好\"不成立——这也是 AMD 客诉的常见来源。</div>"}], "out": "Intel vs AMD 平台适配对照表"}, {"id": "d13", "title": "QVL 解读实操", "date": "Day 13 · 周三", "dot": "3", "tasks": ["学习 QVL 表格各列含义：厂商/颗粒/容量/频率/时序/测试状态", "实操：在 2 块主板官网下载 QVL，检索 HOGE 型号或主流型号", "理解\"QVL 之外不一定不兼容，QVL 之内不一定绝对兼容\"边界", "记录 QVL 检索步骤，形成标准动作（客户问兼容性时怎么查）"], "tools": "华硕/微星/技嘉 QVL 文件", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1VhnF6yEDQ", "label": "▶ 爆肝测试100套组合·内存不兼容原因（和微论件 · 11.2万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1ua411L78Y", "label": "▶ 内存条兼容性·玄学问题（ZoveyChen · 11.8万播放）"}, {"type": "off", "url": "https://www.asus.com/support/", "label": "📄 华硕内存支持(QVL)"}, {"type": "off", "url": "https://www.msi.com/support", "label": "📄 微星内存支持列表"}], "lectures": [{"title": "QVL 解读：怎么查、怎么看、边界在哪", "html": "<h5>1. QVL 是什么</h5>\n<p>QVL（Qualified Vendor List）= 主板厂商实测过的内存型号兼容列表。它回答：\"这块主板配这些内存测过没问题。\"</p>\n<h5>2. QVL 表格怎么读（常见列）</h5>\n<ul><li><b>Vendor 厂商</b>：内存品牌（如 HOOE/三星/金士顿）；</li>\n<li><b>Part Number</b>：具体型号（关键，同名品牌不同型号也要看准）；</li>\n<li><b>Capacity 容量</b>：单条/套条容量；</li>\n<li><b>Speed 频率</b>：测试时达到的频率（XMP 档或 JEDEC）；</li>\n<li><b>Timing/Voltage</b>：对应时序与电压。</li></ul>\n<h5>3. 检索动作（标准流程）</h5>\n<ol><li>到华硕/微星/技嘉等官网 → 产品页 → 支持/规格 → 内存兼容性列表；</li>\n<li>搜品牌型号（用精确 Part Number，别只搜系列名）；</li>\n<li>记录该型号在哪些插槽/容量组合下验证通过。</li></ol>\n<h5>4. 边界理解（FAE 常被问）</h5>\n<ul><li>不在 QVL ≠ 一定不兼容——只是没测过；</li>\n<li>在 QVL ≠ 绝对没问题——QVL 基于特定 BIOS 版本/批次；</li>\n<li>判定\"兼容性问题\"要结合实测，不能只看列表。</li></ul>\n<div class=\"warn\">⚠️ 客户若用\"不在 QVL\"质疑，正确回应：\"QVL 是厂商测试基线，不代表全部；我们按实际平台做交叉验证来定位。\"</div>"}], "out": "QVL 检索 SOP（含截图演示）"}, {"id": "d14", "title": "BIOS 内存项 + XMP/EXPO 机制", "date": "Day 14 · 周四", "dot": "4", "tasks": ["学习 BIOS 内存菜单：频率选择、时序设置、电压（VDDQ/SA）、Gear 模式", "理解 XMP/EXPO 原理：SPD 扩展区预设的额外Profile，一键超频", "理解 XMP 失败常见原因：IMC体质、电压不足、散热、兼容性", "学习\"恢复 BIOS 默认\"的正确路径（清CMOS/默认设置）"], "tools": "BIOS手册、主板说明书", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1b1BKB8EdX", "label": "▶ 保姆级XMP/EXPO开启教程（无敌电脑大王 · 2.9万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV113411i7eS", "label": "▶ 简谈内存SPD、刷写XMP（吗吗哈哈 · 8625播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Intel_Extreme_Memory_Profile", "label": "📄 维基百科·Intel XMP"}], "lectures": [{"title": "BIOS 内存项 + XMP/EXPO 机制", "html": "<h5>1. BIOS 内存菜单常见项</h5>\n<ul><li><b>Memory Frequency/比率</b>：手动频率或自动（Auto/By SPD）；</li>\n<li><b>XMP/EXPO Profile</b>：一键载入超频配置；</li>\n<li><b>DRAM 电压</b>：DDR5 常见 VDDQ/VDD（1.35V 为 XMP 常用值），加电压提高稳定性但升温；</li>\n<li><b>Gear Mode（Intel）</b>：Gear1/Gear2 选择；</li>\n<li><b>Memory Training / 重新训练</b>：开机训练记忆参数，老主板换条后建议清内存训练。</li></ul>\n<h5>2. XMP/EXPO 原理</h5>\n<p>SPD 里除了 JEDEC 标准档，还有一个（或多个）<b>超频 Profile</b>：指定了更高频率+时序+电压。BIOS 开启后按 Profile 跑，而不是按 JEDEC 保守档。</p>\n<h5>3. XMP 开启后不稳定的常见原因</h5>\n<ol><li>IMC 体质不够（CPU 不行）；</li>\n<li>电压不足（需要手动微增 VDDQ/SA）；</li>\n<li>散热不足（高温降频/不稳）；</li>\n<li>主板 BIOS 兼容性差（需更新）；</li>\n<li>混插不同频率/不同颗粒条子。</li></ol>\n<h5>4. 恢复 BIOS 默认的正确做法</h5>\n<p>进 BIOS → Load Defaults / 恢复默认设置 → 保存重启；必要时短接 CMOS 跳线或拔电池 30 秒。恢复默认后内存回到 JEDEC 档，用来排除\"超频设置导致的故障\"。</p>\n<div class=\"tip\">💡 排查客诉\"一开 XMP 就重启\"：先恢复默认确认 JEDEC 档稳定 → 再逐步开 XMP → 最后微调电压/降频定位边界。</div>"}], "out": "BIOS 内存项名词表（含中英文对照）"}, {"id": "d15", "title": "实操：开 XMP + 恢复默认 + 周复盘", "date": "Day 15 · 周五", "dot": "5", "tasks": ["实操：进 BIOS → 开启 XMP/EXPO → 重启验证频率时序生效", "实操：恢复 BIOS 默认 → 验证内存回到 JEDEC 标称频率", "用 HWiNFO64 对比 XMP 开/关的时序、电压、温度差异", "完成《12周计划》W3 验收点打勾 + 周复盘"], "tools": "测试平台、HWiNFO64、BIOS手册", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1b1BKB8EdX", "label": "▶ 保姆级XMP/EXPO开启教程（无敌电脑大王 · 2.9万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV113411i7eS", "label": "▶ 简谈内存SPD、刷写XMP（吗吗哈哈 · 8625播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Intel_Extreme_Memory_Profile", "label": "📄 维基百科·Intel XMP"}], "lectures": [{"title": "BIOS 内存项 + XMP/EXPO 机制", "html": "<h5>1. BIOS 内存菜单常见项</h5>\n<ul><li><b>Memory Frequency/比率</b>：手动频率或自动（Auto/By SPD）；</li>\n<li><b>XMP/EXPO Profile</b>：一键载入超频配置；</li>\n<li><b>DRAM 电压</b>：DDR5 常见 VDDQ/VDD（1.35V 为 XMP 常用值），加电压提高稳定性但升温；</li>\n<li><b>Gear Mode（Intel）</b>：Gear1/Gear2 选择；</li>\n<li><b>Memory Training / 重新训练</b>：开机训练记忆参数，老主板换条后建议清内存训练。</li></ul>\n<h5>2. XMP/EXPO 原理</h5>\n<p>SPD 里除了 JEDEC 标准档，还有一个（或多个）<b>超频 Profile</b>：指定了更高频率+时序+电压。BIOS 开启后按 Profile 跑，而不是按 JEDEC 保守档。</p>\n<h5>3. XMP 开启后不稳定的常见原因</h5>\n<ol><li>IMC 体质不够（CPU 不行）；</li>\n<li>电压不足（需要手动微增 VDDQ/SA）；</li>\n<li>散热不足（高温降频/不稳）；</li>\n<li>主板 BIOS 兼容性差（需更新）；</li>\n<li>混插不同频率/不同颗粒条子。</li></ol>\n<h5>4. 恢复 BIOS 默认的正确做法</h5>\n<p>进 BIOS → Load Defaults / 恢复默认设置 → 保存重启；必要时短接 CMOS 跳线或拔电池 30 秒。恢复默认后内存回到 JEDEC 档，用来排除\"超频设置导致的故障\"。</p>\n<div class=\"tip\">💡 排查客诉\"一开 XMP 就重启\"：先恢复默认确认 JEDEC 档稳定 → 再逐步开 XMP → 最后微调电压/降频定位边界。</div>"}, {"title": "HWiNFO64 使用详解：温压监控 + 日志", "html": "<h5>1. 是什么</h5>\n<p>免费硬件信息与传感器监控工具（<a href=\"https://www.hwinfo.com/\" target=\"_blank\" rel=\"noopener\">官网</a>）。FAE 用它看<b>温度、电压、频率</b>，判断稳定性问题的环境因素。</p>\n<h5>2. 关键界面</h5>\n<ul><li>启动选<b> Sensors-only（仅传感器）</b> 模式；</li>\n<li>找 <b>DIMM/内存温度</b>：DDR5 条子通常带温度传感器（TS）；</li>\n<li>看 <b>VDDQ / VDD 电压</b>：是否稳定在 1.1V/1.35V（XMP）附近；</li>\n<li>看 <b>CPU/主板供电温度</b>：过热会影响内存稳定性。</li></ul>\n<h5>3. 抓日志（重要）</h5>\n<ol><li>Sensors 窗口 → 工具栏点击 <b>Logging（日志）</b> 按钮；</li>\n<li>设置间隔（如 1 秒）与保存路径（CSV）；</li>\n<li>开始记录后去跑压力测试/复现故障场景；</li>\n<li>故障发生后停止日志，Excel 打开 CSV 看\"温度/电压在崩溃前发生了什么\"。</li></ol>\n<h5>4. 与故障窗口关联</h5>\n<p>NTF/偶发问题最难的就是\"没有现场\"。HWiNFO64 日志能回答：<b>蓝屏前 1 分钟内存温度是不是飙了？电压是不是掉了？</b>——这是环境类根因的直接证据。</p>\n<div class=\"tip\">💡 客户现场支持，第一件事先开 HWiNFO64 记录——等故障发生时你就有完整数据，而不是空手回去。</div>"}], "out": "XMP 开/关对比记录表（频率/时序/电压/温度）"}]}, {"id": "w4", "badge": "W4", "title": "测试标准与工具：MT86 + MonitorMemtest + BurnInTest + 电气测量", "sub": "阶段 P1 · 建立\"用数据说话\"的测试能力", "accept": "独立完成一轮完整测试并判读日志，给出PASS/FAIL结论与依据。", "tools": "MT86、BurnInTest、老化箱、万用表/示波器、测试规范", "phase": "P1", "weekend": "周末加油站：P1 阶段知识自测；预习 W5 故障场景；整理 P1 阶段笔记成\"打底知识包\"（后续反复查阅）。 可选：把 MT86 判读口诀做成小卡片", "days": [{"id": "d16", "title": "MemTest86 启动盘制作 + 全流程", "date": "Day 16 · 周一", "dot": "1", "tasks": ["下载 MemTest86（x86/ARM 版本选择），用 Rufus 制作启动U盘", "学习 MT86 测试项概念：地址测试/数据测试/缓存测试/错误判定", "独立跑完一个 Pass，学会看进度与错误页", "学习判读报错地址：免费版可用地址段人工推断颗粒范围；Pro版支持自动解码到 DIMM/Chip（Test 6/14 无法解码），免费版日志无 DIMM 解码"], "tools": "MemTest86官网、Rufus、测试机", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1gh4y1C7kF", "label": "▶ MemTest86使用方法简介（风吹散的思念 · 9.5万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1QU411d79u", "label": "▶ MemTest86新手教程·启动盘（金百达协助员 · 2.5万播放）"}, {"type": "off", "url": "https://www.memtest86.com/", "label": "📄 MemTest86 官网"}, {"type": "off", "url": "https://www.memtest86.com/tech_booting-memtest.html", "label": "📄 MemTest86 技术手册"}, {"type": "off", "url": "https://www.cpuid.com/softwares/cpu-z.html", "label": "📄 CPU-Z 官网"}], "lectures": [{"title": "MemTest86：制作启动盘 + 全流程判读", "html": "<h5>1. 为什么用它（MemTest86 的地位）</h5>\n<p>MemTest86 是<b>独立于操作系统</b>的开机级内存测试工具（PassMark 出品），从 USB 启动，绕过系统/驱动干扰，直接扫描内存硬件错误。<b>行业默认的最终判据之一</b>：内存有没有问题，MT86 跑一轮比系统里任何软件都可信。</p>\n<h5>2. 制作启动 U 盘（标准流程，10 分钟）</h5>\n<ol><li>下载 MemTest86 镜像（x86/x64 用 PC 版；企业/服务器平台确认 UEFI 模式）；</li>\n<li>用 <b>Rufus</b> 或 MemTest86 自带工具写 U 盘（⚠️ 注意备份 U 盘数据，会清空）；</li>\n<li>电脑重启 → 按 F8/F11/F12（看主板）选 U 盘启动 → 进入测试界面（新版支持 XMP 配置读取）。</li></ol>\n<h5>3. 测试配置建议（客诉级别）</h5>\n<table><tr><th>场景</th><th>Pass 数</th><th>时长参考</th><th>目的</th></tr>\n<tr><td>快速筛查</td><td>1 Pass</td><td>约 1-2h</td><td>初步判断有无硬件错误</td></tr>\n<tr><td>客诉常规</td><td>2-4 Pass</td><td>过夜</td><td>排除偶发，覆盖更多地址</td></tr>\n<tr><td>疑难/NTF</td><td>≥4 Pass + 长测</td><td>24h+</td><td>间歇性/高温边界问题</td></tr></table>\n<p>建议同时开 <b>ECC 校验（如支持）</b>和 <b>温度监控</b>；高温环境（夏天/机箱悶）可在 55℃ 环境下复测，很多临界条子在温度高时才出错。</p>\n<h5>4. 判读（核心动作）</h5>\n<ul><li>看 <b>Errors 是否为 0</b>——任何 Error 都是 FAIL；</li>\n<li>看错误<b>地址范围</b>：免费版可按地址段人工推断颗粒区域（结合插槽号与 Rank）；Pro 版自动解码到 DIMM/Chip（Test 6/14 除外）；</li>\n<li>记录错误<b>模式</b>：固定地址反复错 = 颗粒/通道问题；随机地址零星错 = 电压/时序/温度边界；大面积错 = 接触/颗粒严重故障或多通道问题；</li>\n<li>跑完保存日志（免费版可截图/存 HTML，Pro 出报告）。</li></ul>\n<h5>5. 判定标准与后续</h5>\n<p><b>0 Error + 完整跑完 = PASS</b>；出现 Error = FAIL，下一步：换槽/换条/交叉替换确认<b>哪根条的哪颗粒/哪个通道</b>，然后决定换货/返修/换平台复测。</p>\n<div class=\"warn\">⚠️ 重要细节：免费版无法自动 DIMM/chip 解码，地址推断依赖经验和插槽图；别从\"广告多的第三方站\"下载，官方 memtest86.com 下载即可，Pro 版功能不需要就别花钱。</div>\n<div class=\"tip\">💡 考核点：能说清\"为什么用 MT86 而不是 Windows 内存诊断\"——答：开机级 + 独立于 OS + 覆盖率高的标准判据。</div>"}], "out": "可启动的 MT86 U盘 + 首轮测试日志"}, {"id": "d17", "title": "MonitorMemtest + BurnInTest", "date": "Day 17 · 周二", "dot": "2", "tasks": ["学习 MonitorMemtest：Windows 下的图形化内存测试工具", "学习 BurnInTest：测试项配置、内存占比、时长设置（8h+目标）", "实操：设置 BurnInTest RAM 测试（≥90%内存/循环/日志输出）", "学习日志判读：Error 计数、测试进度、如何定位失败项"], "tools": "MonitorMemtest、BurnInTest、测试规范", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1ZMoeBPEKx", "label": "▶ 保姆级内存条测试·tm5压力/台风（宅机侠 · 17.6万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1MjKb62EtX", "label": "▶ 运维必备内存压测工具memtester（尚诚云课堂 · 1074播放）"}, {"type": "off", "url": "https://www.passmark.com/products/burnintest/index.php", "label": "📄 PassMark BurnInTest 官网"}], "lectures": [{"title": "MonitorMemtest + BurnInTest：压力测试", "html": "<h5>1. MonitorMemtest 用途</h5>\n<p>Windows 下图形化内存监控+测试（PassMark 免费工具）。适合：系统可进、想<b>后台跑</b>观察随机错误。</p>\n<h5>2. BurnInTest 配置（8h+ 长稳）</h5>\n<ol><li>新建测试 → 勾选 <b>RAM</b>（可加 CPU/Disk 模拟整机负载）；</li>\n<li>设置测试时间 480 分钟（8h）或循环次数；</li>\n<li>内存占用 ≥90% 才能有效压满；</li>\n<li>开启自动保存日志（CSV/HTML），便于截图存证。</li></ol>\n<h5>3. 判读</h5>\n<ul><li>看 Pass/Fail 计数；0 Error + 持续运行 = 通过；</li>\n<li>中途蓝屏/死机 → 记录时间点与当时温度/负载，反查日志；</li>\n<li>与 MT86 配合：MT86 查硬件坏点，BurnInTest 查系统级稳定性/NTF 复现。</li></ul>"}], "out": "8h 压力测试参数配置截图 + 日志模板"}, {"id": "d18", "title": "稳定/兼容/性能测试 + 不良判定", "date": "Day 18 · 周三", "dot": "3", "tasks": ["学习测试规范的结构：目的/环境/步骤/判定标准", "兼容性测试：多平台点测流程（Intel+AMD+笔记本平台）", "性能测试基础：跑分工具（AIDA64 Cache&Memory Benchmark）", "学习不良项判定标准：出现 1 个错误算 FAIL？判据要查规范", "学习高低温老化测试概念：高温老化（如55℃/85℃）与低温老化目的，温区设置⚠️以公司测试规范为准", "认识信创平台测试（有项目时）：Stress/Memtest/Stream/S3/S4/Reboot/LTP——国产平台（飞腾/兆芯/麒麟等）基线测试方法，详见《02_工具实操手册》A4节"], "tools": "公司测试规范、AIDA64、测试记录模板", "resources": [], "lectures": [{"title": "测试规范：怎么测、按什么判", "html": "<h5>1. 测试规范的骨架（所有测试通用）</h5>\n<p>一份测试记录必须写清：<b>目的 / 环境（硬件+软件版本）/ 步骤 / 数据 / 判定（对照规范条款）</b>。判 PASS/FAIL 的唯一依据是公司《测试规范》/《不良判定标准》，不是个人感觉。</p>\n<h5>2. 三类测试的要点</h5>\n<ul><li><b>兼容性测试</b>：多平台点测（Intel+AMD+笔记本），关注开机/识别/读写是否正常；样本量越大越可信；</li>\n<li><b>稳定性测试</b>：MT86 + BurnInTest（8h+），重点看长时间、高温、满负载下是否出错；</li>\n<li><b>性能测试</b>：AIDA64 Cache & Memory Benchmark / 读写跑分，用于横向对比条子档位是否符合规格。</li></ul>\n<h5>3. 不良判定（关键）</h5>\n<ul><li>MT86 出现任何 Error → 判定 FAIL，记录地址与测试项；</li>\n<li>BurnInTest 8h 0 Error + 无蓝屏 → PASS；中途报错/死机 → 记录时间点反查；</li>\n<li>\"出现 1 个错误是否 FAIL\"——<b>按规范条款</b>查判定标准，不同客户/场景要求可能不同（消费级 vs 工业级）。</li></ul>\n<h5>4. 测试记录的行业习惯</h5>\n<p>环境栏写全：BIOS 版本、OS 版本、内存插槽位置、散热条件、室温。数据栏贴日志/截图。<b>没有环境信息的测试记录等于废纸</b>，因为不可复现。</p>\n<div class=\"warn\">⚠️ 常见坑：测出来 PASS 但客户现场 FAIL——先查环境是否一致（BIOS 版本/插槽数/是否混插/温度）。</div>"}, {"title": "AIDA64 使用详解：内存压力 + 性能基准", "html": "<h5>1. 是什么</h5>\n<p>系统检测与基准测试工具（<a href=\"https://www.aida64.com/\" target=\"_blank\" rel=\"noopener\">官网</a>）。FAE 用两块：<b>稳定性压力测试</b> 和 <b>内存性能基准</b>。</p>\n<h5>2. 稳定性测试（工具→系统稳定性测试）</h5>\n<ul><li>勾选 <b>Stress Memory</b>（或 Stress CPU 一起模拟整机负载）；</li>\n<li>下方实时显示温度/占用；推荐 30min-1h 起步；</li>\n<li>报错时看是 CPU 还是内存项报错，配合传感器判读。</li></ul>\n<h5>3. 内存性能基准（工具→Cache & Memory Benchmark）</h5>\n<ul><li>结果含 Read / Write / Copy / Latency 四项；</li>\n<li>用于判断条子是否达到标称性能、开 XMP 前后的差异；</li>\n<li>对比基线：同型号条子、同平台正常值。</li></ul>\n<h5>4. FAE 用法</h5>\n<p>客户报\"内存性能差\" → AIDA64 跑基准 → 和同配置正常值对比 → 若 Read 掉半 → 检查是否被降频/单通道/混插。数据说话，别凭感觉。</p>\n<div class=\"tip\">💡 AIDA64 的内存延迟（Latency）是判断\"时序设置是否激进\"的好指标：延迟异常高 → 可能 Gear 分频/时序过松。</div>"}, {"title": "信创平台测试工具补充（memtester/Stream/LTP/S3S4循环）", "html": "<h5>1. 信创常用工具一句话版</h5>\n<table><tr><th>工具</th><th>测什么</th><th>典型用法</th></tr>\n<tr><td>stress</td><td>CPU/内存/IO 负载</td><td>stress --cpu 8 --vm 2 --vm-bytes 1G --timeout 8h</td></tr>\n<tr><td>memtester</td><td>内存专项压力</td><td>memtester 1G 10</td></tr>\n<tr><td>Stream</td><td>内存带宽（Copy/Scale/Add/Triad）</td><td>./stream 测峰值带宽，对比基线</td></tr>\n<tr><td>S3/S4</td><td>休眠/睡眠唤醒</td><td>循环 suspend/resume 脚本 ×100</td></tr>\n<tr><td>Reboot</td><td>重启稳定性</td><td>循环 reboot 脚本 ×50-100</td></tr>\n<tr><td>LTP</td><td>系统级长稳回归</td><td>LTP 全量/子集跑一夜</td></tr></table>\n<h5>2. 何时用</h5>\n<p>信创项目（飞腾/鲲鹏/兆芯/海光 + 麒麟/UOS）验收、兼容性客诉复现。重点：<b>输出平台+BIOS+工具+时长+结论的基线结论</b>，客户要的是\"能用多久不出错\"的证明。</p>\n<h5>3. 与内存 FAE 的关系</h5>\n<p>信创平台内存兼容性问题高发：先跑 memtester/Stream 确认硬件，再查 BIOS 内存项与国产 OS 驱动；LTP 失败常是驱动/系统问题而非内存。</p>"}], "out": "测试规范速查表（判定标准高亮）"}, {"id": "d19", "title": "万用表/示波器测供电与通路", "date": "Day 19 · 周四", "dot": "4", "tasks": ["学习万用表：电压档测金手指供电——DDR4 VDD=1.2V；DDR5 VDD/VDDQ=1.1V、VPP=1.8V（对照测量）", "学习通断档测金手指到测试点通路（找虚焊/断路）", "认识简易示波器：测供电纹波、关键信号有无（入门级）", "实操：在报废条上练习测电压点，记录读数"], "tools": "万用表、简易示波器、ATE 工具说明", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV11N4y1679u", "label": "▶ 万用表使用方法一分钟学会（电工plc教学-老帝 · 90.2万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1HJ4m1J7Vy", "label": "▶ 万用表使用入门到精通（工控圈 · 28.4万播放）"}], "lectures": [{"title": "万用表 / 简易示波器测供电与通路", "html": "<h5>1. 万用表三档用法（对内存）</h5>\n<ul><li><b>电压档（DC V）</b>：测金手指供电脚——DDR4 VDD=1.2V；DDR5 VDD/VDDQ=1.1V、VPP=1.8V。读数偏离 → 供电问题（PMIC/主板）；</li>\n<li><b>通断档（蜂鸣）</b>：测金手指到测试点是否导通 → 找虚焊/断路；</li>\n<li><b>电阻档</b>：测供电脚对地阻值，异常短路可快速定位。</li></ul>\n<h5>2. 测量安全</h5>\n<p>先确认档位再夹表笔；测电压用直流档，表笔红黑接对；带电测量注意短路风险。</p>\n<h5>3. 简易示波器（入门）</h5>\n<ul><li>测 <b>供电纹波</b>：VDDQ 点 AC 耦合看纹波幅值（大纹波 → 供电气质差 → 不稳定）；</li>\n<li>测 <b>关键信号有无</b>：DQS/DQ 是否有活动波形（无波形可能颗粒未激活/断路）；</li>\n<li>入门不用深究波形质量，先会测\"有/无、电压对不对\"。</li></ul>\n<div class=\"tip\">💡 现场快速三连：一看金手指、二测 VDD 电压、三测通路 → 大部分供电/接触问题当场定性。</div>"}], "out": "万用表测量记录表（点位/档位/读数）"}, {"id": "d20", "title": "完整测试闭环 + 阶段小测", "date": "Day 20 · 周五", "dot": "5", "tasks": ["独立完成一轮\"完整测试\"：装条→MT86→BurnInTest短跑→判定", "输出一份测试记录：目的/环境/数据/结论（PASS/FAIL+依据）", "完成 P1 阶段小测（原理+结构+平台+测试四块）", "完成《12周计划》W4 验收点打勾 + P1 阶段总结复盘"], "tools": "测试平台、测试规范、阶段测试卷", "resources": [], "lectures": [{"title": "完整测试闭环：从装条到结论的一次演练", "html": "<h5>1. 闭环八步（自己走一遍）</h5>\n<ol><li>准备：机台、条子、BIOS 默认环境、工具盘；</li>\n<li>安装：确认插到位、金手指干净、卡扣锁牢；</li>\n<li>开机验证：BIOS 正确识别容量/频率；</li>\n<li>MT86：跑一轮（≥1 Pass），记录日志；</li>\n<li>BurnInTest 短跑（30min+）验证系统稳定；</li>\n<li>HWiNFO64 记录温度/电压基线；</li>\n<li>AIDA64 跑性能看是否达标；</li>\n<li>汇总数据 → 对照规范给 PASS/FAIL → 填测试报告。</li></ol>\n<h5>2. 报告模板（当日产出）</h5>\n<p>目的 / 环境（型号+BIOS+OS）/ 测试方法（工具+参数+时长）/ 数据（日志+截图）/ 判定（结论+条款依据）。</p>\n<h5>3. 阶段小测备考</h5>\n<ul><li>原理：D4/D5 差异 5 条口述；时序 4 参数解释；</li>\n<li>结构：实物指认各器件作用；引脚数（288/260/262）；</li>\n<li>平台：Intel Gear、AMD FCLK、QVL 含义；</li>\n<li>测试：MT86 怎么跑、Error 怎么判、测试规范怎么用。</li></ul>\n<div class=\"tip\">💡 测试闭环最大的价值：以后每一单客诉，你都按这个套路跑一遍，不会漏步骤、也不会被客户\"带节奏\"。</div>"}, {"title": "测试记录/测试报告怎么写", "html": "<h5>1. 一份合格测试记录的六要素</h5>\n<p><b>目的 / 环境 / 方法 / 数据 / 判定 / 结论</b>。没有环境信息（BIOS版本/OS/插槽/温度）的记录=不可复现=废纸。</p>\n<h5>2. 模板</h5>\n<pre>\n测试目的：验证 XXX 内存 DDR5-5600 在 XX 平台稳定性\n测试环境：主板 / BIOS v1.20 / CPU / OS / 内存插槽 A2+B2 / 室温25℃\n测试方法：MemTest86 4Pass + BurnInTest 8h（RAM≥90%）\n测试数据：（日志路径 / 截图 / 温压曲线）\n判定：对照《测试规范》条款X → PASS / FAIL\n结论：一句话，异常项单独说明\n</pre>\n<h5>3. 常见错误</h5>\n<ul><li>只写\"测了没问题\"不说怎么测的；</li>\n<li>判定没有引用规范条款；</li>\n<li>数据与结论不一致（有 Error 却说 PASS）。</li></ul>\n<div class=\"tip\">💡 写成模板之后，每单客诉填表即可——既快又不会有遗漏。测试报告也是 FA 报告的数据来源。</div>"}], "out": "完整测试报告 1 份 + P1 阶段总结"}]}, {"id": "w5", "badge": "W5", "title": "故障场景拆解·硬件类：十大TOP客诉 + 根因映射", "sub": "阶段 P2 · 从\"认识内存\"到\"会拆故障\"", "accept": "能对每个故障现象列出 ≥4 条候选根因并排序。", "tools": "客户案例库、现场问题分析报告模板", "phase": "P2", "weekend": "周末加油站：把映射表打印贴工位；挑 1 个真实案例从\"现象\"反推\"根因验证链\"；预习 W6 排查流程。 可选：学习\"最小系统法\"排障视频", "days": [{"id": "d21", "title": "故障场景总览 + 案例库学习", "date": "Day 21 · 周一", "dot": "1", "tasks": ["通读客户案例库中 10 个真实案例，建立\"现象→根因\"直觉", "学习《现场问题分析报告模板》结构与字段", "整理十大TOP客诉清单：不识别/容量错、频率不达标、蓝屏死机、黑屏、过热、物理损坏等", "建立个人《故障-根因映射表》Excel 骨架（现象/根因/验证方法/案例号）"], "tools": "客户案例库、现场问题分析报告模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1mp421m7aV", "label": "▶ 风扇正常转但黑屏无信号·解决（国丰装机 · 240.4万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1qV411S7g9", "label": "▶ 黑屏/蓝屏/闪退最全解决办法（大明湖畔千百万 · 7.0万播放）"}, {"type": "off", "url": "https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-checks-bug-check-code-reference", "label": "📄 微软蓝屏代码官方文档"}], "lectures": [{"title": "TOP 故障现象 → 候选根因 + 验证方法", "html": "<h5>1. 不识别/容量错</h5>\n<p>√ 插槽接触不良（重插/换槽）｜√ SPD 损坏或数据错误（查 SPD 二进制）｜√ 颗粒虚焊/损坏｜√ 主板 BIOS 不兼容（更新/查 QVL）｜√ 混插不匹配｜√ 32 位系统限制（4GB 上限）｜√ 金手指氧化</p>\n<h5>2. 频率不达标</h5>\n<p>√ 未开 XMP/EXPO ｜√ IMC 体质不足｜√ 混插降频（不同频率条子取最低）｜√ 散热降频｜√ BIOS 旧版｜√ 电压不足</p>\n<h5>3. 蓝屏/死机/重启</h5>\n<p>√ 颗粒不良（MT86 定性）｜√ 时序过激（XMP 不稳）｜√ 驱动/系统问题｜√ 供电不稳｜√ 混插兼容｜√ 接触不良｜√ CPU/主板问题（交叉替换排除）</p>\n<h5>4. 黑屏/不开机</h5>\n<p>√ 内存未装好（卡扣/方向）｜√ 内存损坏 ｜√ 主板/CPU 故障｜√ 电源不足｜√ BIOS 损坏（罕见）——先最小化系统缩小范围。</p>\n<h5>5. 过热报警</h5>\n<p>√ 散热片/马甲贴装不良 ｜√ 环境温度高｜√ 电压过高（XMP 加压）｜√ 风道设计｜√ 颗粒批次发热特性</p>\n<h5>6. 物理损坏</h5>\n<p>√ 运输磕碰 ｜√ 安装暴力 ｜√ 散热器压伤颗粒 ｜√ ESD 静电损伤 ｜√ 金手指断裂/氧化</p>\n<h5>7. 性能差/延迟高</h5>\n<p>√ 未开 XMP ｜√ 单通道误插（插错槽位）｜√ 混插降频 ｜√ 后台占用 ｜√ OS 未优化</p>\n<h5>8. 长时/高温随机出错</h5>\n<p>√ 颗粒余量不足 ｜√ 温压边界（HWiNFO 抓证据）｜√ 供电纹波 ｜√ IMC 体质 ｜√ 环境干扰（ESD/电源质量）</p>\n<div class=\"tip\">💡 每条根因都要能写出\"验证方法+判定依据\"，这就是考核要的\"≥4条并排序\"。排序按概率：接触问题 > 兼容性 > 颗粒 > 供电 > 环境。</div>"}, {"title": "故障-根因映射表：怎么建、怎么用", "html": "<h5>1. 是什么</h5>\n<p>一张\"现象 → 候选根因（排序）→ 验证方法 → 案例号\"的表，是 FAE 排障的<b>知识资产</b>。考核要求：每个现象能列 ≥4 条候选根因并排序。</p>\n<h5>2. 建表方法（Excel 三列起步）</h5>\n<table><tr><th>现象</th><th>候选根因（按概率排序）</th><th>验证方法</th></tr>\n<tr><td>不识别/容量错</td><td>①接触不良 ②SPD损坏 ③颗粒坏 ④混插 ⑤槽位限制</td><td>换槽/查SPD/单条测试</td></tr>\n<tr><td>频率不达标</td><td>①未开XMP ②IMC体质 ③混插降频 ④散热 ⑤BIOS旧</td><td>开XMP/单条/看温度</td></tr></table>\n<h5>3. 排序原则</h5>\n<p>按<b>发生概率</b>排：接触问题 > 兼容性 > 颗粒 > 供电 > 环境。别把\"罕见根因\"排在前面——客户会觉得不专业。</p>\n<h5>4. 使用方法</h5>\n<ul><li>排障时对照表格逐条验证，不跳步；</li>\n<li>每处理一单新案例，回填\"案例号/验证结果\"；</li>\n<li>每月升级一版（V1→V2…），把新根因加入。</li></ul>\n<div class=\"tip\">💡 考核答辩：导师随机抽\"蓝屏死机\"，你按表格一口气列 6 条+排序+验证方法 = 高分。这张表就是你考试的弹药库。</div>"}], "out": "故障-根因映射表 V0（框架+初填）"}, {"id": "d22", "title": "现象①：不开机/黑屏", "date": "Day 22 · 周二", "dot": "2", "tasks": ["列出不开机/黑屏 ≥4 条候选根因：接触不良、内存不兼容、插错槽、颗粒损坏、主板/CPU损坏、BIOS损坏", "学习每条的验证方法：重新插拔/换槽/最小化/交叉替换", "从案例库找 2 个\"黑屏\"案例跟踪根因结论", "更新映射表（排序写出最可能→最不可能）"], "tools": "案例库、映射表", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1mp421m7aV", "label": "▶ 风扇正常转但黑屏无信号·解决（国丰装机 · 240.4万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1qV411S7g9", "label": "▶ 黑屏/蓝屏/闪退最全解决办法（大明湖畔千百万 · 7.0万播放）"}, {"type": "off", "url": "https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-checks-bug-check-code-reference", "label": "📄 微软蓝屏代码官方文档"}], "lectures": [{"title": "TOP 故障现象 → 候选根因 + 验证方法", "html": "<h5>1. 不识别/容量错</h5>\n<p>√ 插槽接触不良（重插/换槽）｜√ SPD 损坏或数据错误（查 SPD 二进制）｜√ 颗粒虚焊/损坏｜√ 主板 BIOS 不兼容（更新/查 QVL）｜√ 混插不匹配｜√ 32 位系统限制（4GB 上限）｜√ 金手指氧化</p>\n<h5>2. 频率不达标</h5>\n<p>√ 未开 XMP/EXPO ｜√ IMC 体质不足｜√ 混插降频（不同频率条子取最低）｜√ 散热降频｜√ BIOS 旧版｜√ 电压不足</p>\n<h5>3. 蓝屏/死机/重启</h5>\n<p>√ 颗粒不良（MT86 定性）｜√ 时序过激（XMP 不稳）｜√ 驱动/系统问题｜√ 供电不稳｜√ 混插兼容｜√ 接触不良｜√ CPU/主板问题（交叉替换排除）</p>\n<h5>4. 黑屏/不开机</h5>\n<p>√ 内存未装好（卡扣/方向）｜√ 内存损坏 ｜√ 主板/CPU 故障｜√ 电源不足｜√ BIOS 损坏（罕见）——先最小化系统缩小范围。</p>\n<h5>5. 过热报警</h5>\n<p>√ 散热片/马甲贴装不良 ｜√ 环境温度高｜√ 电压过高（XMP 加压）｜√ 风道设计｜√ 颗粒批次发热特性</p>\n<h5>6. 物理损坏</h5>\n<p>√ 运输磕碰 ｜√ 安装暴力 ｜√ 散热器压伤颗粒 ｜√ ESD 静电损伤 ｜√ 金手指断裂/氧化</p>\n<h5>7. 性能差/延迟高</h5>\n<p>√ 未开 XMP ｜√ 单通道误插（插错槽位）｜√ 混插降频 ｜√ 后台占用 ｜√ OS 未优化</p>\n<h5>8. 长时/高温随机出错</h5>\n<p>√ 颗粒余量不足 ｜√ 温压边界（HWiNFO 抓证据）｜√ 供电纹波 ｜√ IMC 体质 ｜√ 环境干扰（ESD/电源质量）</p>\n<div class=\"tip\">💡 每条根因都要能写出\"验证方法+判定依据\"，这就是考核要的\"≥4条并排序\"。排序按概率：接触问题 > 兼容性 > 颗粒 > 供电 > 环境。</div>"}, {"title": "不开机/黑屏深度排查", "html": "<h5>1. 现象描述要点（先分清三种\"不开机\"）</h5>\n<p>客户说\"不开机\"信息不够——是<b>①完全无反应（风扇都不转）？②风扇转但黑屏（无 POST 画面）？③能进系统但屏幕黑？</b>三种情况方向完全不同：无反应先查电源/主板，风扇转黑屏多查内存/显卡，能进系统黑屏多查驱动/显示器。</p>\n<h5>2. 候选根因（按概率排序）</h5>\n<ol><li><b>内存接触不良/未插好</b>：卡扣没扣、插入不到位、金手指氧化——最常见；</li>\n<li><b>内存不兼容/损坏</b>：换单条/换槽可排除；</li>\n<li><b>插错插槽/单通道要求</b>：某些板必须插 A2 才能点；</li>\n<li><b>主板/CPU 故障</b>：内存完好但 CPU 座/内存通道坏；</li>\n<li><b>电源不足/损坏</b>：开机瞬间掉电；</li>\n<li><b>BIOS 状态异常</b>：清 CMOS 后恢复。</li></ol>\n<h5>3. Debug 灯与蜂鸣代码（内存问题的独特提示）</h5>\n<table><tr><th>提示</th><th>含义</th><th>动作</th></tr>\n<tr><td>Debug 灯停在 DRAM</td><td>内存初始化失败</td><td>重插/换槽/单条测试</td></tr>\n<tr><td>规律长鸣（持续 Beep）</td><td>内存错误（AMI/Award 常见）</td><td>内存相关优先排查</td></tr>\n<tr><td>短鸣 1 声</td><td>POST 正常</td><td>问题在显示/外设</td></tr>\n<tr><td>Debug 灯停在 CPU</td><td>CPU/供电问题</td><td>别在内存上耗时间</td></tr></table>\n<h5>4. 排查路径（快速版 + 完整版）</h5>\n<p><b>快速版（客户通话 5 分钟）</b>：①查 Debug 灯/蜂鸣 → ②单条内存 + A2 槽 + 清 BIOS → ③换槽换条 → ④最小系统。</p>\n<p><b>完整版（现场/返修）</b>：①指示灯/代码 → ②外观金手指 → ③单条 A2 清 CMOS → ④拔光外设备件逐个回装 → ⑤换内存/换槽/换平台交叉 → ⑥万用表测供电（VDD 1.1/1.2V，DDR5 VPP 1.8V）→ ⑦BIOS 更新。</p>\n<h5>5. 与\"内存损坏\"的区别（别误判）</h5>\n<p>黑屏 ≠ 内存坏：<b>只有报错代码/灯指向内存</b>才算。Debug 灯停在 DRAM 且规律长鸣 → 内存通道问题优先；停在 VGA → 显卡；停在 BOOT → 硬盘/引导。查错方向浪费的是客户时间，更伤信任。</p>\n<h5>6. 客户沟通话术</h5>\n<div class=\"warn\">⚠️ \"请先试单条内存插在从 CPU 往右数第二个槽（A2），其他根全部拔掉，看能否点亮——这样能快速判断是不是多根混插/接触问题。顺便拍一下主板上 Debug 灯或蜂鸣情况。\"</div>\n<div class=\"tip\">💡 记忆锚点：\"黑屏先分三种，再查灯，再单条 A2\"——三步走完，80% 的接触类问题已经定位。</div>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。</p>\n<h5>2. 每例 <200 字的推荐格式</h5>\n<pre>案例编号：FAE-2026-XXX\n现象：一句话\n平台：主板/CPU/OS/内存型号\n根因：一句话\n证据：日志/截图路径\n对策：临时+永久\n状态：已闭环/复核中</pre>\n<h5>3. 什么案例值得记</h5>\n<ul><li>第一次遇到的故障类型；</li>\n<li>排查过程走弯路的（教训最值钱）；</li>\n<li>证据链完整、能当培训材料的；</li>\n<li>客户高频问题（同问必记）。</li></ul>\n<h5>4. 归档节奏</h5>\n<p>客诉闭环当天顺手记一例（30 秒的事），月底统一补标签和索引。目标：<b>12 周 ≥10 例，一年 ≥30 例</b>。</p>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。</div>"}], "out": "黑屏根因清单（≥4条+验证方法+排序）"}, {"id": "d23", "title": "现象②③：不识别/容量错 + 频率不达标", "date": "Day 23 · 周三", "dot": "3", "tasks": ["不识别/容量错候选根因：SPD损坏、颗粒坏、混插冲突、32位系统限制、主板内存通道故障、接触不良", "频率不达标候选根因：未开XMP/EXPO、IMC体质、混插降频、散热、BIOS旧版、颗粒等级", "学习判断\"容量错\"的陷阱：系统识别 vs BIOS识别 vs 插槽限制", "更新映射表（这两个现象各≥4条）"], "tools": "案例库、CPU-Z、BIOS设置知识", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1mp421m7aV", "label": "▶ 风扇正常转但黑屏无信号·解决（国丰装机 · 240.4万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1qV411S7g9", "label": "▶ 黑屏/蓝屏/闪退最全解决办法（大明湖畔千百万 · 7.0万播放）"}, {"type": "off", "url": "https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-checks-bug-check-code-reference", "label": "📄 微软蓝屏代码官方文档"}], "lectures": [{"title": "TOP 故障现象 → 候选根因 + 验证方法", "html": "<h5>1. 不识别/容量错</h5>\n<p>√ 插槽接触不良（重插/换槽）｜√ SPD 损坏或数据错误（查 SPD 二进制）｜√ 颗粒虚焊/损坏｜√ 主板 BIOS 不兼容（更新/查 QVL）｜√ 混插不匹配｜√ 32 位系统限制（4GB 上限）｜√ 金手指氧化</p>\n<h5>2. 频率不达标</h5>\n<p>√ 未开 XMP/EXPO ｜√ IMC 体质不足｜√ 混插降频（不同频率条子取最低）｜√ 散热降频｜√ BIOS 旧版｜√ 电压不足</p>\n<h5>3. 蓝屏/死机/重启</h5>\n<p>√ 颗粒不良（MT86 定性）｜√ 时序过激（XMP 不稳）｜√ 驱动/系统问题｜√ 供电不稳｜√ 混插兼容｜√ 接触不良｜√ CPU/主板问题（交叉替换排除）</p>\n<h5>4. 黑屏/不开机</h5>\n<p>√ 内存未装好（卡扣/方向）｜√ 内存损坏 ｜√ 主板/CPU 故障｜√ 电源不足｜√ BIOS 损坏（罕见）——先最小化系统缩小范围。</p>\n<h5>5. 过热报警</h5>\n<p>√ 散热片/马甲贴装不良 ｜√ 环境温度高｜√ 电压过高（XMP 加压）｜√ 风道设计｜√ 颗粒批次发热特性</p>\n<h5>6. 物理损坏</h5>\n<p>√ 运输磕碰 ｜√ 安装暴力 ｜√ 散热器压伤颗粒 ｜√ ESD 静电损伤 ｜√ 金手指断裂/氧化</p>\n<h5>7. 性能差/延迟高</h5>\n<p>√ 未开 XMP ｜√ 单通道误插（插错槽位）｜√ 混插降频 ｜√ 后台占用 ｜√ OS 未优化</p>\n<h5>8. 长时/高温随机出错</h5>\n<p>√ 颗粒余量不足 ｜√ 温压边界（HWiNFO 抓证据）｜√ 供电纹波 ｜√ IMC 体质 ｜√ 环境干扰（ESD/电源质量）</p>\n<div class=\"tip\">💡 每条根因都要能写出\"验证方法+判定依据\"，这就是考核要的\"≥4条并排序\"。排序按概率：接触问题 > 兼容性 > 颗粒 > 供电 > 环境。</div>"}, {"title": "频率不达标深度排查", "html": "<h5>1. 先定义\"达标\"（防止鸡同鸭讲）</h5>\n<p>客户说\"内存只有 2400\"——先问清楚：<b>标称多少？期望多少？怎么看出来的？（BIOS / CPU-Z / 任务管理器）</b>任务管理器/CPU-Z 显示的是当前实际频率，XMP 未开时按 JEDEC 保守档（如 DDR5-4800 / DDR4-2400）运行是<b>正常</b>的，不是故障。</p>\n<h5>2. 候选根因（按概率排序）</h5>\n<ol><li><b>未开启 XMP/EXPO</b>：频率停留在 JEDEC 档——占 80%；</li>\n<li><b>平台不支持/IMC 体质</b>：CPU 内存控制器上限不足；</li>\n<li><b>混插降频</b>：两根不同频率/颗粒的条子按慢的跑；</li>\n<li><b>散热不足降频</b>：温度过高自动降频；</li>\n<li><b>BIOS 设置/版本</b>：Gear 模式未选对、旧 BIOS 限制；</li>\n<li><b>插槽不对</b>：未插最优通道（A2+B2）。</li></ol>\n<h5>3. 排查动作（按顺序）</h5>\n<ul><li>看 CPU-Z <b>Memory 页</b>（当前频率/时序）vs <b>SPD 页</b>（XMP 档位——确认条子标称）；</li>\n<li>先确认 XMP/EXPO 是否已开启（BIOS 里 Memory Profile）；</li>\n<li>单条开 XMP 测试：排除混插干扰；</li>\n<li><b>频率换算</b>：实际频率 = 内存时钟 ×2（DDR 双沿），CPU-Z 显示 3000 = DDR4-6000？不——CPU-Z 的 DRAM Frequency 是时钟频率，DDR4-3200 显示 1600MHz，别算错；</li>\n<li>更新 BIOS 到支持该内存版本（早期 BIOS 对高频率支持不全）；</li>\n<li>手动放宽时序（如 CL 降档）或加内存电压试探 IMC 边界，记录结果。</li></ul>\n<h5>4. 判定标准</h5>\n<p><b>XMP 开启后跑到标称频率且稳定（压力测试过）= 达标</b>；跑不到但 JEDEC 默认稳定 = <b>平台体质/兼容问题</b>——要给客户解释\"内存没问题，是平台上限\"，并给出可执行建议（换插槽/升级 BIOS/保守频率）。</p>\n<h5>5. 沟通话术（高频场景）</h5>\n<div class=\"tip\">💡 \"别人买同款能上 6000\"——回复：\"每颗 CPU 的 IMC 体质不同，6000 是标称上限不是保证值。我先帮您确认 BIOS 设置和插槽，再试手动微调，尽量贴近标称。\"</div>\n<p>记住：<b>频率类客诉 80% 是设置问题，不是质量问题</b>——先教客户开 XMP，再谈排查。</p>"}, {"title": "不识别/容量错深度排查", "html": "<h5>1. \"不识别/容量错\"的三种级别（先定位层级！）</h5>\n<ul><li><b>BIOS 都不显示该条</b>：硬件级问题（接触/颗粒/SPD/槽/通道）；</li>\n<li><b>BIOS 显示容量错误</b>：SPD 数据错/颗粒坏/插槽限制；</li>\n<li><b>系统里容量少</b>：OS 位数限制/内存保留（集显共享）/最大内存设置/内存泄漏。</li></ul>\n<p>层级定了，排查范围缩小 80%——<b>第一步永远是问\"BIOS 显示多少\"</b>，而不是直接拆机。</p>\n<h5>2. 候选根因（按概率排序）</h5>\n<ol><li><b>接触不良</b>：金手指氧化、未插到位、槽内灰尘——最常见；</li>\n<li><b>SPD 数据错误/损坏</b>：字段错、刷写失败、二手条改过标；</li>\n<li><b>颗粒损坏/虚焊</b>：容量识别失败、通道坏；</li>\n<li><b>混插兼容</b>：不同容量/频率/颗粒混插降级或识别异常；</li>\n<li><b>主板通道限制</b>：某些平台单条容量上限、插槽位要求、CPU 内存通道坏；</li>\n<li><b>系统限制</b>：32 位系统 4GB 上限、msconfig 最大内存勾选、集显共享显存。</li></ol>\n<h5>3. 排查动作（按顺序）</h5>\n<ul><li>看 BIOS 识别 vs 系统识别，先定位层级；</li>\n<li>CPU-Z SPD 页读字段（容量/频率/厂商），确认标称与实际；</li>\n<li>单条各槽位逐测（定位插槽/条子/通道问题）；</li>\n<li>更新 BIOS；清 CMOS；恢复 BIOS 默认；</li>\n<li>系统里 msconfig → 引导 → 高级选项 → 查\"最大内存\"是否被勾选；</li>\n<li>任务管理器 → 性能 → 内存 → 看\"为硬件保留\"多少（集显共享会占用）。</li></ul>\n<h5>4. 判定树</h5>\n<table><tr><th>BIOS 显示</th><th>系统显示</th><th>结论方向</th></tr>\n<tr><td>正确</td><td>偏少</td><td>系统/软件层（保留/位数/设置）</td></tr>\n<tr><td>错误</td><td>错误</td><td>硬件/SPD 层（接触/颗粒/虚焊）</td></tr>\n<tr><td>插单条正确、两条错</td><td>—</td><td>混插兼容/通道问题</td></tr>\n<tr><td>时好时坏</td><td>—</td><td>接触不良/虚焊优先</td></tr></table>\n<div class=\"tip\">💡 常见翻车案例：客户报\"16GB 只有 8GB\"——结果是集显共享显存占了一半，不是内存坏。先问\"BIOS 显示多少\"，一句话省一天。</div>"}], "out": "\"不识别/容量错/频率不达标\"根因清单"}, {"id": "d24", "title": "现象④⑤：蓝屏死机重启 + 过热报警", "date": "Day 24 · 周四", "dot": "4", "tasks": ["蓝屏死机候选根因：颗粒不稳定、时序过紧、电压不足、驱动冲突、系统损坏、过热", "过热报警候选根因：散热片未贴、风道差、颗粒自发热、超频电压高、环境温度高", "学习蓝屏代码初步认识：0x1A(MEMORY_MANAGEMENT)、0x50(PAGE_FAULT)等", "更新映射表（各≥4条）"], "tools": "案例库、事件查看器、蓝屏代码速查", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV19G411Y7Jx", "label": "▶ 蓝屏终止代码KERNEL_DATA_INPAGE_ERROR（电脑蓝屏_南京小吧 · 6.8万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV12G411t7nf", "label": "▶ 不定时蓝屏重启·每次代码不同（其趣生活 · 1.1万播放）"}, {"type": "off", "url": "https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-checks-bug-check-code-reference", "label": "📄 微软蓝屏代码官方文档"}], "lectures": [{"title": "蓝屏代码：从 Code 到内存判断", "html": "<h5>1. 常见内存相关蓝屏代码（先看 Code 再动手）</h5>\n<table><tr><th>Code</th><th>名称</th><th>含义/方向</th></tr>\n<tr><td>0x1A</td><td>MEMORY_MANAGEMENT</td><td>内存管理异常，高度指向内存</td></tr>\n<tr><td>0x50</td><td>PAGE_FAULT_IN_NONPAGED_AREA</td><td>非分页区缺页，内存+驱动都要查</td></tr>\n<tr><td>0x7E/0x8E</td><td>SYSTEM_THREAD / KERNEL_MODE_EXCEPTION</td><td>多为驱动，也可由坏内存引起</td></tr>\n<tr><td>0x7A</td><td>KERNEL_DATA_INPAGE_ERROR</td><td>页面数据读入失败（内存/存储）</td></tr>\n<tr><td>0x0A</td><td>IRQL_NOT_LESS_OR_EQUAL</td><td>驱动问题为主，别急着赖内存</td></tr>\n<tr><td>0x3B</td><td>SYSTEM_SERVICE_EXCEPTION</td><td>驱动/服务异常，需看 dump 定位模块</td></tr>\n<tr><td>0xC4/0x1E</td><td>硬件相关代码</td><td>硬件错误，配合内存扫描确认</td></tr></table>\n<h5>2. 分析流程（Code → dump → 交叉验证）</h5>\n<ol><li>记录 <b>Code + 时间 + 场景</b>（游戏/待机/开机/特定软件）；</li>\n<li>启用小内存转储（Win+R → sysdm.cpl → 高级 → 启动和故障恢复 → 小内存转储 256KB）；</li>\n<li>WinDbg 打开 dump：<code>!analyze -v</code> 看 FAULTING_MODULE 定位故障模块；</li>\n<li><b>交叉验证</b>：MemTest86 全项扫描 → 0 Error 则内存嫌疑下降，重点查驱动/软件；有 Error 才指向内存；</li>\n<li>更新驱动/BIOS 复测；仍复现再深入（电压/时序/硬件替换）。</li></ol>\n<h5>3. 蓝屏反推：哪些场景更可能内存相关</h5>\n<ul><li>游戏高负载时随机蓝屏 + 内存错误 → 颗粒/时序/温度嫌疑高；</li>\n<li>待机/轻负载蓝屏 → 驱动/电源管理嫌疑高；</li>\n<li>开机即蓝屏 → 驱动冲突/硬件初始化；</li>\n<li>同一软件必现蓝屏 → 优先怀疑软件/驱动，别先赖内存。</li></ul>\n<h5>4. 客户要求快速结论时怎么说</h5>\n<p>\"蓝屏 Code 只是线索，不是判决书——我拿到 dump 分析 + 交叉跑一遍内存扫描，才能给您准确结论，预计 X 小时。\" 用纪律换取客户信任，而不是拍脑袋给答案。</p>\n<div class=\"warn\">⚠️ 铁律：蓝屏 Code 不是判决书——必须配合 dump 分析和内存扫描再下结论，这是客诉答辩的纪律，也是不背锅的护身符。</div>\n<div class=\"tip\">💡 记忆锚点：\"Code 定方向，dump 定模块，MT86 定内存\"——三步闭环，蓝屏客诉不再慌。</div>"}, {"title": "蓝屏/死机/重启深度排查", "html": "<h5>1. 收集关键信息</h5>\n<p>蓝屏不是\"现象\"而是\"结果\"。必须拿到：<b>蓝屏 Code + dump 文件 + 发生场景（游戏/待机/开机）+ 频率</b>。没有 Code 就无从下手。</p>\n<h5>2. 候选根因（按概率排序）</h5>\n<ol><li><b>内存不稳定</b>：XMP 过紧/颗粒体质差（MT86 验证）；</li>\n<li><b>驱动/系统问题</b>：显卡/芯片组驱动冲突、系统损坏（dump 分析）；</li>\n<li><b>供电不稳</b>：电源老化、主板供电不足；</li>\n<li><b>温度过高</b>：内存/CPU 过热；</li>\n<li><b>混插/接触不良</b>：多根条子时序不同步；</li>\n<li><b>超频过度</b>：CPU/内存同时超频互相干扰。</li></ol>\n<h5>3. 蓝屏 Code 速查（内存相关）</h5>\n<table><tr><th>Code</th><th>名称</th><th>方向</th></tr>\n<tr><td>0x1A</td><td>MEMORY_MANAGEMENT</td><td>高度指向内存</td></tr>\n<tr><td>0x50</td><td>PAGE_FAULT_IN_NONPAGED_AREA</td><td>内存或驱动</td></tr>\n<tr><td>0x7A</td><td>KERNEL_DATA_INPAGE_ERROR</td><td>内存或存储</td></tr>\n<tr><td>0x0A</td><td>IRQL_NOT_LESS_OR_EQUAL</td><td>驱动为主</td></tr></table>\n<h5>4. 排查流程</h5>\n<ol><li>获取 Code + dump（C:\\Windows\\Minidump）；</li>\n<li>MemTest86 基础扫描（排除硬件坏点）；</li>\n<li>关 XMP 回 JEDEC 档测试（排除超频不稳）；</li>\n<li>更新驱动/BIOS；</li>\n<li>交叉替换内存/主板/电源。</li></ol>\n<div class=\"warn\">⚠️ 不要只看 Code 就断言内存坏：0x1A 指向内存，但也可能 CPU 内存控制器问题。MT86 0 Error + 关 XMP 稳定 = 很大概率不是内存颗粒坏，而是设置/兼容问题。</div>"}], "out": "蓝屏/过热根因清单"}, {"id": "d25", "title": "现象⑥：物理损坏 + 周复盘", "date": "Day 25 · 周五", "dot": "5", "tasks": ["物理损坏候选根因：运输磕碰、插拔损坏、静电ESD、安装不当、主板卡扣问题", "学习物理损坏的判定证据：照片、外观检查、金手指痕迹", "完成映射表 V1：覆盖≥6现象 × ≥4根因，并排序", "完成《12周计划》W5 验收点打勾（导师抽问）"], "tools": "映射表V1、导师抽问清单", "resources": [], "lectures": [{"title": "物理损坏：判别与取证", "html": "<h5>1. 物理损坏的类型与成因</h5>\n<table><tr><th>类型</th><th>典型成因</th><th>外观特征</th></tr>\n<tr><td>金手指损伤</td><td>暴力插拔、插反、运输摩擦</td><td>划痕、掉点、氧化、变形</td></tr>\n<tr><td>颗粒损伤</td><td>散热器压伤、跌落、静电 ESD</td><td>鼓包、崩角、裂纹、烧焦</td></tr>\n<tr><td>PCB 损伤</td><td>弯曲、断裂、过热变黄</td><td>翘曲、线断、元件脱落</td></tr>\n<tr><td>静电损伤(ESD)</td><td>未佩戴防静电、干燥环境</td><td>外观可能正常，但功能异常</td></tr></table>\n<h5>2. 判别流程</h5>\n<ol><li><b>外观检查</b>：在光线下仔细看金手指、颗粒、PCB，拍照留证；</li>\n<li><b>是否可用</b>：上机测试（可能部分功能异常）；</li>\n<li><b>损伤定位</b>：通路测量（万用表）确认断路点；</li>\n<li><b>定性</b>：人为/运输/制程——三者的责任归属完全不同，<b>照片证据最关键</b>。</li></ol>\n<h5>3. 取证要点（客诉争议重灾区）</h5>\n<ul><li>收货拆包时拍照（含包装状态）；</li>\n<li>金手指损伤常见于\"客户装机时插反/硬拔\"——要问清操作过程；</li>\n<li>颗粒背面掉件/电容脱落要找制程证据（虚焊?受撞?）——交给研发判断。</li></ul>\n<h5>4. 判定与沟通</h5>\n<p>若判定人为/运输损坏：反馈客户证据 + 建议售后流程（非质量保修）。注意：<b>不要在没有照片证据时口头说\"客户弄坏的\"</b>，容易激化矛盾。话术：\"从金手指划痕看，推测安装过程中受力，能否提供操作过程照片进一步确认？\"</p>\n<div class=\"tip\">💡 ESD 静电损坏最隐蔽：外观看不出，上机偶发故障。防静电手环、操作规范是 FAE 现场必备。</div>"}], "out": "故障-根因映射表 V1 + W5周复盘"}]}, {"id": "w6", "badge": "W6", "title": "根因分层与诊断流程：排查路径图 + 交叉替换", "sub": "阶段 P2 · 形成不跳步的系统化排查能力", "accept": "对任意给定案例能画出排查路径图，不跳步。", "tools": "分析判断思路SOP、MT86、AIDA64、HWiNFO64", "phase": "P2", "weekend": "周末加油站：把排查路径图背诵成肌肉记忆；阅读 NTF 方法论背景；预习 W7 复现实验设计。 可选：看 WinDbg 蓝屏 dump 分析入门", "days": [{"id": "d26", "title": "信息收集 → 初步诊断", "date": "Day 26 · 周一", "dot": "1", "tasks": ["学习《分析判断思路SOP》第一步：信息收集（机型/平台/BIOS/内存型号/现象/概率/环境/操作）", "学习初步诊断：安装/接触/外观三步检查（金手指、插槽、卡扣）", "实操：拿一台测试机完整演练\"信息收集表\"填写", "理解\"信息不全就下结论\"是FAE第一大忌"], "tools": "分析判断思路SOP、信息收集表模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV19z4y1f7m5", "label": "▶ Outlook邮件技巧·分类管理（东方瑞通 · 1.5万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1afQoYnEvQ", "label": "▶ 客服邮件处理（邹阳FBM笔记 · 6827播放）"}], "lectures": [{"title": "信息收集模板：一次问全的 10 个字段", "html": "<h5>1. 为什么信息收集是第一步</h5>\n<p>FAE 90% 的坑来自信息不全就下结论。客户说\"内存坏了\"是<b>结果</b>，你要的是<b>过程事实</b>：什么环境、什么操作、什么现象、什么概率。信息收集的质量直接决定排查方向——收集错，后面全错。</p>\n<h5>2. 十字段模板（发给客户的填空版）</h5>\n<ol><li><b>客户/联系方式</b>：对接人 + 电话/企业微信（紧急时直接联系）；</li>\n<li><b>机型/品牌+SN</b>：整机厂牌型号 + 序列号（判批次/渠道）；</li>\n<li><b>主板型号+BIOS 版本</b>：BIOS 日期/版本号（很多问题随 BIOS 更新消失或出现）；</li>\n<li><b>CPU 型号</b>：IMC 代际差异（12 代 vs 13/14 代内存策略不同）；</li>\n<li><b>OS 版本+补丁</b>：Win10/11 大版本 + 累积更新（兼容性客诉常在这里）；</li>\n<li><b>内存型号+SN+批次+颗粒</b>：模组 PN、条码批次、颗粒厂商（同型号不同批次可能不同颗粒）；</li>\n<li><b>插槽位置/是否混插</b>：A1/A2/B1/B2 哪个槽、是否与其他品牌混用；</li>\n<li><b>现象描述+截图/视频</b>：蓝屏要 dump 文件/蓝屏照片，死机要录触发过程；</li>\n<li><b>复现概率+触发条件</b>：必现/偶发、开机/压力/冷机/热机/特定软件；</li>\n<li><b>环境+已做动作</b>：温度/供电/湿度，客户已经试过什么（换槽？单条？清CMOS？）。</li></ol>\n<h5>3. 每个字段的追问示例（拿到\"不够填\"时怎么追问）</h5>\n<ul><li>\"蓝屏\" → 追问：蓝屏代码是多少？什么时候开始？开着什么软件？截图发我；</li>\n<li>\"开不了机\" → 追问：有无报警声/指示灯？显示器有无信号？插几根条？</li>\n<li>\"偶尔死机\" → 追问：大概多久一次？重启后正常吗？是特定操作还是随机？</li>\n<li>\"性能差\" → 追问：和什么基准比？BIOS 里频率实际多少？XMP/EXPO 开了吗？</li></ul>\n<h5>4. 沟通技巧（让客户愿意配合）</h5>\n<ul><li>发<b>填空模板</b>（表格格式）比来回追问高效——客户填起来快，你也拿得全；</li>\n<li>要求<b>截图/视频而非口头描述</b>：\"蓝屏\"要有照片+dump，\"报错\"要有截图（很多问题看一眼截图就定性了）；</li>\n<li>进度<b>主动同步</b>销售/客户，避免\"失联\"猜疑；</li>\n<li>一次问全 vs 挤牙膏：宁可第一次多问几项，别\"想到哪问到哪\"——客户会觉得你没章法。</li></ul>\n<h5>5. 常见\"信息陷阱\"提醒</h5>\n<ul><li>客户说\"换了内存就好\" ≠ 旧条一定坏——可能只是旧条与平台配合问题；</li>\n<li>客户说\"两根都试过\" 要确认：是\"两根都不行\"还是\"每根单独都行、两根一起不行\"（后者是兼容性/供电问题）；</li>\n<li>BIOS 版本必问——刷了 Beta BIOS 后的\"新故障\"可能版本引入；</li>\n<li>拍照要求：金手指正反面、整条标签、插槽位、蓝屏/报错画面，缺一不可。</li></ul>\n<div class=\"tip\">💡 把十字段做成一张 Excel/表格模板存桌面，接单直接发给客户填——这是 FAE 的第一个\"趁手工具\"。</div>"}, {"title": "金手指外观检查速查", "html": "<h5>1. 初步诊断第一步：看金手指（工具：手电 + 放大镜/微距拍照）</h5>\n<p>五类高频外观问题要一眼分得清：<b>氧化、划伤、掉点/镀层破损、弯曲变形、污染（助焊剂/油污/汗渍）</b>。每条都要用微距图取证。</p>\n<h5>2. 判定参考表（对着照片分级）</h5>\n<table><tr><th>现象</th><th>可能成因</th><th>处理建议</th></tr>\n<tr><td>整排均匀发暗/发绿</td><td>存放过久、环境潮湿（硫化/氧化）</td><td>重新插拔多次（摩擦去氧化膜），多数可改善；无效则换条</td></tr>\n<tr><td>局部划伤 + 对应插槽位复现故障</td><td>插拔摩擦、插槽内有异物/毛刺</td><td>锁定该金手指与槽位，检查插槽；必要时换槽</td></tr>\n<tr><td>金面缺失/掉点（露铜）</td><td>镀金层磨穿、返工损坏</td><td>直接判定不可用，换条（镀层破损会接触电阻升高）</td></tr>\n<tr><td>边缘弯曲/变形</td><td>安装受力不均、卡扣未到位</td><td>检查卡扣与安装方向，变形严重则换条</td></tr>\n<tr><td>表面污染（助焊剂残留/油污）</td><td>制程残留、手触碰</td><td>无水酒精+无尘布轻擦（仅限轻度污染），擦后吹干再装</td></tr></table>\n<h5>3. 为什么金手指外观会引发\"奇奇怪怪\"的故障</h5>\n<p>金手指与插槽弹片靠<b>接触压力</b>导通。氧化膜/污染/划伤都会增大接触电阻：高速信号（DQ/DQS 上千兆）对接触阻抗极敏感，轻微劣化就表现为<b>偶发蓝屏、开机报警、同一条换个槽就正常</b>——这就是\"看起来像坏、换槽又好了\"的常见来源。</p>\n<h5>4. 处理边界（重要！）</h5>\n<ul><li><b>橡皮擦</b>：很多人会试，但会磨损镀金层且留屑，只适用于\"死马当活马医\"的应急，不推荐作为标准动作；</li>\n<li><b>酒精</b>：只处理油污类轻度污染，先断电再操作，擦完彻底晾干；</li>\n<li><b>严禁</b>用砂纸/利器刮金手指——直接报废。</li></ul>\n<h5>5. 和客户沟通（一句话模板）</h5>\n<p>\"请拍一张金手指的清晰照片发我们，正反两面都要\"——这是初步诊断<b>最便宜也最有效</b>的动作，很多接触类问题一眼定性，比让客户来回换货强得多。</p>\n<div class=\"tip\">💡 现场铁律：先拍照取证，再动手处理。同一根条子拔插前后的照片对比，就是最好的判定证据。</div>"}], "out": "一份完整填写的信息收集表"}, {"id": "d27", "title": "最小化 → 交叉替换", "date": "Day 27 · 周二", "dot": "2", "tasks": ["学习\"最小化系统\"：只保留 CPU+1内存+集显/最小启动，逐件加回", "学习交叉替换法：内存/主板/CPU 两两替换定位故障边界", "实操：用一台机器做\"单根内存 A/B 槽位\"交叉测试", "画出\"交叉替换判定表\"（部件A好/坏 × 部件B好/坏的组合）"], "tools": "SOP、交叉替换工具表", "resources": [], "lectures": [{"title": "最小化系统 + 交叉替换：定位故障的黄金法则", "html": "<h5>1. 最小化系统（先从最少零件开始）</h5>\n<p>最小化 = 只用最小必要硬件排除故障：<b>CPU + 1 根内存（A2 槽最优）+ 集显/最小显卡 + 电源</b>，不接硬盘/SATA/USB 外设。做法：逐步外设一件一件加回去，加到哪一步出问题，嫌疑就在哪一步。</p>\n<h5>2. 交叉替换法（换件定位）</h5>\n<p>当两个部件可能互相影响时（如内存 vs 主板插槽），用<b>交叉组合</b>定位：</p>\n<table><tr><th>组合</th><th>好内存+好主板</th><th>疑似坏内存+好主板</th><th>好内存+疑似坏主板</th></tr>\n<tr><td>现象</td><td>正常</td><td>出问题</td><td>出问题</td></tr>\n<tr><td>结论</td><td>基线</td><td>指向内存</td><td>指向主板</td></tr></table>\n<h5>3. 操作纪律</h5>\n<ul><li>每次只换一个变量（\"换内存又换槽位\"就没法定位）；</li>\n<li>替换用<b>已知正常件</b>（不能用\"疑似坏内存\"互相测）；</li>\n<li>记录每一步现象与结论，形成判定表；</li>\n<li>内存故障定位顺序：换槽 → 换条 → 换平台 → 电气测量。</li></ul>\n<h5>4. 客户现场应用</h5>\n<p>客户报\"内存坏\"，不要急着说\"那就换条\"——先让他做最小化+交叉：单条 A2 槽能否开机？两根单独各测一次？把结果发你，你就能判断是条子、插槽还是主板。</p>\n<div class=\"tip\">💡 交叉替换判定表是面试/考核常客：能画出这张表，说明你真的懂\"用实验隔离变量\"。</div>"}], "out": "交叉替换判定表（自己设计的模板）"}, {"id": "d28", "title": "BIOS 默认 → 深入分析（信号/温压/边界）", "date": "Day 28 · 周三", "dot": "3", "tasks": ["学习\"恢复BIOS默认再测\"：排除软设置干扰的正确步骤", "深入分析三件套：信号（示波器入门）、温压（HWiNFO64）、边界（超频/降频对照）", "实操：一个疑似\"频率不稳\"案例，走 BIOS默认→加压→降频全流程", "学习 AIDA64 压力测试解读传感器数据"], "tools": "BIOS、HWiNFO64、AIDA64、示波器入门", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1b1BKB8EdX", "label": "▶ 保姆级XMP/EXPO开启教程（无敌电脑大王 · 2.9万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV113411i7eS", "label": "▶ 简谈内存SPD、刷写XMP（吗吗哈哈 · 8625播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Intel_Extreme_Memory_Profile", "label": "📄 维基百科·Intel XMP"}], "lectures": [{"title": "BIOS 内存项 + XMP/EXPO 机制", "html": "<h5>1. BIOS 内存菜单常见项</h5>\n<ul><li><b>Memory Frequency/比率</b>：手动频率或自动（Auto/By SPD）；</li>\n<li><b>XMP/EXPO Profile</b>：一键载入超频配置；</li>\n<li><b>DRAM 电压</b>：DDR5 常见 VDDQ/VDD（1.35V 为 XMP 常用值），加电压提高稳定性但升温；</li>\n<li><b>Gear Mode（Intel）</b>：Gear1/Gear2 选择；</li>\n<li><b>Memory Training / 重新训练</b>：开机训练记忆参数，老主板换条后建议清内存训练。</li></ul>\n<h5>2. XMP/EXPO 原理</h5>\n<p>SPD 里除了 JEDEC 标准档，还有一个（或多个）<b>超频 Profile</b>：指定了更高频率+时序+电压。BIOS 开启后按 Profile 跑，而不是按 JEDEC 保守档。</p>\n<h5>3. XMP 开启后不稳定的常见原因</h5>\n<ol><li>IMC 体质不够（CPU 不行）；</li>\n<li>电压不足（需要手动微增 VDDQ/SA）；</li>\n<li>散热不足（高温降频/不稳）；</li>\n<li>主板 BIOS 兼容性差（需更新）；</li>\n<li>混插不同频率/不同颗粒条子。</li></ol>\n<h5>4. 恢复 BIOS 默认的正确做法</h5>\n<p>进 BIOS → Load Defaults / 恢复默认设置 → 保存重启；必要时短接 CMOS 跳线或拔电池 30 秒。恢复默认后内存回到 JEDEC 档，用来排除\"超频设置导致的故障\"。</p>\n<div class=\"tip\">💡 排查客诉\"一开 XMP 就重启\"：先恢复默认确认 JEDEC 档稳定 → 再逐步开 XMP → 最后微调电压/降频定位边界。</div>"}, {"title": "HWiNFO64 使用详解：温压监控 + 日志", "html": "<h5>1. 是什么</h5>\n<p>免费硬件信息与传感器监控工具（<a href=\"https://www.hwinfo.com/\" target=\"_blank\" rel=\"noopener\">官网</a>）。FAE 用它看<b>温度、电压、频率</b>，判断稳定性问题的环境因素。</p>\n<h5>2. 关键界面</h5>\n<ul><li>启动选<b> Sensors-only（仅传感器）</b> 模式；</li>\n<li>找 <b>DIMM/内存温度</b>：DDR5 条子通常带温度传感器（TS）；</li>\n<li>看 <b>VDDQ / VDD 电压</b>：是否稳定在 1.1V/1.35V（XMP）附近；</li>\n<li>看 <b>CPU/主板供电温度</b>：过热会影响内存稳定性。</li></ul>\n<h5>3. 抓日志（重要）</h5>\n<ol><li>Sensors 窗口 → 工具栏点击 <b>Logging（日志）</b> 按钮；</li>\n<li>设置间隔（如 1 秒）与保存路径（CSV）；</li>\n<li>开始记录后去跑压力测试/复现故障场景；</li>\n<li>故障发生后停止日志，Excel 打开 CSV 看\"温度/电压在崩溃前发生了什么\"。</li></ol>\n<h5>4. 与故障窗口关联</h5>\n<p>NTF/偶发问题最难的就是\"没有现场\"。HWiNFO64 日志能回答：<b>蓝屏前 1 分钟内存温度是不是飙了？电压是不是掉了？</b>——这是环境类根因的直接证据。</p>\n<div class=\"tip\">💡 客户现场支持，第一件事先开 HWiNFO64 记录——等故障发生时你就有完整数据，而不是空手回去。</div>"}, {"title": "AIDA64 使用详解：内存压力 + 性能基准", "html": "<h5>1. 是什么</h5>\n<p>系统检测与基准测试工具（<a href=\"https://www.aida64.com/\" target=\"_blank\" rel=\"noopener\">官网</a>）。FAE 用两块：<b>稳定性压力测试</b> 和 <b>内存性能基准</b>。</p>\n<h5>2. 稳定性测试（工具→系统稳定性测试）</h5>\n<ul><li>勾选 <b>Stress Memory</b>（或 Stress CPU 一起模拟整机负载）；</li>\n<li>下方实时显示温度/占用；推荐 30min-1h 起步；</li>\n<li>报错时看是 CPU 还是内存项报错，配合传感器判读。</li></ul>\n<h5>3. 内存性能基准（工具→Cache & Memory Benchmark）</h5>\n<ul><li>结果含 Read / Write / Copy / Latency 四项；</li>\n<li>用于判断条子是否达到标称性能、开 XMP 前后的差异；</li>\n<li>对比基线：同型号条子、同平台正常值。</li></ul>\n<h5>4. FAE 用法</h5>\n<p>客户报\"内存性能差\" → AIDA64 跑基准 → 和同配置正常值对比 → 若 Read 掉半 → 检查是否被降频/单通道/混插。数据说话，别凭感觉。</p>\n<div class=\"tip\">💡 AIDA64 的内存延迟（Latency）是判断\"时序设置是否激进\"的好指标：延迟异常高 → 可能 Gear 分频/时序过松。</div>"}, {"title": "示波器入门：深入分析的\"信号放大镜\"", "html": "<h5>1. 示波器在内存排查中的角色</h5>\n<p>当\"会不会是信号问题\"时，示波器能看：<b>供电纹波、关键信号有无、信号电平是否达标</b>（入门级看\"有/没有、对不对\"即可）。</p>\n<h5>2. 三个入门测量</h5>\n<ul><li><b>VDD/VDDQ 纹波</b>：AC 耦合看幅值，纹波过大（>50mV 级）指向供电质量；</li>\n<li><b>DQS/DQ 有无活动</b>：开机/自检时测量数据线上是否有波形；</li>\n<li><b>时钟信号（CLK）</b>：是否稳定存在（CLK 丢失=插槽/接触问题）。</li></ul>\n<h5>3. 安全提示</h5>\n<p>探头先接地再接触信号；测供电用直流耦合、测纹波用 AC 耦合；不要带电插拔探头连接线。</p>\n<h5>4. 什么时候用</h5>\n<p>普通客诉不必上示波器；<b>疑似供电/信号/高频不稳定</b>时才需要。用它验证\"电压是否正确、信号是否存在\"，把问题从模糊变成具体。</p>"}], "out": "深入分析动作清单（可复用Checklist）"}, {"id": "d29", "title": "绘制排查路径图", "date": "Day 29 · 周四", "dot": "4", "tasks": ["画出完整排查路径图：信息收集→初诊→最小化→交叉替换→BIOS默认→深入分析", "学习\"不跳步\"原则：每一步都有判定标准，先过再走下一步", "用 2 个真实案例画出个性化路径图", "路径图评审：请导师检查逻辑闭环"], "tools": "SOP、XMind/白板工具", "resources": [], "lectures": [{"title": "排查路径图：不跳步的排障地图", "html": "<h5>1. 为什么要有路径图</h5>\n<p>内存问题千奇百怪，但排查套路是固定的。路径图 = 把套路<b>画成决策树</b>，每一步都有<b>判定标准</b>，满足才进下一步。好处：<b>不跳步、不遗漏、可复现、可教人</b>——一个人跑是经验，画成图是资产。</p>\n<h5>2. 标准七层路径（背诵，刻进肌肉）</h5>\n<pre>\n现象记录（现象/概率/环境/版本）\n   ↓ 信息收集完毕？\n信息收集模板补齐（缺字段先问全）\n   ↓\n初步诊断：安装/接触/外观（金手指/插槽/卡扣）\n   ↓\n最小化环境：单条、单槽（A2）、清BIOS\n   ↓\n交叉替换：内存/主板/CPU 定位边界\n   ↓\nBIOS默认 + XMP对照测试（软设置隔离）\n   ↓\n深入分析：MT86/长测/温压/信号（万用表/示波器）\n   ↓\n根因定性 → 对策 → 验证 → 报告\n</pre>\n<h5>3. 每层的判定标准（写清楚才能不跳步）</h5>\n<table><tr><th>层</th><th>判定标准（过/不过）</th></tr>\n<tr><td>信息收集</td><td>字段齐全才算过（缺现象概率就继续问）</td></tr>\n<tr><td>外观/接触</td><td>金手指无氧化划伤 + 插槽无异物 + 卡扣到位</td></tr>\n<tr><td>最小化</td><td>单条 A2 能否点亮/稳定（能 → 多根/混插问题）</td></tr>\n<tr><td>交叉替换</td><td>换条/换槽/换平台 现象跟谁走（跟条=条坏，跟槽=板坏）</td></tr>\n<tr><td>BIOS/XMP</td><td>默认是否稳定 / 开 XMP 是否复现（复现→频率时序相关）</td></tr>\n<tr><td>深入分析</td><td>MT86 0 Error？温度曲线？电压正常？</td></tr></table>\n<h5>4. 画图技巧（输出物质量）</h5>\n<ul><li>用流程图图形（矩形=动作、菱形=判断）或大纲树——<b>菱形判断要写\"是→往哪、否→往哪\"</b>；</li>\n<li>每个分支标结论去向，避免画成\"只有路径没有出口\"；</li>\n<li>真实案例复盘时\"回填\"路径：某案例卡在第几步、是哪层判定漏了，就是你的瓶颈；</li>\n<li>路径图要能\"倒着读\"：从现象出发，反推出最少验证步骤。</li></ul>\n<h5>5. 考核要求（高频考点）</h5>\n<p>\"对任意案例能画出路径图，不跳步\"——画完自问：<b>如果客户只给了这些信息，我能走到哪一步？缺什么信息？</b>答得出，就达标。面试/答辩常让你现场画某现象的路径图，背下七层 + 会回填 = 稳。</p>\n<div class=\"tip\">💡 记忆锚点：\"现象→收集→外观→最小化→交叉→BIOS→深入\"——七层口诀，走到哪层都有判定，才是真排障。</div>"}], "out": "标准排查路径图 + 2个案例路径图"}, {"id": "d30", "title": "案例演练 + 周复盘", "date": "Day 30 · 周五", "dot": "5", "tasks": ["导师给 1 个全新案例，独立走查排查路径（不许跳步）", "输出排查过程记录：每一步判断依据", "完成《12周计划》W6 验收点打勾", "周复盘：把路径图更新进知识库"], "tools": "新案例、路径图模板、验收清单", "resources": [], "lectures": [{"title": "案例演练：把路径图跑一遍", "html": "<h5>1. 演练方法（导师给案例或自己造案例）</h5>\n<p>拿到一个新现象（如\"开机风扇转但不亮屏\"、\"两根条只认一根\"、\"频率只有2400\"），不查答案，按路径图一步步走，每步写下判断依据。</p>\n<h5>2. 演练评分点</h5>\n<ul><li>是否先补齐信息再动手？</li>\n<li>是否做了外观/接触检查（别上来就换内存）？</li>\n<li>是否做最小化+交叉？替换时是否只动一个变量？</li>\n<li>是否用数据佐证结论（MT86 日志/频率截图）？</li>\n<li>是否能给出临时对策且说明边界？</li></ul>\n<h5>3. 演练后复盘三问</h5>\n<ol><li>我卡在哪一步？为什么卡？（知识缺失？信息不全会？工具不会用？）</li>\n<li>导师/同事是怎么处理的？和我差在哪？</li>\n<li>我的路径图需要更新吗？（新增案例=新增分支）</li></ol>\n<h5>4. 进阶</h5>\n<p>每周挑 1 个真实案例做\"无声演练\"：写下来 → 对照标准答案 → 标出差错 → 归档。这样做一个月，排查思路会形成肌肉记忆。</p>\n<div class=\"tip\">💡 案例演练是考核\"分析判断思路\"的核心证据，练得越多答辩越稳。</div>"}], "out": "独立案例排查记录 + W6复盘"}]}, {"id": "w7", "badge": "W7", "title": "NTF偶发故障专项：复现 + 交叉验证 + 压力复测 + 批次对比", "sub": "阶段 P2 · 搞定\"消失的故障\"，用证据链说话", "accept": "在模拟NTF案例中复现并给出结论与证据链。", "tools": "MonitorMemtest、BurnInTest、版本/批次对照表", "phase": "P2", "weekend": "周末加油站：复习 W5-W7 的映射表+路径图+NTF证据链；预习 W8 沟通话术手册。 可选：学习\"如何写技术邮件\"范例 3 篇", "days": [{"id": "d31", "title": "NTF 方法论：为什么会有\"找不到故障\"", "date": "Day 31 · 周一", "dot": "1", "tasks": ["学习 NTF（No Trouble Found）定义与产生原因", "学习 NTF 方法论五板斧：交叉验证、复现环境搭建、压力复测、批次对比、版本比对", "理解区分四类：真不良/假性不良/人为故障/环境干扰", "从案例库找 1 个 NTF 案例看处理过程"], "tools": "NTF方法论资料、案例库", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1mp421m7aV", "label": "▶ 风扇正常转但黑屏无信号·解决（国丰装机 · 240.4万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1qV411S7g9", "label": "▶ 黑屏/蓝屏/闪退最全解决办法（大明湖畔千百万 · 7.0万播放）"}, {"type": "off", "url": "https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-checks-bug-check-code-reference", "label": "📄 微软蓝屏代码官方文档"}], "lectures": [{"title": "TOP 故障现象 → 候选根因 + 验证方法", "html": "<h5>1. 不识别/容量错</h5>\n<p>√ 插槽接触不良（重插/换槽）｜√ SPD 损坏或数据错误（查 SPD 二进制）｜√ 颗粒虚焊/损坏｜√ 主板 BIOS 不兼容（更新/查 QVL）｜√ 混插不匹配｜√ 32 位系统限制（4GB 上限）｜√ 金手指氧化</p>\n<h5>2. 频率不达标</h5>\n<p>√ 未开 XMP/EXPO ｜√ IMC 体质不足｜√ 混插降频（不同频率条子取最低）｜√ 散热降频｜√ BIOS 旧版｜√ 电压不足</p>\n<h5>3. 蓝屏/死机/重启</h5>\n<p>√ 颗粒不良（MT86 定性）｜√ 时序过激（XMP 不稳）｜√ 驱动/系统问题｜√ 供电不稳｜√ 混插兼容｜√ 接触不良｜√ CPU/主板问题（交叉替换排除）</p>\n<h5>4. 黑屏/不开机</h5>\n<p>√ 内存未装好（卡扣/方向）｜√ 内存损坏 ｜√ 主板/CPU 故障｜√ 电源不足｜√ BIOS 损坏（罕见）——先最小化系统缩小范围。</p>\n<h5>5. 过热报警</h5>\n<p>√ 散热片/马甲贴装不良 ｜√ 环境温度高｜√ 电压过高（XMP 加压）｜√ 风道设计｜√ 颗粒批次发热特性</p>\n<h5>6. 物理损坏</h5>\n<p>√ 运输磕碰 ｜√ 安装暴力 ｜√ 散热器压伤颗粒 ｜√ ESD 静电损伤 ｜√ 金手指断裂/氧化</p>\n<h5>7. 性能差/延迟高</h5>\n<p>√ 未开 XMP ｜√ 单通道误插（插错槽位）｜√ 混插降频 ｜√ 后台占用 ｜√ OS 未优化</p>\n<h5>8. 长时/高温随机出错</h5>\n<p>√ 颗粒余量不足 ｜√ 温压边界（HWiNFO 抓证据）｜√ 供电纹波 ｜√ IMC 体质 ｜√ 环境干扰（ESD/电源质量）</p>\n<div class=\"tip\">💡 每条根因都要能写出\"验证方法+判定依据\"，这就是考核要的\"≥4条并排序\"。排序按概率：接触问题 > 兼容性 > 颗粒 > 供电 > 环境。</div>"}, {"title": "NTF 专项：从\"复现不了\"到\"证据链完整\"", "html": "<h5>1. NTF 的本质</h5>\n<p>NTF（No Trouble Found）= 客户报障，但你在标准测试环境复现不出来。它不是\"白忙一场\"，而是<b>要求你有\"没有结论的结论\"</b>——即用证据链说明\"为什么没复现、问题可能在哪、下一步怎么办\"。</p>\n<h5>2. 关键误区</h5>\n<ul><li>❌ 复现不了就说\"内存没问题\"——证据不足，客户不信；</li>\n<li>❌ 复现不了就换一条给客户——掩盖问题，下次还来；</li>\n<li>✅ 正确的：完整记录复现条件和所有阴性结果，推导可能方向。</li></ul>\n<h5>3. NTF 五步法</h5>\n<ol><li><b>完整复现环境</b>：还原客户 BIOS/OS/场景/温度；</li>\n<li><b>压力复测</b>：8h+ 内存压力 + 循环脚本（S3/S4/Reboot）；</li>\n<li><b>交叉验证</b>：同型号多条、多平台互测；</li>\n<li><b>批次/版本对比</b>：不同批次、不同 BIOS 版本；</li>\n<li><b>证据链报告</b>：现象→环境→测试→阴性结果→推断→待验证。</li></ol>\n<h5>4. 四类定性</h5>\n<p><b>真不良</b>（复现到错误）/ <b>假性不良</b>（环境影响）/ <b>人为故障</b>（操作不当）/ <b>环境干扰</b>（ESD/电源）。每种都要有证据支撑，宁缺毋滥。</p>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。</p>\n<h5>2. 每例 <200 字的推荐格式</h5>\n<pre>案例编号：FAE-2026-XXX\n现象：一句话\n平台：主板/CPU/OS/内存型号\n根因：一句话\n证据：日志/截图路径\n对策：临时+永久\n状态：已闭环/复核中</pre>\n<h5>3. 什么案例值得记</h5>\n<ul><li>第一次遇到的故障类型；</li>\n<li>排查过程走弯路的（教训最值钱）；</li>\n<li>证据链完整、能当培训材料的；</li>\n<li>客户高频问题（同问必记）。</li></ul>\n<h5>4. 归档节奏</h5>\n<p>客诉闭环当天顺手记一例（30 秒的事），月底统一补标签和索引。目标：<b>12 周 ≥10 例，一年 ≥30 例</b>。</p>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。</div>"}], "out": "NTF 方法论思维导图"}, {"id": "d32", "title": "复现环境搭建", "date": "Day 32 · 周二", "dot": "2", "tasks": ["学习复现要素：同平台/同BIOS/同OS/同负载/同环境温度", "实操：为\"每月一次蓝屏\"设计复现实验（压力+场景模拟）", "学习记录复现条件：时间/温度/负载/运行软件清单", "搭建个人复现实验清单模板"], "tools": "复现实验模板、压力工具", "resources": [], "lectures": [{"title": "复现环境搭建：让\"偶发\"现形", "html": "<h5>1. 复现环境 = 还原客户现场</h5>\n<p>NTF 案例复现不了，90% 是因为环境不一致。复现环境要尽量还原：<b>同平台（主板/BIOS 版本）、同内存组合（插槽/混插）、同 OS/驱动、同负载场景、同温度环境</b>。</p>\n<h5>2. 复现五要素清单</h5>\n<ul><li><b>硬件</b>：主板型号+BIOS 版本、CPU、内存插槽、是否混插；</li>\n<li><b>软件</b>：OS 版本+补丁、驱动版本、BIOS 设置（XMP 开没开）；</li>\n<li><b>负载</b>：什么软件导致（游戏/渲染/多开）、内存占用比例；</li>\n<li><b>时序</b>：什么时候发生（开机/运行中/休眠唤醒）、频率；</li>\n<li><b>环境</b>：室温、机箱风道、供电（插座/稳压器）。</li></ul>\n<h5>3. 复现实验设计</h5>\n<ul><li>用客户给的场景驱动：如\"玩某游戏 30 分钟蓝屏\"→ 跑对应压力场景 + 8h 长测；</li>\n<li>循环脚本设计：S3/S4 休眠唤醒 ×100、Reboot ×100；</li>\n<li>监控：HWiNFO64 记录温压曲线，出现故障瞬间的数据是关键证据。</li></ul>\n<div class=\"warn\">⚠️ 常见误区：拿\"自己标准环境\"复测客户案例，测不出来就说\"内存没问题\"——这是不专业的。要先对齐环境再下结论。</div>"}], "out": "复现实验设计文档（针对案例）"}, {"id": "d33", "title": "压力复测 + 版本比对", "date": "Day 33 · 周三", "dot": "3", "tasks": ["设计并执行 8h+ MonitorMemtest/BurnInTest 压力复测", "学习版本比对：BIOS版本、驱动版本、颗粒版本对故障的影响", "实操：同一故障现象在不同 BIOS 版本下复测对比", "建立《版本/批次对照表》记录格式"], "tools": "MonitorMemtest、BurnInTest、版本记录表", "resources": [], "lectures": [{"title": "压力复测 + 版本比对：给间歇性问题加码", "html": "<h5>1. 压力复测策略</h5>\n<ul><li><b>8h 起步</b>：MonitorMemtest / BurnInTest RAM ≥90% 8h+；</li>\n<li><b>满负载组合</b>：内存+CPU+磁盘同时压（模拟真实重负载）；</li>\n<li><b>循环场景</b>：休眠唤醒循环、重启循环，暴露\"偶发\"性问题；</li>\n<li><b>记录</b>：故障时间点 ↔ 温度/电压/占用率对照。</li></ul>\n<h5>2. 版本比对（常见\"假凶手\"）</h5>\n<ul><li><b>BIOS 版本</b>：旧版本可能有内存兼容 bug，更新后可能解决；</li>\n<li><b>驱动/OS 补丁</b>：显卡/芯片组驱动冲突可模拟内存故障；</li>\n<li><b>颗粒固件/SPD 版本</b>：同型号不同批次写法不同。</li></ul>\n<h5>3. 对照表做法</h5>\n<table><tr><th>变量</th><th>版本A</th><th>版本B</th><th>结果</th></tr>\n<tr><td>BIOS</td><td>v1.20</td><td>v1.40</td><td>B 稳定、A 复现 → 指向 BIOS</td></tr>\n<tr><td>驱动</td><td>旧</td><td>新</td><td>……</td></tr></table>\n<p>每次只换一个变量，结论才有意义。</p>\n<div class=\"tip\">💡 客户说\"昨天还好好的今天死机\"——第一反应查\"最近更新了什么\"（BIOS/驱动/补丁），而不是盯着内存看。</div>"}], "out": "压力复测日志 + 版本对照表首行"}, {"id": "d34", "title": "批次对比 + 区分真假不良", "date": "Day 34 · 周四", "dot": "4", "tasks": ["学习批次号解读：从条码/标签识别生产批次、颗粒批次", "学习批次对比实验：不同批次同型号条子交叉验证", "学习真不良(数据确凿) vs 假性不良(环境/驱动/人为) vs 环境干扰(ESD/电源)的判断逻辑", "用 2 个旧案例练习\"贴标签\"：真/假/人为/环境"], "tools": "批次对照表、历史案例", "resources": [], "lectures": [{"title": "批次对比 + 真/假不良判别", "html": "<h5>1. 批次号怎么看</h5>\n<p>模组标签上一般有 <b>PN（型号）+ SN（序列号）+ 批次码 / 日期码</b>。颗粒本体上还有颗粒批次（如 2341 = 23 年第 41 周）。排障时记录完整条形码信息——这是追溯的钥匙。</p>\n<h5>2. 批次对比实验</h5>\n<ul><li>同型号不同批次条子交叉测试：是\"这批都坏\"还是\"单条问题\"？</li>\n<li>同批次多根条子测：若成片不良 → 批次制程问题（找生产/PQE）；</li>\n<li>不同批次对照：新批次修复了 → 版本/工艺变更影响。</li></ul>\n<h5>3. 四类不良判别卡</h5>\n<table><tr><th>类型</th><th>特征</th><th>证据要求</th></tr>\n<tr><td>真不良</td><td>MT86 有 Error、数据可复现</td><td>日志/地址/照片</td></tr>\n<tr><td>假性不良</td><td>环境/驱动/设置导致</td><td>对照实验（换环境消失）</td></tr>\n<tr><td>人为故障</td><td>安装错误、刷坏 SPD、超压</td><td>外观/操作记录</td></tr>\n<tr><td>环境干扰</td><td>ESD、电源质量、高温</td><td>温压记录/现场环境</td></tr></table>\n<div class=\"warn\">⚠️ 判定纪律：没有证据不下\"真坏\"，没有对照不下\"没问题\"。给客户的结论必须落在证据上。</div>"}], "out": "批次对比实验记录 + 四类不良判别卡"}, {"id": "d35", "title": "模拟 NTF 案例：结论与证据链", "date": "Day 35 · 周五", "dot": "5", "tasks": ["完成 1 个模拟 NTF 案例：从复现→证据→结论全流程", "输出 NTF 报告：现象/复现条件/测试数据/结论/证据链", "请导师评审证据链是否完整、结论是否过度", "完成《12周计划》W7 验收点打勾 + 周复盘"], "tools": "NTF案例包、报告模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1gaFez8EFT", "label": "▶ 电脑不定时死机卡住重启怎么办（程工修笔记本 · 5683播放）"}], "lectures": [{"title": "NTF 方法论：找不到故障时的破案纪律", "html": "<h5>1. 什么是 NTF</h5>\n<p>NTF（No Trouble Found）＝客户报障但标准流程测不出问题。价值不在\"找到了\"，而在<b>证据链完整</b>，能对客户交代\"为什么没找到、怎么保证不是我们的问题\"。</p>\n<h5>2. 五板斧</h5>\n<ol><li><b>交叉验证</b>：多条同型号互相换机换槽，确认是否单条问题；</li>\n<li><b>复现环境搭建</b>：还原客户平台/BIOS/OS/负载/温度，不还原就复现不了；</li>\n<li><b>压力复测</b>：8h+ BurnInTest/MonitorMemtest、循环脚本；</li>\n<li><b>批次对比</b>：不同生产批次/颗粒批次交叉测；</li>\n<li><b>版本比对</b>：BIOS/驱动/固件版本差异是常见\"假凶手\"。</li></ol>\n<h5>3. 四类结论</h5>\n<ul><li><b>真不良</b>：有数据实证（MT86 地址、复测日志）；</li>\n<li><b>假性不良</b>：环境/驱动/设置问题（证据链指向非内存）；</li>\n<li><b>人为故障</b>：安装/操作不当（插反、超压、刷坏 SPD）；</li>\n<li><b>环境干扰</b>：ESD、电源质量、温度、电磁干扰。</li></ul>\n<div class=\"warn\">⚠️ NTF 报告切忌\"结论过度\"：没有证据不能说是真不良，也不能硬说没问题。给\"证据链 + 待验证项\"是最职业的写法。</div>"}, {"title": "NTF 专项：从\"复现不了\"到\"证据链完整\"", "html": "<h5>1. NTF 的本质</h5>\n<p>NTF（No Trouble Found）= 客户报障，但你在标准测试环境复现不出来。它不是\"白忙一场\"，而是<b>要求你有\"没有结论的结论\"</b>——即用证据链说明\"为什么没复现、问题可能在哪、下一步怎么办\"。</p>\n<h5>2. 关键误区</h5>\n<ul><li>❌ 复现不了就说\"内存没问题\"——证据不足，客户不信；</li>\n<li>❌ 复现不了就换一条给客户——掩盖问题，下次还来；</li>\n<li>✅ 正确的：完整记录复现条件和所有阴性结果，推导可能方向。</li></ul>\n<h5>3. NTF 五步法</h5>\n<ol><li><b>完整复现环境</b>：还原客户 BIOS/OS/场景/温度；</li>\n<li><b>压力复测</b>：8h+ 内存压力 + 循环脚本（S3/S4/Reboot）；</li>\n<li><b>交叉验证</b>：同型号多条、多平台互测；</li>\n<li><b>批次/版本对比</b>：不同批次、不同 BIOS 版本；</li>\n<li><b>证据链报告</b>：现象→环境→测试→阴性结果→推断→待验证。</li></ol>\n<h5>4. 四类定性</h5>\n<p><b>真不良</b>（复现到错误）/ <b>假性不良</b>（环境影响）/ <b>人为故障</b>（操作不当）/ <b>环境干扰</b>（ESD/电源）。每种都要有证据支撑，宁缺毋滥。</p>"}], "out": "模拟NTF报告（含证据链）"}]}, {"id": "w8", "badge": "W8", "title": "客户对接与跨部门协同：信息收集 + 技术邮件 + 话术", "sub": "阶段 P2 · 技术能力开始\"对外\"", "accept": "完成1次完整信息收集 + 1封技术邮件 + 1次会议记录。", "tools": "沟通话术手册、FA模板、会议记录模板", "phase": "P2", "weekend": "周末加油站：整理 P2 阶段成果（映射表V1→V2、路径图、NTF证据链、邮件话术包）；预习 W9 客诉流程SOP。 可选：给导师发一封\"P2阶段总结\"邮件练手", "days": [{"id": "d36", "title": "信息收集模板实战", "date": "Day 36 · 周一", "dot": "1", "tasks": ["学习信息收集模板全字段：机型/平台/BIOS/内存型号/现象/概率/环境/操作", "学习\"一次问全\"技巧：给客户模板让他们一次性填好", "模拟角色扮演：客户报障，用模板追问到位", "把模板存入企业微信快捷回复/邮箱签名常用"], "tools": "信息收集模板、沟通话术手册", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV19z4y1f7m5", "label": "▶ Outlook邮件技巧·分类管理（东方瑞通 · 1.5万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1afQoYnEvQ", "label": "▶ 客服邮件处理（邹阳FBM笔记 · 6827播放）"}], "lectures": [{"title": "信息收集模板：一次问全的 10 个字段", "html": "<h5>1. 为什么信息收集是第一步</h5>\n<p>FAE 90% 的坑来自信息不全就下结论。客户说\"内存坏了\"是<b>结果</b>，你要的是<b>过程事实</b>：什么环境、什么操作、什么现象、什么概率。信息收集的质量直接决定排查方向——收集错，后面全错。</p>\n<h5>2. 十字段模板（发给客户的填空版）</h5>\n<ol><li><b>客户/联系方式</b>：对接人 + 电话/企业微信（紧急时直接联系）；</li>\n<li><b>机型/品牌+SN</b>：整机厂牌型号 + 序列号（判批次/渠道）；</li>\n<li><b>主板型号+BIOS 版本</b>：BIOS 日期/版本号（很多问题随 BIOS 更新消失或出现）；</li>\n<li><b>CPU 型号</b>：IMC 代际差异（12 代 vs 13/14 代内存策略不同）；</li>\n<li><b>OS 版本+补丁</b>：Win10/11 大版本 + 累积更新（兼容性客诉常在这里）；</li>\n<li><b>内存型号+SN+批次+颗粒</b>：模组 PN、条码批次、颗粒厂商（同型号不同批次可能不同颗粒）；</li>\n<li><b>插槽位置/是否混插</b>：A1/A2/B1/B2 哪个槽、是否与其他品牌混用；</li>\n<li><b>现象描述+截图/视频</b>：蓝屏要 dump 文件/蓝屏照片，死机要录触发过程；</li>\n<li><b>复现概率+触发条件</b>：必现/偶发、开机/压力/冷机/热机/特定软件；</li>\n<li><b>环境+已做动作</b>：温度/供电/湿度，客户已经试过什么（换槽？单条？清CMOS？）。</li></ol>\n<h5>3. 每个字段的追问示例（拿到\"不够填\"时怎么追问）</h5>\n<ul><li>\"蓝屏\" → 追问：蓝屏代码是多少？什么时候开始？开着什么软件？截图发我；</li>\n<li>\"开不了机\" → 追问：有无报警声/指示灯？显示器有无信号？插几根条？</li>\n<li>\"偶尔死机\" → 追问：大概多久一次？重启后正常吗？是特定操作还是随机？</li>\n<li>\"性能差\" → 追问：和什么基准比？BIOS 里频率实际多少？XMP/EXPO 开了吗？</li></ul>\n<h5>4. 沟通技巧（让客户愿意配合）</h5>\n<ul><li>发<b>填空模板</b>（表格格式）比来回追问高效——客户填起来快，你也拿得全；</li>\n<li>要求<b>截图/视频而非口头描述</b>：\"蓝屏\"要有照片+dump，\"报错\"要有截图（很多问题看一眼截图就定性了）；</li>\n<li>进度<b>主动同步</b>销售/客户，避免\"失联\"猜疑；</li>\n<li>一次问全 vs 挤牙膏：宁可第一次多问几项，别\"想到哪问到哪\"——客户会觉得你没章法。</li></ul>\n<h5>5. 常见\"信息陷阱\"提醒</h5>\n<ul><li>客户说\"换了内存就好\" ≠ 旧条一定坏——可能只是旧条与平台配合问题；</li>\n<li>客户说\"两根都试过\" 要确认：是\"两根都不行\"还是\"每根单独都行、两根一起不行\"（后者是兼容性/供电问题）；</li>\n<li>BIOS 版本必问——刷了 Beta BIOS 后的\"新故障\"可能版本引入；</li>\n<li>拍照要求：金手指正反面、整条标签、插槽位、蓝屏/报错画面，缺一不可。</li></ul>\n<div class=\"tip\">💡 把十字段做成一张 Excel/表格模板存桌面，接单直接发给客户填——这是 FAE 的第一个\"趁手工具\"。</div>"}], "out": "信息收集模板（自用优化版）"}, {"id": "d37", "title": "技术邮件写作", "date": "Day 37 · 周二", "dot": "2", "tasks": ["学习技术邮件结构：主题/背景/已查信息/初步判断/请求事项/时间承诺", "学习写作原则：结论先行、数据说话、口径一致、不夸大", "实操：写 1 封\"向客户要信息\"的邮件，导师批改", "学习回复客户催问的礼貌话术"], "tools": "邮件模板、导师批改", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV19z4y1f7m5", "label": "▶ Outlook邮件技巧·分类管理（东方瑞通 · 1.5万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1afQoYnEvQ", "label": "▶ 客服邮件处理（邹阳FBM笔记 · 6827播放）"}], "lectures": [{"title": "技术邮件写作：结构 + 话术 + 模板", "html": "<h5>1. 技术邮件结构五段</h5>\n<p><b>主题 → 背景 → 已查信息 → 初步判断/请求事项 → 时间承诺</b>。</p>\n<h5>2. 主题公式（一眼看懂）</h5>\n<p><code>【客诉】客户名-机型-内存型号-现象-日期</code>，如【客诉】XX科技-联想T14-DDR5-5600-开机蓝屏-20261114。一眼能检索、能归档案。</p>\n<h5>3. 正文写作原则</h5>\n<ul><li><b>结论先行</b>：第一句说清\"我为什么写这封邮件\"；</li>\n<li><b>数据说话</b>：有测试结果放日志/截图，不写\"应该没问题\"；</li>\n<li><b>口径一致</b>：与公司规范/研发结论一致，不承诺未验证事项；</li>\n<li><b>有界承诺</b>：给时间节点（\"预计X天给初步结论\"），别说过头话。</li></ul>\n<h5>4. 模板（客户要信息版）</h5>\n<pre>\nXX 经理您好，\n关于贵司反馈的 [现象]（[客户单号]），我们已初步排查 [已做动作]，\n需要您协助补充以下信息以便定位：\n1. 主板型号 + BIOS 版本\n2. 内存完整型号 + 序列号\n3. 现象截图/视频 + 复现频率\n4. 是否混插/是否开 XMP\n预计收到信息后 X 个工作日内给初步结论。\n</pre>\n<h5>5. 回复客户催问话术</h5>\n<p>\"我们正在按计划排查，目前进展是……，预计 X 天给您结论。如有新信息我会第一时间同步。\"——主动同步比失联强十倍。</p>\n<div class=\"tip\">💡 写完邮件自己先读一遍：如果我是客户，看得懂吗？有安全感吗？</div>"}], "out": "1 封批改后的技术邮件"}, {"id": "d38", "title": "临时对策写作", "date": "Day 38 · 周三", "dot": "3", "tasks": ["学习临时对策要素：具体动作/适用范围/有效期/验证方法/风险说明", "学习\"临时 vs 永久对策\"边界（权宜可用 ≠ 根因解决）", "实操：为 1 个案例写临时对策（如先降频/换槽位/关XMP）", "学习对策的\"内外口径一致\"：研发/销售/客户说辞统一"], "tools": "对策模板、案例库", "resources": [], "lectures": [{"title": "临时对策写作：先救急，再根治", "html": "<h5>1. 临时对策 vs 永久对策</h5>\n<p><b>临时对策</b>＝马上能让客户恢复生产的权宜动作；<b>永久对策</b>＝根因修复（换料/改工艺/升级固件）。FAE 的职责是<b>同时给两个</b>，并且说清区别和边界。</p>\n<h5>2. 临时对策五要素</h5>\n<ol><li><b>具体动作</b>：如\"换到 A2 槽\"、\"关 XMP 用 JEDEC 档\"、\"单条运行\"；</li>\n<li><b>适用范围</b>：适用什么平台/什么现象，不适用什么；</li>\n<li><b>有效期/条件</b>：临时方案能撑多久，什么情况下失效；</li>\n<li><b>验证方法</b>：执行后怎么确认有效（跑多久测什么）；</li>\n<li><b>风险说明</b>：降频会损失多少性能？临时方案有什么副作用？</li></ol>\n<h5>3. 写法模板</h5>\n<pre>\n【临时对策】（截至 12/31 有效）\n1. 将内存安装在 A2+B2 槽（远离 CPU 插槽的通道）\n2. 关闭 XMP，使用 JEDEC 默认频率 4800\n3. 重启后运行 MemTest86 1 Pass 验证\n风险：频率降为 4800，性能约降 5%~8%\n后续：我司已送样改良固件，预计 X 天验证完成后给永久方案\n</pre>\n<h5>4. 沟通要点</h5>\n<p>临时对策要<b>让客户自己能执行</b>（别用术语砸人），并明确\"这是临时方案，我们会继续给永久修复\"——管理好预期，客户才不焦虑。</p>"}], "out": "临时对策文档 1 份"}, {"id": "d39", "title": "跟会 + 会议记录", "date": "Day 39 · 周四", "dot": "4", "tasks": ["参加一次真实会议（客诉会/项目会/周会）", "用模板写会议记录：议题/结论/待办/负责人/期限", "学习\"随会学习\"：记录不认识的术语会后查证", "学习异议应对：客户质疑时不要硬刚，用数据回应"], "tools": "会议记录模板、会前议程", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1hi4y1d7rk", "label": "▶ 如何写好会议纪要·老笔杆子（会写材料的明叔 · 33.1万播放）"}], "lectures": [{"title": "跟会与会议记录：FAE 的软技能", "html": "<h5>1. 会议记录四要素</h5>\n<p><b>议题 → 结论 → 待办 → 责任人/期限</b>。没有待办和责任的会议记录等于没记。</p>\n<h5>2. 随会学习</h5>\n<ul><li>听不懂的术语现场记下来，会后查；</li>\n<li>关注客诉会中\"销售/研发/生产\"各自的立场；</li>\n<li>学导师怎么拆需求、怎么应对异议。</li></ul>\n<h5>3. 输出格式</h5>\n<p>邮件同步：会议背景 1 行 + 结论 3 条 + 待办表（事项/负责人/期限/状态）。口径与公司一致。</p>"}], "out": "会议记录 1 份"}, {"id": "d40", "title": "P2 阶段总结 + 周复盘", "date": "Day 40 · 周五", "dot": "5", "tasks": ["完成信息收集+邮件+会议记录三项验收打包", "完成 P2 阶段小测（故障+流程+NTF+沟通）", "完成《12周计划》W8 验收点打勾", "P2 阶段总结：能力模型 B/C 域勾选盘点"], "tools": "验收清单、阶段测试卷", "resources": [], "lectures": [{"title": "P2 阶段总结：诊断能力复盘", "html": "<h5>1. P2（W5-W8）能力盘点</h5>\n<ul><li>十大故障场景每个都能列 ≥4 条根因并排序（映射表 V1→V2）；</li>\n<li>排查路径图能画、不跳步；</li>\n<li>NTF 方法论五板斧能讲能用（复现/交叉/复测/批次/版本）；</li>\n<li>信息收集模板、技术邮件、临时对策、会议记录都有产出。</li></ul>\n<h5>2. 阶段总结模板</h5>\n<ol><li>我学会的最重要 3 个技能（举例说怎么用的）；</li>\n<li>我踩过的坑（比如\"信息不全就下结论\"）；</li>\n<li>能力模型 B/C 域自评（故障分析+客户对接）打勾；</li>\n<li>P3 之前还缺什么（如\"没独立处理过真实客诉\"）。</li></ol>\n<h5>3. 复盘动作</h5>\n<p>把映射表、路径图、NTF 报告、邮件模板归档进知识库；把\"容易忘的判断口诀\"做成卡片；给导师发 500 字阶段小结（锻炼书面汇报能力）。</p>"}], "out": "P2 阶段总结 + 三项验收存档"}]}, {"id": "w9", "badge": "W9", "title": "独立客诉参与：客诉单闭环", "sub": "阶段 P3 · 第一次真正上战场", "accept": "独立参与1-2单常规客诉：信息收集→排查→临时对策→进度同步销售；客诉单闭环、销售与客户均确认对策有效。", "tools": "客户支持流程SOP、企业微信/邮件", "phase": "P3", "weekend": "周末加油站：预习 FA 报告模板结构；把客诉复盘结论同步给导师；准备 W10 的案例素材。 可选：找 1 份优秀 FA 报告通读学习写法", "days": [{"id": "d41", "title": "客诉流程 SOP 精读 + 认领案例", "date": "Day 41 · 周一", "dot": "1", "tasks": ["精读《客户支持流程SOP》：接单→登记→处理→复盘全流程", "学习客诉单字段：客户/机型/内存型号/数量/现象/期望", "认领/旁听 1 个真实客诉案例", "建立客诉跟进表（进度/下一步/责任人）"], "tools": "客户支持流程SOP、客诉单模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1PYkrBcE9H", "label": "▶ 如何高情商处理客户投诉（海纳集团视频号 · 7031播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19b4y1d7rg", "label": "▶ 处理顾客投诉五步曲（梁老师889 · 2032播放）"}], "lectures": [{"title": "客诉处理：从接单到闭环", "html": "<h5>1. 八步闭环（每一步都要有产出物）</h5>\n<p><b>信息收集→初判分级→复现测试→根因分析→临时对策→根因对策→验证→归档</b>。不要跳步：客户催得急也要把证据链走完，否则后患无穷。</p>\n<table><tr><th>步骤</th><th>关键动作</th><th>产出物</th></tr>\n<tr><td>①信息收集</td><td>按模板问全：机型/平台/BIOS/内存型号/现象/概率/环境/操作</td><td>信息收集表（一次问全）</td></tr>\n<tr><td>②初判分级</td><td>判断停线/重大/常规，定响应时效</td><td>问题分级 + 响应节点</td></tr>\n<tr><td>③复现测试</td><td>客户环境复现 + 本司平台复现（MemTest86/BurnInTest）</td><td>复现记录（截图/日志/视频）</td></tr>\n<tr><td>④根因分析</td><td>最小化/交叉替换/批次比对/电气测量，锁定层级</td><td>根因假设 + 证据</td></tr>\n<tr><td>⑤临时对策</td><td>先给客户能用的：换槽/降频/单条/关XMP</td><td>临时对策单</td></tr>\n<tr><td>⑥根因对策</td><td>联动研发/质量：换货/固件/工艺/来料管控</td><td>永久对策 + 责任方</td></tr>\n<tr><td>⑦验证</td><td>对策有效性验证（复测通过 + 客户确认）</td><td>验证报告</td></tr>\n<tr><td>⑧归档</td><td>编号入案例库，写清现象→根因→对策→可复用的排查思路</td><td>案例库条目</td></tr></table>\n<h5>2. 分级与响应时效（先响应，再解决）</h5>\n<ul><li><b>产线停线</b>：最高级，1 小时内响应，电话 + 群同步，24h 内给临时对策；</li>\n<li><b>客户升级/大客户</b>：当日响应，48h 内给初步结论；</li>\n<li><b>常规单</b>：1 个工作日内响应。</li></ul>\n<p>第一时间回复<b>\"已收到，正在排查，预计 X 时间给结论\"</b>——不是等有结论才回。客户的焦虑来自沉默，回复=\\\"确定性缓冲\\\"。</p>\n<h5>3. 客诉单要填的字段（对照你的模板逐一确认）</h5>\n<p>客户/机型/平台/BIOS版本/内存型号与SN/数量/故障现象（原话）/出现概率（必现/偶发/频率）/触发条件（开机/压力/冷机/热机）/环境（温度/电压/机箱风道）/客户期望（退货/换货/分析报告/赔偿）/紧急度。缺字段=后面必返工。</p>\n<h5>4. 临时对策 vs 永久对策（边界要分清）</h5>\n<p>临时对策是<b>给客户先能用</b>：换槽/降频/单条/关 XMP/清 CMOS；永久对策是<b>消除根因</b>：换货/固件/工艺/来料管控。\"权宜可用 ≠ 根因解决\"——临时对策单上要写清适用范围与有效期，避免客户把临时当永久。</p>\n<h5>5. 内部协同与对外口径</h5>\n<p>FAE 是窗口：销售/研发/客户三方信息都从你这里对齐。<b>对外口径统一</b>，别在客户群里互相矛盾——不确定的事先内部确认再回复；同时把客户的原始诉求完整带回内部（含情绪、期望、决策人）。</p>\n<h5>6. 客户预期管理话术（背熟直接可用）</h5>\n<ul><li>催结果：\"根因还在交叉验证，我先把已确认的部分同步给您，预计 X 确认完整结论\"；</li>\n<li>想退货：\"换货流程已启动，同时我建议先试临时对策避免影响生产，两条线并行\"；</li>\n<li>质疑结论：\"我用了 A/B 交叉和压力测试，数据如下...如果还有疑虑我们可以一起复现\"。</li></ul>\n<div class=\"tip\">💡 考核/面试点：能说出\"八步闭环\"还不够，要能随手举出每一\"步的产出物——纸上写不出来的流程不叫会。</div>"}], "out": "客诉单登记记录 + 跟进表"}, {"id": "d42", "title": "客诉排查执行（第一天）", "date": "Day 42 · 周二", "dot": "2", "tasks": ["按信息收集模板向客户补齐全部字段（缺什么问什么）", "初步诊断：安装/接触/外观检查步骤走一遍", "最小化验证：单条/换槽/交叉替换开始执行", "每日进展同步（销售+客户群）"], "tools": "排查SOP、信息收集表、企业微信", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1PYkrBcE9H", "label": "▶ 如何高情商处理客户投诉（海纳集团视频号 · 7031播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19b4y1d7rg", "label": "▶ 处理顾客投诉五步曲（梁老师889 · 2032播放）"}], "lectures": [{"title": "客诉处理：从接单到闭环", "html": "<h5>1. 八步闭环（每一步都要有产出物）</h5>\n<p><b>信息收集→初判分级→复现测试→根因分析→临时对策→根因对策→验证→归档</b>。不要跳步：客户催得急也要把证据链走完，否则后患无穷。</p>\n<table><tr><th>步骤</th><th>关键动作</th><th>产出物</th></tr>\n<tr><td>①信息收集</td><td>按模板问全：机型/平台/BIOS/内存型号/现象/概率/环境/操作</td><td>信息收集表（一次问全）</td></tr>\n<tr><td>②初判分级</td><td>判断停线/重大/常规，定响应时效</td><td>问题分级 + 响应节点</td></tr>\n<tr><td>③复现测试</td><td>客户环境复现 + 本司平台复现（MemTest86/BurnInTest）</td><td>复现记录（截图/日志/视频）</td></tr>\n<tr><td>④根因分析</td><td>最小化/交叉替换/批次比对/电气测量，锁定层级</td><td>根因假设 + 证据</td></tr>\n<tr><td>⑤临时对策</td><td>先给客户能用的：换槽/降频/单条/关XMP</td><td>临时对策单</td></tr>\n<tr><td>⑥根因对策</td><td>联动研发/质量：换货/固件/工艺/来料管控</td><td>永久对策 + 责任方</td></tr>\n<tr><td>⑦验证</td><td>对策有效性验证（复测通过 + 客户确认）</td><td>验证报告</td></tr>\n<tr><td>⑧归档</td><td>编号入案例库，写清现象→根因→对策→可复用的排查思路</td><td>案例库条目</td></tr></table>\n<h5>2. 分级与响应时效（先响应，再解决）</h5>\n<ul><li><b>产线停线</b>：最高级，1 小时内响应，电话 + 群同步，24h 内给临时对策；</li>\n<li><b>客户升级/大客户</b>：当日响应，48h 内给初步结论；</li>\n<li><b>常规单</b>：1 个工作日内响应。</li></ul>\n<p>第一时间回复<b>\"已收到，正在排查，预计 X 时间给结论\"</b>——不是等有结论才回。客户的焦虑来自沉默，回复=\\\"确定性缓冲\\\"。</p>\n<h5>3. 客诉单要填的字段（对照你的模板逐一确认）</h5>\n<p>客户/机型/平台/BIOS版本/内存型号与SN/数量/故障现象（原话）/出现概率（必现/偶发/频率）/触发条件（开机/压力/冷机/热机）/环境（温度/电压/机箱风道）/客户期望（退货/换货/分析报告/赔偿）/紧急度。缺字段=后面必返工。</p>\n<h5>4. 临时对策 vs 永久对策（边界要分清）</h5>\n<p>临时对策是<b>给客户先能用</b>：换槽/降频/单条/关 XMP/清 CMOS；永久对策是<b>消除根因</b>：换货/固件/工艺/来料管控。\"权宜可用 ≠ 根因解决\"——临时对策单上要写清适用范围与有效期，避免客户把临时当永久。</p>\n<h5>5. 内部协同与对外口径</h5>\n<p>FAE 是窗口：销售/研发/客户三方信息都从你这里对齐。<b>对外口径统一</b>，别在客户群里互相矛盾——不确定的事先内部确认再回复；同时把客户的原始诉求完整带回内部（含情绪、期望、决策人）。</p>\n<h5>6. 客户预期管理话术（背熟直接可用）</h5>\n<ul><li>催结果：\"根因还在交叉验证，我先把已确认的部分同步给您，预计 X 确认完整结论\"；</li>\n<li>想退货：\"换货流程已启动，同时我建议先试临时对策避免影响生产，两条线并行\"；</li>\n<li>质疑结论：\"我用了 A/B 交叉和压力测试，数据如下...如果还有疑虑我们可以一起复现\"。</li></ul>\n<div class=\"tip\">💡 考核/面试点：能说出\"八步闭环\"还不够，要能随手举出每一\"步的产出物——纸上写不出来的流程不叫会。</div>"}, {"title": "客诉执行工具箱：怎么用好排查工具", "html": "<h5>1. 常规客诉两天排查节奏</h5>\n<table><tr><th>时间</th><th>动作</th><th>工具</th></tr>\n<tr><td>Day1 上午</td><td>信息收集 + 外观/接触检查</td><td>信息收集模板、手电放大镜</td></tr>\n<tr><td>Day1 下午</td><td>最小化 + 交叉替换</td><td>单条换槽、已知正常件</td></tr>\n<tr><td>Day2 上午</td><td>开机级扫描</td><td>MemTest86（1-2 Pass）</td></tr>\n<tr><td>Day2 下午</td><td>系统压力 + 定论</td><td>BurnInTest 8h / 短跑</td></tr></table>\n<h5>2. 交叉替换在本单怎么用</h5>\n<p>客户报\"这条内存有问题\"时：<b>先把条子插到另一台正常电脑试，再把正常条子插到客户电脑试</b>——四个组合一跑，故障跟条子走还是跟主板走立刻清楚。</p>\n<h5>3. MemTest86 / BurnInTest 什么时候必要</h5>\n<ul><li><b>MT86</b>：怀疑颗粒/线路坏点时必跑（开机级、最权威）；</li>\n<li><b>BurnInTest</b>：怀疑\"系统下长时间才出错\"时跑 8h+；</li>\n<li>两者都要留日志，这是给客户/研发的证据。</li></ul>\n<h5>4. 拿日志说话</h5>\n<p>给客户回话别用\"应该没问题\"，用\"我们测得 MT86 2Pass 0 Error、BurnInTest 8h 无异常，说明……\"。数据一出，争议少一半。</p>"}], "out": "排查日志第1天"}, {"id": "d43", "title": "客诉排查执行（第二天）", "date": "Day 43 · 周三", "dot": "3", "tasks": ["深入测试：MT86/BurnInTest 跑数据，拿日志说话", "复现情况记录：现象/概率/环境/软件版本", "与导师/测试/研发初步对齐判断方向", "用数据回复客户（避免\"凭感觉\"式回复）"], "tools": "MT86、BurnInTest、测试记录模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1PYkrBcE9H", "label": "▶ 如何高情商处理客户投诉（海纳集团视频号 · 7031播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19b4y1d7rg", "label": "▶ 处理顾客投诉五步曲（梁老师889 · 2032播放）"}], "lectures": [{"title": "客诉处理：从接单到闭环", "html": "<h5>1. 八步闭环（每一步都要有产出物）</h5>\n<p><b>信息收集→初判分级→复现测试→根因分析→临时对策→根因对策→验证→归档</b>。不要跳步：客户催得急也要把证据链走完，否则后患无穷。</p>\n<table><tr><th>步骤</th><th>关键动作</th><th>产出物</th></tr>\n<tr><td>①信息收集</td><td>按模板问全：机型/平台/BIOS/内存型号/现象/概率/环境/操作</td><td>信息收集表（一次问全）</td></tr>\n<tr><td>②初判分级</td><td>判断停线/重大/常规，定响应时效</td><td>问题分级 + 响应节点</td></tr>\n<tr><td>③复现测试</td><td>客户环境复现 + 本司平台复现（MemTest86/BurnInTest）</td><td>复现记录（截图/日志/视频）</td></tr>\n<tr><td>④根因分析</td><td>最小化/交叉替换/批次比对/电气测量，锁定层级</td><td>根因假设 + 证据</td></tr>\n<tr><td>⑤临时对策</td><td>先给客户能用的：换槽/降频/单条/关XMP</td><td>临时对策单</td></tr>\n<tr><td>⑥根因对策</td><td>联动研发/质量：换货/固件/工艺/来料管控</td><td>永久对策 + 责任方</td></tr>\n<tr><td>⑦验证</td><td>对策有效性验证（复测通过 + 客户确认）</td><td>验证报告</td></tr>\n<tr><td>⑧归档</td><td>编号入案例库，写清现象→根因→对策→可复用的排查思路</td><td>案例库条目</td></tr></table>\n<h5>2. 分级与响应时效（先响应，再解决）</h5>\n<ul><li><b>产线停线</b>：最高级，1 小时内响应，电话 + 群同步，24h 内给临时对策；</li>\n<li><b>客户升级/大客户</b>：当日响应，48h 内给初步结论；</li>\n<li><b>常规单</b>：1 个工作日内响应。</li></ul>\n<p>第一时间回复<b>\"已收到，正在排查，预计 X 时间给结论\"</b>——不是等有结论才回。客户的焦虑来自沉默，回复=\\\"确定性缓冲\\\"。</p>\n<h5>3. 客诉单要填的字段（对照你的模板逐一确认）</h5>\n<p>客户/机型/平台/BIOS版本/内存型号与SN/数量/故障现象（原话）/出现概率（必现/偶发/频率）/触发条件（开机/压力/冷机/热机）/环境（温度/电压/机箱风道）/客户期望（退货/换货/分析报告/赔偿）/紧急度。缺字段=后面必返工。</p>\n<h5>4. 临时对策 vs 永久对策（边界要分清）</h5>\n<p>临时对策是<b>给客户先能用</b>：换槽/降频/单条/关 XMP/清 CMOS；永久对策是<b>消除根因</b>：换货/固件/工艺/来料管控。\"权宜可用 ≠ 根因解决\"——临时对策单上要写清适用范围与有效期，避免客户把临时当永久。</p>\n<h5>5. 内部协同与对外口径</h5>\n<p>FAE 是窗口：销售/研发/客户三方信息都从你这里对齐。<b>对外口径统一</b>，别在客户群里互相矛盾——不确定的事先内部确认再回复；同时把客户的原始诉求完整带回内部（含情绪、期望、决策人）。</p>\n<h5>6. 客户预期管理话术（背熟直接可用）</h5>\n<ul><li>催结果：\"根因还在交叉验证，我先把已确认的部分同步给您，预计 X 确认完整结论\"；</li>\n<li>想退货：\"换货流程已启动，同时我建议先试临时对策避免影响生产，两条线并行\"；</li>\n<li>质疑结论：\"我用了 A/B 交叉和压力测试，数据如下...如果还有疑虑我们可以一起复现\"。</li></ul>\n<div class=\"tip\">💡 考核/面试点：能说出\"八步闭环\"还不够，要能随手举出每一\"步的产出物——纸上写不出来的流程不叫会。</div>"}, {"title": "客诉执行工具箱：怎么用好排查工具", "html": "<h5>1. 常规客诉两天排查节奏</h5>\n<table><tr><th>时间</th><th>动作</th><th>工具</th></tr>\n<tr><td>Day1 上午</td><td>信息收集 + 外观/接触检查</td><td>信息收集模板、手电放大镜</td></tr>\n<tr><td>Day1 下午</td><td>最小化 + 交叉替换</td><td>单条换槽、已知正常件</td></tr>\n<tr><td>Day2 上午</td><td>开机级扫描</td><td>MemTest86（1-2 Pass）</td></tr>\n<tr><td>Day2 下午</td><td>系统压力 + 定论</td><td>BurnInTest 8h / 短跑</td></tr></table>\n<h5>2. 交叉替换在本单怎么用</h5>\n<p>客户报\"这条内存有问题\"时：<b>先把条子插到另一台正常电脑试，再把正常条子插到客户电脑试</b>——四个组合一跑，故障跟条子走还是跟主板走立刻清楚。</p>\n<h5>3. MemTest86 / BurnInTest 什么时候必要</h5>\n<ul><li><b>MT86</b>：怀疑颗粒/线路坏点时必跑（开机级、最权威）；</li>\n<li><b>BurnInTest</b>：怀疑\"系统下长时间才出错\"时跑 8h+；</li>\n<li>两者都要留日志，这是给客户/研发的证据。</li></ul>\n<h5>4. 拿日志说话</h5>\n<p>给客户回话别用\"应该没问题\"，用\"我们测得 MT86 2Pass 0 Error、BurnInTest 8h 无异常，说明……\"。数据一出，争议少一半。</p>"}], "out": "测试数据包 + 中间结论"}, {"id": "d44", "title": "临时对策 + 闭环推进", "date": "Day 44 · 周四", "dot": "4", "tasks": ["输出临时对策（可立即执行的权宜方案）", "与销售确认商务口径，与客户确认对策可接受", "对策验证：按临时对策执行后复测", "推进客诉单闭环：销售与客端双向确认"], "tools": "对策模板、销售协同、企微", "resources": [], "lectures": [{"title": "客诉推进：从\"判断\"到\"客户满意\"", "html": "<h5>1. 客诉第 4-5 天的关键动作</h5>\n<p>到这一步，你已经完成了信息收集、复现、初步定位。<b>现在最重要的事不是再测，而是把结论\"翻译\"成客户能接受的方案</b>：临时对策 + 明确的时间承诺 + 定期同步。</p>\n<h5>2. 临时对策落地三步</h5>\n<ol><li>写清动作与验证方法（让客户能执行）；</li>\n<li>和销售确认商务口径（换货/赔偿边界不自己承诺）；</li>\n<li>客户执行后复测 → 确认对策有效 → 记录。</li></ol>\n<h5>3. 闭环推进（销售+客户双向确认）</h5>\n<ul><li>给销售：技术结论 + 商务建议；</li>\n<li>给客户：临时对策 + 后续永久修复时间表；</li>\n<li>归档：把该案例写入案例库（现象/根因/对策/验证）。</li></ul>\n<div class=\"tip\">💡 客户满意度 = 解决速度 × 沟通透明度。一天同步一次进展，比三天后给完美答案更让人安心。</div>"}], "out": "临时对策文档 + 闭环确认记录"}, {"id": "d45", "title": "客诉复盘 + 周复盘", "date": "Day 45 · 周五", "dot": "5", "tasks": ["客诉全流程复盘：做得好/卡在哪/下次改进", "把该案例填入个人案例库（现象/根因/对策/验证）", "完成《12周计划》W9 验收点打勾", "如果可能，认领第2单客诉（进阶挑战）"], "tools": "案例库模板、复盘模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1PYkrBcE9H", "label": "▶ 如何高情商处理客户投诉（海纳集团视频号 · 7031播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19b4y1d7rg", "label": "▶ 处理顾客投诉五步曲（梁老师889 · 2032播放）"}], "lectures": [{"title": "客诉处理：从接单到闭环", "html": "<h5>1. 八步闭环（每一步都要有产出物）</h5>\n<p><b>信息收集→初判分级→复现测试→根因分析→临时对策→根因对策→验证→归档</b>。不要跳步：客户催得急也要把证据链走完，否则后患无穷。</p>\n<table><tr><th>步骤</th><th>关键动作</th><th>产出物</th></tr>\n<tr><td>①信息收集</td><td>按模板问全：机型/平台/BIOS/内存型号/现象/概率/环境/操作</td><td>信息收集表（一次问全）</td></tr>\n<tr><td>②初判分级</td><td>判断停线/重大/常规，定响应时效</td><td>问题分级 + 响应节点</td></tr>\n<tr><td>③复现测试</td><td>客户环境复现 + 本司平台复现（MemTest86/BurnInTest）</td><td>复现记录（截图/日志/视频）</td></tr>\n<tr><td>④根因分析</td><td>最小化/交叉替换/批次比对/电气测量，锁定层级</td><td>根因假设 + 证据</td></tr>\n<tr><td>⑤临时对策</td><td>先给客户能用的：换槽/降频/单条/关XMP</td><td>临时对策单</td></tr>\n<tr><td>⑥根因对策</td><td>联动研发/质量：换货/固件/工艺/来料管控</td><td>永久对策 + 责任方</td></tr>\n<tr><td>⑦验证</td><td>对策有效性验证（复测通过 + 客户确认）</td><td>验证报告</td></tr>\n<tr><td>⑧归档</td><td>编号入案例库，写清现象→根因→对策→可复用的排查思路</td><td>案例库条目</td></tr></table>\n<h5>2. 分级与响应时效（先响应，再解决）</h5>\n<ul><li><b>产线停线</b>：最高级，1 小时内响应，电话 + 群同步，24h 内给临时对策；</li>\n<li><b>客户升级/大客户</b>：当日响应，48h 内给初步结论；</li>\n<li><b>常规单</b>：1 个工作日内响应。</li></ul>\n<p>第一时间回复<b>\"已收到，正在排查，预计 X 时间给结论\"</b>——不是等有结论才回。客户的焦虑来自沉默，回复=\\\"确定性缓冲\\\"。</p>\n<h5>3. 客诉单要填的字段（对照你的模板逐一确认）</h5>\n<p>客户/机型/平台/BIOS版本/内存型号与SN/数量/故障现象（原话）/出现概率（必现/偶发/频率）/触发条件（开机/压力/冷机/热机）/环境（温度/电压/机箱风道）/客户期望（退货/换货/分析报告/赔偿）/紧急度。缺字段=后面必返工。</p>\n<h5>4. 临时对策 vs 永久对策（边界要分清）</h5>\n<p>临时对策是<b>给客户先能用</b>：换槽/降频/单条/关 XMP/清 CMOS；永久对策是<b>消除根因</b>：换货/固件/工艺/来料管控。\"权宜可用 ≠ 根因解决\"——临时对策单上要写清适用范围与有效期，避免客户把临时当永久。</p>\n<h5>5. 内部协同与对外口径</h5>\n<p>FAE 是窗口：销售/研发/客户三方信息都从你这里对齐。<b>对外口径统一</b>，别在客户群里互相矛盾——不确定的事先内部确认再回复；同时把客户的原始诉求完整带回内部（含情绪、期望、决策人）。</p>\n<h5>6. 客户预期管理话术（背熟直接可用）</h5>\n<ul><li>催结果：\"根因还在交叉验证，我先把已确认的部分同步给您，预计 X 确认完整结论\"；</li>\n<li>想退货：\"换货流程已启动，同时我建议先试临时对策避免影响生产，两条线并行\"；</li>\n<li>质疑结论：\"我用了 A/B 交叉和压力测试，数据如下...如果还有疑虑我们可以一起复现\"。</li></ul>\n<div class=\"tip\">💡 考核/面试点：能说出\"八步闭环\"还不够，要能随手举出每一\"步的产出物——纸上写不出来的流程不叫会。</div>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。</p>\n<h5>2. 每例 <200 字的推荐格式</h5>\n<pre>案例编号：FAE-2026-XXX\n现象：一句话\n平台：主板/CPU/OS/内存型号\n根因：一句话\n证据：日志/截图路径\n对策：临时+永久\n状态：已闭环/复核中</pre>\n<h5>3. 什么案例值得记</h5>\n<ul><li>第一次遇到的故障类型；</li>\n<li>排查过程走弯路的（教训最值钱）；</li>\n<li>证据链完整、能当培训材料的；</li>\n<li>客户高频问题（同问必记）。</li></ul>\n<h5>4. 归档节奏</h5>\n<p>客诉闭环当天顺手记一例（30 秒的事），月底统一补标签和索引。目标：<b>12 周 ≥10 例，一年 ≥30 例</b>。</p>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。</div>"}], "out": "客诉闭环案例 1 例入库 + 周复盘"}]}, {"id": "w10", "badge": "W10", "title": "FA失效分析报告：现象→数据→根因→对策→验证→预防", "sub": "阶段 P3 · 把一次客诉变成一份资产", "accept": "按模板输出FA报告，报告通过领导评审，根因可追溯、验证数据完整。", "tools": "FA报告模板", "phase": "P3", "weekend": "周末加油站：把 FA 报告给研发/测试同事看，收集跨部门视角；预习 W11 新项目导入。 可选：学习 8D 报告的基本结构（FA 的进阶形态）", "days": [{"id": "d46", "title": "FA 报告模板拆解", "date": "Day 46 · 周一", "dot": "1", "tasks": ["学习 FA 报告六段式：现象→数据→根因→对策→验证→预防", "通读 1 份优秀 FA 报告，拆解每段写法", "学习\"FA写法与边界\"：能下结论的才有依据，不能下结论的明确待验证", "选定自己将要写的案例（优先用 W9 客诉案例）"], "tools": "FA报告模板、优秀范例", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV18t421L7oa", "label": "▶ 笔记本加内存条·拆装方法（想想3c数码 · 18.7万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1zp411f7h2", "label": "▶ 内存条的拆装（KOTIN京天售后 · 4.3万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1G2dhBmESw", "label": "▶ 学会看内存条出厂日期（政雨Rich · 2.8万播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/DIMM", "label": "📄 维基百科·DIMM"}], "lectures": [{"title": "FA 报告六段式详解：每段怎么写", "html": "<h5>1. 六段式骨架（FA 报告唯一结构）</h5>\n<p><b>现象 → 数据 → 根因 → 对策 → 验证 → 预防</b>，六段缺一不可。</p>\n<h5>2. 每段写法要点</h5>\n<ol><li><b>现象</b>：客户原话 + 截图/视频 + 环境信息（机型/平台/BIOS/OS/概率）；</li>\n<li><b>数据</b>：测试日志、MT86 地址、温压曲线、电气测量——全部可追溯；</li>\n<li><b>根因</b>：用\"排除+确认\"逻辑写，每个结论指向一份证据；</li>\n<li><b>对策</b>：临时（客户可执行）与永久（公司侧）分开写；</li>\n<li><b>验证</b>：对策后复测数据，写明方法/时长/结果；</li>\n<li><b>预防</b>：设计/制程/文档/FAQ/批次处理建议。</li></ol>\n<h5>3. FA 写法边界（最重要）</h5>\n<ul><li>能下结论的写结论，不能下结论的写\"待验证项\"；</li>\n<li>不用\"可能是/应该吧\"，用\"数据表明/排除后指向\"；</li>\n<li>根因必须可追溯：每个结论都能指向一条证据；</li>\n<li>不夸大、不承诺未验证事项。</li></ul>\n<h5>4. 评审关注点</h5>\n<p>领导看三件事：证据全不全、逻辑通不通、口径专不专业。写完后按《避坑清单》自查再提交。</p>\n<div class=\"tip\">💡 第一份报告不求完美，求\"六段齐全+数据真实\"。批改意见逐条记录进避坑清单，第二份就有手感了。</div>"}], "out": "FA 报告结构拆解笔记"}, {"id": "d47", "title": "案例数据整理", "date": "Day 47 · 周二", "dot": "2", "tasks": ["收集案例全部数据：现象描述/测试日志/截图/环境信息", "整理时间线：什么时间做了什么测试、得到什么结果", "把数据分类归档（现象/试验/电气/温压/软件）", "第37步检查：证据链是否有断点"], "tools": "案例数据包、归档结构", "resources": [], "lectures": [{"title": "案例数据整理：把杂乱证据变成 FA 报告素材", "html": "<h5>1. 为什么要整理数据</h5>\n<p>FA 报告的可信度 = 数据的完整性和可追溯性。现场测试散落的截图/日志如果不整理成时间线，写报告时会抓瞎、也容易遗漏关键证据。</p>\n<h5>2. 数据分类归档法</h5>\n<ul><li><b>现象类</b>：客户原话、截图、视频、复现描述；</li>\n<li><b>试验类</b>：MT86 日志、BurnInTest 结果、AIDA64 数据；</li>\n<li><b>监控类</b>：温压曲线（HWiNFO64 CSV）、事件日志；</li>\n<li><b>产品类</b>：内存型号/SN/批次、BIOS 版本、平台信息。</li></ul>\n<h5>3. 时间线整理</h5>\n<p>按\"时间→动作→结果\"列出：<br>13:00 客户报障（蓝屏 0x1A，附截图）→ 13:30 信息收集完成 → 14:00 MT86 启动 → 15:30 MT86 发现 3 个错误（地址 0x…）→ ……</p>\n<h5>4. 证据链检查</h5>\n<p>写报告前自问：<b>我的每个结论，能指向哪份数据？有没有断点？</b>\"感觉是颗粒问题\"不算，必须有地址段+复测记录。</p>"}], "out": "数据包（按FA报告结构组织）"}, {"id": "d48", "title": "撰写 FA 报告初稿", "date": "Day 48 · 周三", "dot": "3", "tasks": ["按模板填写六段式初稿", "\"现象\"写清客户原话 + 截图；\"数据\"附日志证据", "\"根因\"用\"排除+确认\"逻辑书写；\"对策\"区分临时/永久", "\"验证\"写明验证方法/时长/结果；\"预防\"落到文件或流程"], "tools": "FA报告模板、数据包", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV18Q4y1j76R", "label": "▶ 8D报告怎么写（讨教君质量与管理分享 · 2.8万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1BzoNBnEKD", "label": "▶ 8D报告入门·D0到D8全流程（数智营企 · 572播放）"}], "lectures": [{"title": "FA 报告：现象→数据→根因→对策→验证→预防", "html": "<h5>1. 六段式骨架</h5>\n<ol><li><b>现象</b>：客户原话+截图，谁、什么环境、多久一次；</li>\n<li><b>数据</b>：测试日志/截图/温压曲线/电气测量，全部可追溯；</li>\n<li><b>根因</b>：排除+确认逻辑写出结论，附证据；</li>\n<li><b>对策</b>：临时（客户侧）与永久（公司侧）分开；</li>\n<li><b>验证</b>：对策后复测数据，写明方法/时长/结果；</li>\n<li><b>预防</b>：设计/制程/文档/FAQ/批次处理建议。</li></ol>\n<h5>2. 写作边界（FAE 第一课）</h5>\n<ul><li>能下结论的写结论，不能下结论的写\"待验证项\"；</li>\n<li>不用\"可能是/应该吧\"，用\"数据表明/排除后指向\"；</li>\n<li>根因必须可追溯：每个结论都能指向一条证据。</li></ul>\n<h5>3. 评审关注点</h5>\n<p>领导看三件事：证据全不全、逻辑通不通、口径专不专业。用《避坑清单》反复自查。</p>"}], "out": "FA 报告初稿"}, {"id": "d49", "title": "报告评审 + 修改", "date": "Day 49 · 周四", "dot": "4", "tasks": ["请导师/领导评审初稿，逐条记录意见", "学习评审关注点：根因可追溯性、验证数据完整性、结论不过度", "修改报告：补数据/改措辞/弱化无依据结论", "形成《FA报告避坑清单》（首版）"], "tools": "评审意见、修改记录", "resources": [], "lectures": [{"title": "报告评审：领导在看什么", "html": "<h5>1. 评审常见问题（避坑清单）</h5>\n<ul><li><b>证据不足</b>：结论没有数据支撑 → 补日志/截图/测量值；</li>\n<li><b>逻辑跳跃</b>：从现象直接跳结论 → 补上排查过程；</li>\n<li><b>口径过度</b>：\"肯定是内存问题\" → 改成\"数据指向内存，待交叉验证\"；</li>\n<li><b>边界不清</b>：哪些测过、哪些没测 → 明确\"验证范围与局限\"。</li></ul>\n<h5>2. 评审流程</h5>\n<ol><li>自己先按清单自查一遍；</li>\n<li>请导师/研发/测试同事预审（不同视角抓不同问题）；</li>\n<li>按意见修改 → 标出\"修改记录\"（哪条意见改成了什么）；</li>\n<li>领导终审 → 通过后归档。</li></ol>\n<h5>3. 心态</h5>\n<p>评审不是找茬，是帮你把报告变成\"别人也能验证\"的文档。被打回 2-3 次很正常——每打回一次，避坑清单就多一条经验。</p>"}], "out": "FA 报告修订版 + 避坑清单"}, {"id": "d50", "title": "报告定稿 + 周复盘", "date": "Day 50 · 周五", "dot": "5", "tasks": ["完成报告定稿并通过领导评审", "FA 报告归档案例库（编号/日期/搜索标签）", "完成《12周计划》W10 验收点打勾", "周复盘：本次报告最难的环节是什么"], "tools": "FA报告模板、案例库", "resources": [], "lectures": [{"title": "报告定稿与复盘", "html": "<h5>1. 定稿标准（六段齐全 + 可追溯）</h5>\n<ul><li><b>六段齐全</b>：现象 / 数据 / 根因 / 对策 / 验证 / 预防；</li>\n<li><b>每个结论可追溯到数据</b>：说\"稳定\"就要有跑了多久的数据，说\"根因\"就要有交叉验证记录；</li>\n<li><b>边界明确</b>：验证范围、未验证项写清楚（哪些平台没测、哪些场景没覆盖——诚实是专业的一部分）；</li>\n<li><b>通过领导评审</b>：评审意见逐条处理并留痕。</li></ul>\n<h5>2. 定稿前的自查清单</h5>\n<ul><li>现象描述是否有客户原话 + 截图？</li>\n<li>数据部分是否包含：测试环境 / 工具版本 / 时长 / 判据 / 原始日志路径？</li>\n<li>根因是否为\"最简解释\"（Occam 剃刀——别过度设计）？</li>\n<li>对策是否区分临时/永久，指定了负责人和时限？</li>\n<li>验证部分是否真的验证过（不是计划）？</li></ul>\n<h5>3. 归档动作（让报告\"活起来\"）</h5>\n<ol><li>编号（如 FAE-2026-XXX）→ 入案例库；</li>\n<li>打搜索标签：<b>现象关键词 / 平台 / 型号 / 根因</b>（标签决定 3 个月后能不能被搜到）；</li>\n<li>同步 FAQ：如果这个客诉是高频问题，把标准回答沉淀成 FAQ 条目；</li>\n<li>通知相关人员：涉及研发/质量/销售的关键结论，同步到位并确认收到。</li></ol>\n<h5>4. 复盘四问（每次定稿后 10 分钟做掉）</h5>\n<ol><li>这次报告<b>最难的部分</b>是什么？（数据不够 / 逻辑组织 / 结论拿不准？）</li>\n<li>我<b>卡在哪一步</b>？为什么卡？（信息 / 工具 / 知识？）</li>\n<li>下次同类报告，我能<b>省掉哪一步</b>？（复用什么模板？提前要什么数据？）</li>\n<li>这个教训写进《FA 报告避坑清单》了吗？（不写=白踩坑）</li></ol>\n<h5>5. FA 报告的价值（写给谁看要清楚）</h5>\n<p>客户看结论和可信度、研发看数据和机理、质量看对策和预防、领导看效率和资产——<b>一份报告四个读者</b>，各取所需，你才真的是在\"写报告\"而不是\"交作业\"。</p>\n<div class=\"tip\">💡 好报告的标准：\"结论可以先看，数据可以复查，边界的坦诚让所有人都敢签字。\"</div>"}], "out": "通过评审的 FA 报告 + W10复盘"}]}, {"id": "w11", "badge": "W11", "title": "风险预判与前期支持：新项目导入", "sub": "阶段 P3 · 从\"救火\"到\"防火\"", "accept": "能针对一个拟导入项目输出风险评估清单。", "tools": "QVL、项目进度跟踪表、历史案例库", "phase": "P3", "weekend": "周末加油站：把风险评估清单给导师评审；准备 W12 结业汇报材料；把 12 周成果目录过一遍。 可选：学习\"如何做年终汇报/结业PPT\"技巧", "days": [{"id": "d51", "title": "新项目导入流程学习", "date": "Day 51 · 周一", "dot": "1", "tasks": ["学习新项目导入全流程：需求→选型→样品→测试→认证→量产", "认识 FAE 在新项目中的角色：前期技术支持、风险评估、测试建议", "学习《项目进度跟踪表》字段与用法", "找一个历史\"导入期踩坑\"案例复盘"], "tools": "项目导入SOP、项目进度跟踪表", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1aW4y1F7y5", "label": "▶ 风险评估报告怎么写（catfish2018 · 6965播放）"}], "lectures": [{"title": "新项目导入：风险评估清单", "html": "<h5>1. FAE 在新项目中的角色</h5>\n<p>在客户选型/导入阶段提前介入，输出\"前期技术支持意见 + 测试建议\"，把坑提前填掉。</p>\n<h5>2. 风险维度</h5>\n<ul><li><b>平台兼容</b>：CPU IMC/Gear、主板 QVL、BIOS 版本；</li>\n<li><b>颗粒组合</b>：单双 rank、颗粒批次、混插风险；</li>\n<li><b>散热</b>：机箱风道、马甲、高温降频；</li>\n<li><b>频率时序电压</b>：目标档位是否留余量；</li>\n<li><b>物料批次</b>：投产批次稳定性。</li></ul>\n<h5>3. 清单结构</h5>\n<p>风险项 / 发生概率 / 影响程度 / 当前状态（已验证OK·需测试确认）/ 建议对策 —— 一页纸给客户和内部看。</p>"}], "out": "项目导入流程图（标注FAE动作）"}, {"id": "d52", "title": "风险维度学习", "date": "Day 52 · 周二", "dot": "2", "tasks": ["学习风险维度：平台兼容、BIOS版本、颗粒组合、散热、频率时序、物料批次", "用历史案例库找出 3 个典型\"新项目风险\"案例", "学习\"提前识别\"方法：对照QVL、查历史相似组合、问研发已知问题", "建立个人《风险维度检查表》"], "tools": "历史案例库、QVL", "resources": [], "lectures": [{"title": "新项目风险维度：提前排雷", "html": "<h5>1. FAE 在新项目中的位置</h5>\n<p>客户选型/导入阶段，FAE 的活儿是<b>提前识别风险</b>，避免量产了才爆雷（那时成本高、口碑差）。</p>\n<h5>2. 风险维度检查表（8个维度起步）</h5>\n<ul><li><b>平台兼容</b>：CPU IMC/Gear、主板 QVL、BIOS 版本；</li>\n<li><b>颗粒组合</b>：颗粒厂商/位数/单双 Rank、混插风险；</li>\n<li><b>频率/时序</b>：目标档位是否留余量、XMP 依赖；</li>\n<li><b>散热</b>：机箱风道、马甲、高温降频；</li>\n<li><b>供电</b>：PMIC、主板内存供电能力；</li>\n<li><b>物料批次</b>：投产批次稳定性、变更管理；</li>\n<li><b>软件生态</b>：OS/BIOS/驱动兼容；</li>\n<li><b>认证要求</b>：客户规格书特殊要求（温度/可靠性）。</li></ul>\n<h5>3. 用什么资料识别</h5>\n<ul><li>历史案例库：同平台/同颗粒的旧坑；</li>\n<li>QVL：主板厂商已验证组合；</li>\n<li>研发/测试同事的已知问题清单。</li></ul>"}], "out": "风险维度检查表（≥8维度）"}, {"id": "d53", "title": "输出风险评估清单", "date": "Day 53 · 周三", "dot": "3", "tasks": ["选定一个拟导入项目（真实或模拟）", "按检查表逐项评估：风险项/概率/影响/对策建议", "区分\"已验证OK\"与\"需测试确认\"两类结论", "输出《风险评估清单》（一页纸版）"], "tools": "风险评估模板、项目资料", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1aW4y1F7y5", "label": "▶ 风险评估报告怎么写（catfish2018 · 6965播放）"}], "lectures": [{"title": "新项目导入：风险评估清单", "html": "<h5>1. FAE 在新项目中的角色</h5>\n<p>在客户选型/导入阶段提前介入，输出\"前期技术支持意见 + 测试建议\"，把坑提前填掉。</p>\n<h5>2. 风险维度</h5>\n<ul><li><b>平台兼容</b>：CPU IMC/Gear、主板 QVL、BIOS 版本；</li>\n<li><b>颗粒组合</b>：单双 rank、颗粒批次、混插风险；</li>\n<li><b>散热</b>：机箱风道、马甲、高温降频；</li>\n<li><b>频率时序电压</b>：目标档位是否留余量；</li>\n<li><b>物料批次</b>：投产批次稳定性。</li></ul>\n<h5>3. 清单结构</h5>\n<p>风险项 / 发生概率 / 影响程度 / 当前状态（已验证OK·需测试确认）/ 建议对策 —— 一页纸给客户和内部看。</p>"}], "out": "风险评估清单 V1"}, {"id": "d54", "title": "前期技术支持意见 + 测试建议", "date": "Day 54 · 周四", "dot": "4", "tasks": ["基于风险评估输出\"前期技术支持意见\"（选型/平台建议）", "输出\"测试建议\"：QVL覆盖测试、压力测试计划、平台组合矩阵", "与测试/研发确认测试建议可执行", "把意见整理成《项目前期技术支持报告》草稿"], "tools": "测试规范、项目资料", "resources": [], "lectures": [{"title": "前期技术支持意见 + 测试建议", "html": "<h5>1. 输出物结构（前期技术支持意见 + 测试建议）</h5>\n<ol><li><b>选型/平台建议</b>：基于客户场景（游戏/渲染/服务器 7x24/信创）推荐合适的内存组合，写明理由；</li>\n<li><b>风险点说明</b>：高风险项列出证据——历史案例、QVL 缺口、平台已知问题；</li>\n<li><b>测试建议</b>：QVL 覆盖测试、压力测试计划、平台矩阵（Intel/AMD/多代）；</li>\n<li><b>时间表</b>：测试排期、验证节点、风险对策窗口（留出 buffer）。</li></ol>\n<h5>2. 测试建议怎么写才\"有用\"（不是走过场）</h5>\n<ul><li>具体到<b>测什么工具、跑多久、什么平台组合、判据是什么</b>——新人才拿起来就能执行；</li>\n<li>覆盖<b>客户真实负载场景</b>：游戏 = 长时间游戏 + 高负载压测；渲染 = 多线程内存带宽；服务器 = 7x24 稳定性 + ECC（如有）；</li>\n<li>留出<b>边界测试</b>：目标档位超频 +1 档测余量（判断颗粒体质余量）；</li>\n<li>明确<b>PASS/FAIL 判据</b>：MemTest86 多少 Pass、BurnInTest 多久无错、温度上限多少。</li></ul>\n<h5>3. 测试矩阵示例（可直接套用）</h5>\n<table><tr><th>平台</th><th>测试项</th><th>工具</th><th>时长/判据</th></tr>\n<tr><td>Intel 12/13/14代</td><td>开机+基础带宽</td><td>CPU-Z/AIDA64</td><td>频率/时序达标的无报错</td></tr>\n<tr><td>AMD AM4/AM5</td><td>FCLK 稳定性</td><td>AIDA64 压力</td><td>1h 无 WHEA 错误</td></tr>\n<tr><td>目标整机</td><td>长时间稳定性</td><td>MemTest86 + BurnInTest</td><td>MT86 2Pass / BurnIn 8h</td></tr>\n<tr><td>高低温</td><td>温度边界</td><td>高低温箱/HWiNFO</td><td>55℃/85℃ 温区稳定</td></tr></table>\n<h5>4. 与客户沟通：把技术\"翻译\"成人话</h5>\n<p>\"我们建议在贵司目标平台做一轮 X 测试，预计 Y 天完成，这是为了防止 Z 风险\"——<b>管理预期 + 给时间表 + 说清为什么</b>，客户才愿意等。避免只说\"建议测一下\"（客户不知道要多久、为什么、有什么风险）。</p>\n<h5>5. 前期介入的价值（FAE 的\"防火\"思维）</h5>\n<p>在客户选型/导入阶段提前介入，把坑提前填掉：<b>导入期发现问题的成本是量产期的十分之一</b>。FAE 前期多花 1 小时，可能省客户 1 周停产。</p>\n<div class=\"tip\">💡 考核点：能当场输出一份\"具体到工具/时长/判据\"的测试矩阵，而不是泛泛说\"建议压力测试\"——这就是专业度差距。</div>"}], "out": "前期技术支持报告（草稿）"}, {"id": "d55", "title": "项目会参与 + 周复盘", "date": "Day 55 · 周五", "dot": "5", "tasks": ["参加新项目导入会议（如条件允许）", "在会上汇报风险评估要点（练习表达）", "根据反馈更新风险评估清单 V2", "完成《12周计划》W11 验收点打勾 + 周复盘"], "tools": "项目会材料、反馈记录", "resources": [], "lectures": [{"title": "项目会参与：不只是旁听", "html": "<h5>1. 会前准备</h5>\n<ul><li>读项目资料：需求文档、规格书、历史反馈；</li>\n<li>准备 1-2 个技术问题/风险点想主动提出；</li>\n<li>明确自己要在会上同步什么（风险评估要点）。</li></ul>\n<h5>2. 会中动作</h5>\n<ul><li>记录会议纪要（议题/结论/待办/责任人/期限）；</li>\n<li>听不懂的术语记下来会后查；</li>\n<li>有机会就汇报风险评估（哪怕 2 分钟），锻炼表达。</li></ul>\n<h5>3. 会后</h5>\n<ul><li>按会议纪要推进自己的待办；</li>\n<li>更新《风险评估清单》→ V2；</li>\n<li>复盘：这次会上我有没有输出价值？下次怎么更好？</li></ul>"}], "out": "风险评估清单 V2 + 周复盘"}]}, {"id": "w12", "badge": "W12", "title": "综合验收与案例归档：结业汇报", "sub": "阶段 P3 · 12周终点，上岗起点", "accept": "验收清单全部达标（见Sheet五），完成结业汇报。", "tools": "验收清单、案例库、结业PPT", "phase": "P3", "weekend": "🎉 结业周末：正式向深化期冲刺！阅读 M4-M6 深化期计划，与导师确认深化期 KPI 与第一个独立客诉目标。 给自己一个复盘仪式：把 12 周最有成就感的 3 件事写下来，作为下阶段起点", "days": [{"id": "d56", "title": "验收清单逐项自评", "date": "Day 56 · 周一", "dot": "1", "tasks": ["对照《上岗验收清单》逐项自评，标注达标/待补", "不足项制定 48 小时补齐计划", "整理三大交付物：知识笔记/测试证据/案例库", "把自评结果同步导师，请求抽测范围提示"], "tools": "验收清单、12周文档", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1c7411z7Zt", "label": "▶ 工作型PPT制作入门（Office讲师陈飞 · 2.0万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV168411H73G", "label": "▶ 文献汇报PPT该怎么做（做科研的大师兄 · 14.0万播放）"}], "lectures": [{"title": "结业验收与汇报：让努力被看见", "html": "<h5>1. 验收清单自评（对照逐项打勾，别只会说\"我学了\"）</h5>\n<p>知识口试 / 实物指认 / XMP 实操 / MT86 判读 / 故障根因 / NTF 证据链 / 客诉闭环 / FA 报告 / 案例库 / 安全规范——每一项都要能拿出<b>证据</b>：口试答对、实操录像、判读报告、闭环案例号。</p>\n<h5>2. 结业汇报结构（一页一主题，数据说话）</h5>\n<ol><li><b>成长历程</b>：起点 → 关键节点 → 现在（2-3 张照片/截图即可，别放流水账）；</li>\n<li><b>能力成果（有证据）</b>：完成 XX 任务 / 独立处理 XX 单客诉 / 产出 XX 篇讲义 FA 报告——全部带数字；</li>\n<li><b>典型案例（1-2 个讲深）</b>：选最有技术含量的一单，按\"现象→排查→根因→对策\"讲透，包含数据；</li>\n<li><b>下一步计划</b>：M4-M6 深化方向 + 具体目标（可量化）。</li></ol>\n<h5>3. 答应领导/导师的\"汇报句式\"</h5>\n<ul><li>\"我解决了 X，靠的是 Y 方法，留下 Z 资产\"——x3 针对三个能力维度各说一次；</li>\n<li>\"这个案例让我学会了...\"——体现成长，不只是做事；</li>\n<li>\"下一步我要补...\"——表现规划能力。</li></ul>\n<h5>4. 汇报技巧（细节决定观感）</h5>\n<ul><li><b>先讲结论再展开</b>：PPT 第一页就有结论，听众不用猜；</li>\n<li>数据可视化：进度条/对比图/时间轴 > 大段文字；</li>\n<li>准备 1 页\"被追问页\"：领导可能问的刁钻问题，答案预先写好（颗粒型号含义？判读步骤？）；</li>\n<li>领导抽测时：<b>会的说透，不会的坦诚 + 给补课计划</b>——硬编答案被拆穿比坦诚更伤。</li></ul>\n<h5>5. 汇报前自测三问</h5>\n<p>① 3 分钟能讲完核心吗（电梯演讲）？② 每个数字都有出处吗？③ 被问到\"你最大失误是什么\"能答好吗？（这道题考察自我认知，别答\"没有\"）</p>\n<div class=\"tip\">💡 汇报不是\"总结过去\"，是\"推销未来\"：让领导相信你 M4-M6 能独立扛事，才拿到深化期的资源。</div>"}], "out": "验收自评表"}, {"id": "d57", "title": "TOP 案例归档 + 知识库更新", "date": "Day 57 · 周二", "dot": "2", "tasks": ["挑选 TOP 案例（≥5例最有价值的）正式归档", "按统一规范：编号/现象/根因/对策/证据路径/搜索标签", "知识库更新：笔记/速查卡/测试模板归位到标准目录", "更新 QVL 与项目进度跟踪表（如有变化）"], "tools": "案例库、知识库目录、QVL", "resources": [], "lectures": [{"title": "案例归档 + 知识库更新：让经验不丢", "html": "<h5>1. 案例库规范（每例 <200 字，只留最可复用的部分）</h5>\n<pre>\n案例编号：FAE-2026-XXX\n现象：<一句话，客户原话>>\n平台：<主板/CPU/OS/内存型号/批次>\n根因：<一句话，能验证的结论>\n证据：<日志/截图路径，指向原始文件>\n对策：<临时+永久>\n教训：<踩过的坑 / 可复用的排查思路>\n状态：<已闭环/复核中>\n</pre>\n<h5>2. 选 TOP 案例的标准（不是所有案例都值得归档）</h5>\n<ul><li><b>有代表性</b>：该故障类型第一次遇到，或同类问题的高频代表；</li>\n<li><b>有完整证据链</b>：现象→排查→根因→验证全链路清晰，能当培训教材；</li>\n<li><b>有教训</b>：自己踩过坑的案例最值钱——把\"当时差点走错的方向\"写进去，比正确路径更有教育意义。</li></ul>\n<h5>3. 案例库组织（检索友好 ≥ 收藏整齐）</h5>\n<ul><li>按<b>故障现象 / 平台 / 内存型号 / 排查方法</b>打标签（检索靠标签，不靠记忆）；</li>\n<li>速查卡归一类、案例归一类、模板归一类——三样东西分开，用时各取所需；</li>\n<li>命名统一：`FAE-2026-XXX_现象关键词`，一眼可扫；</li>\n<li>每月更新一次 QVL 与项目跟踪表（案例中发现的兼容性结论要回流到 QVL）。</li></ul>\n<h5>4. 归档的\"30 秒原则\"</h5>\n<p>客诉闭环当天顺手归档（趁热），别攒到周末——<b>隔了 3 天细节就模糊，隔一周就更不想写了</b>。写不写得好是能力问题，写不写是态度问题。</p>\n<h5>5. 知识库的\"活\"与\"死\"</h5>\n<p>归档只是第一步：<b>每月回访一次</b>——哪些案例被重复问到？说明 FAQ 没覆盖；哪些案例过时了？更新或下架。知识库要像代码一样维护，不是存完就完事。</p>\n<div class=\"tip\">💡 一个好案例 = 未来的你 + 新来的同事 都能 5 分钟看懂并复用。写案例时问自己：\"如果我失忆了，靠这条能恢复这个经验吗？\"</div>"}], "out": "案例库归档完成（≥5例）"}, {"id": "d58", "title": "结业汇报 PPT 制作", "date": "Day 58 · 周三", "dot": "3", "tasks": ["制作结业汇报 PPT 结构：成长历程→能力成果→典型案例→下一步", "用\"考核表式清爽\"风格：一页一主题、数据可视化", "精选 1-2 个典型案例讲深讲透（含数据）", "写讲稿 / 排练第一遍"], "tools": "PPT模板、案例数据", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1c7411z7Zt", "label": "▶ 工作型PPT制作入门（Office讲师陈飞 · 2.0万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV168411H73G", "label": "▶ 文献汇报PPT该怎么做（做科研的大师兄 · 14.0万播放）"}], "lectures": [{"title": "结业验收与汇报：让努力被看见", "html": "<h5>1. 验收清单自评（对照逐项打勾，别只会说\"我学了\"）</h5>\n<p>知识口试 / 实物指认 / XMP 实操 / MT86 判读 / 故障根因 / NTF 证据链 / 客诉闭环 / FA 报告 / 案例库 / 安全规范——每一项都要能拿出<b>证据</b>：口试答对、实操录像、判读报告、闭环案例号。</p>\n<h5>2. 结业汇报结构（一页一主题，数据说话）</h5>\n<ol><li><b>成长历程</b>：起点 → 关键节点 → 现在（2-3 张照片/截图即可，别放流水账）；</li>\n<li><b>能力成果（有证据）</b>：完成 XX 任务 / 独立处理 XX 单客诉 / 产出 XX 篇讲义 FA 报告——全部带数字；</li>\n<li><b>典型案例（1-2 个讲深）</b>：选最有技术含量的一单，按\"现象→排查→根因→对策\"讲透，包含数据；</li>\n<li><b>下一步计划</b>：M4-M6 深化方向 + 具体目标（可量化）。</li></ol>\n<h5>3. 答应领导/导师的\"汇报句式\"</h5>\n<ul><li>\"我解决了 X，靠的是 Y 方法，留下 Z 资产\"——x3 针对三个能力维度各说一次；</li>\n<li>\"这个案例让我学会了...\"——体现成长，不只是做事；</li>\n<li>\"下一步我要补...\"——表现规划能力。</li></ul>\n<h5>4. 汇报技巧（细节决定观感）</h5>\n<ul><li><b>先讲结论再展开</b>：PPT 第一页就有结论，听众不用猜；</li>\n<li>数据可视化：进度条/对比图/时间轴 > 大段文字；</li>\n<li>准备 1 页\"被追问页\"：领导可能问的刁钻问题，答案预先写好（颗粒型号含义？判读步骤？）；</li>\n<li>领导抽测时：<b>会的说透，不会的坦诚 + 给补课计划</b>——硬编答案被拆穿比坦诚更伤。</li></ul>\n<h5>5. 汇报前自测三问</h5>\n<p>① 3 分钟能讲完核心吗（电梯演讲）？② 每个数字都有出处吗？③ 被问到\"你最大失误是什么\"能答好吗？（这道题考察自我认知，别答\"没有\"）</p>\n<div class=\"tip\">💡 汇报不是\"总结过去\"，是\"推销未来\"：让领导相信你 M4-M6 能独立扛事，才拿到深化期的资源。</div>"}], "out": "结业 PPT V1"}, {"id": "d59", "title": "汇报排练 + 自测", "date": "Day 59 · 周四", "dot": "4", "tasks": ["向导师/同事完整排练一次，收集提问", "演练领导可能抽测的问题（口述D4/D5、根因清单、测试判读）", "修改 PPT 与讲稿（控时在 10-15 分钟）", "提前调试会议室设备/备份文件"], "tools": "排练反馈、抽测题库", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1c7411z7Zt", "label": "▶ 工作型PPT制作入门（Office讲师陈飞 · 2.0万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV168411H73G", "label": "▶ 文献汇报PPT该怎么做（做科研的大师兄 · 14.0万播放）"}], "lectures": [{"title": "结业验收与汇报：让努力被看见", "html": "<h5>1. 验收清单自评（对照逐项打勾，别只会说\"我学了\"）</h5>\n<p>知识口试 / 实物指认 / XMP 实操 / MT86 判读 / 故障根因 / NTF 证据链 / 客诉闭环 / FA 报告 / 案例库 / 安全规范——每一项都要能拿出<b>证据</b>：口试答对、实操录像、判读报告、闭环案例号。</p>\n<h5>2. 结业汇报结构（一页一主题，数据说话）</h5>\n<ol><li><b>成长历程</b>：起点 → 关键节点 → 现在（2-3 张照片/截图即可，别放流水账）；</li>\n<li><b>能力成果（有证据）</b>：完成 XX 任务 / 独立处理 XX 单客诉 / 产出 XX 篇讲义 FA 报告——全部带数字；</li>\n<li><b>典型案例（1-2 个讲深）</b>：选最有技术含量的一单，按\"现象→排查→根因→对策\"讲透，包含数据；</li>\n<li><b>下一步计划</b>：M4-M6 深化方向 + 具体目标（可量化）。</li></ol>\n<h5>3. 答应领导/导师的\"汇报句式\"</h5>\n<ul><li>\"我解决了 X，靠的是 Y 方法，留下 Z 资产\"——x3 针对三个能力维度各说一次；</li>\n<li>\"这个案例让我学会了...\"——体现成长，不只是做事；</li>\n<li>\"下一步我要补...\"——表现规划能力。</li></ul>\n<h5>4. 汇报技巧（细节决定观感）</h5>\n<ul><li><b>先讲结论再展开</b>：PPT 第一页就有结论，听众不用猜；</li>\n<li>数据可视化：进度条/对比图/时间轴 > 大段文字；</li>\n<li>准备 1 页\"被追问页\"：领导可能问的刁钻问题，答案预先写好（颗粒型号含义？判读步骤？）；</li>\n<li>领导抽测时：<b>会的说透，不会的坦诚 + 给补课计划</b>——硬编答案被拆穿比坦诚更伤。</li></ul>\n<h5>5. 汇报前自测三问</h5>\n<p>① 3 分钟能讲完核心吗（电梯演讲）？② 每个数字都有出处吗？③ 被问到\"你最大失误是什么\"能答好吗？（这道题考察自我认知，别答\"没有\"）</p>\n<div class=\"tip\">💡 汇报不是\"总结过去\"，是\"推销未来\"：让领导相信你 M4-M6 能独立扛事，才拿到深化期的资源。</div>"}], "out": "结业 PPT V2 + 排练记录"}, {"id": "d60", "title": "结业汇报 + 验收通过", "date": "Day 60 · 周五", "dot": "5", "tasks": ["完成结业汇报（领导/团队面前）", "通过验收清单全部达标（领导确认）", "输出 12 周复盘总结 + 下阶段计划（M4-M6）", "感谢导师/团队，同步 M4-M6 目标"], "tools": "验收清单、结业PPT、下阶段计划", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1c7411z7Zt", "label": "▶ 工作型PPT制作入门（Office讲师陈飞 · 2.0万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV168411H73G", "label": "▶ 文献汇报PPT该怎么做（做科研的大师兄 · 14.0万播放）"}], "lectures": [{"title": "结业验收与汇报：让努力被看见", "html": "<h5>1. 验收清单自评（对照逐项打勾，别只会说\"我学了\"）</h5>\n<p>知识口试 / 实物指认 / XMP 实操 / MT86 判读 / 故障根因 / NTF 证据链 / 客诉闭环 / FA 报告 / 案例库 / 安全规范——每一项都要能拿出<b>证据</b>：口试答对、实操录像、判读报告、闭环案例号。</p>\n<h5>2. 结业汇报结构（一页一主题，数据说话）</h5>\n<ol><li><b>成长历程</b>：起点 → 关键节点 → 现在（2-3 张照片/截图即可，别放流水账）；</li>\n<li><b>能力成果（有证据）</b>：完成 XX 任务 / 独立处理 XX 单客诉 / 产出 XX 篇讲义 FA 报告——全部带数字；</li>\n<li><b>典型案例（1-2 个讲深）</b>：选最有技术含量的一单，按\"现象→排查→根因→对策\"讲透，包含数据；</li>\n<li><b>下一步计划</b>：M4-M6 深化方向 + 具体目标（可量化）。</li></ol>\n<h5>3. 答应领导/导师的\"汇报句式\"</h5>\n<ul><li>\"我解决了 X，靠的是 Y 方法，留下 Z 资产\"——x3 针对三个能力维度各说一次；</li>\n<li>\"这个案例让我学会了...\"——体现成长，不只是做事；</li>\n<li>\"下一步我要补...\"——表现规划能力。</li></ul>\n<h5>4. 汇报技巧（细节决定观感）</h5>\n<ul><li><b>先讲结论再展开</b>：PPT 第一页就有结论，听众不用猜；</li>\n<li>数据可视化：进度条/对比图/时间轴 > 大段文字；</li>\n<li>准备 1 页\"被追问页\"：领导可能问的刁钻问题，答案预先写好（颗粒型号含义？判读步骤？）；</li>\n<li>领导抽测时：<b>会的说透，不会的坦诚 + 给补课计划</b>——硬编答案被拆穿比坦诚更伤。</li></ul>\n<h5>5. 汇报前自测三问</h5>\n<p>① 3 分钟能讲完核心吗（电梯演讲）？② 每个数字都有出处吗？③ 被问到\"你最大失误是什么\"能答好吗？（这道题考察自我认知，别答\"没有\"）</p>\n<div class=\"tip\">💡 汇报不是\"总结过去\"，是\"推销未来\"：让领导相信你 M4-M6 能独立扛事，才拿到深化期的资源。</div>"}], "out": "结业汇报完成 + 验收通过记录"}]}, {"id": "m4", "badge": "M4", "title": "深化期第一月：独立承接常规业务", "sub": "在岗深化 · 把 12 周所学变成日常生产力", "accept": "独立承接常规客诉业务，闭环效率与准确率达标。", "tools": "维护QVL/案例库、跟踪每个客诉全流程、周度效率复盘", "phase": "M", "weekend": "", "days": [{"id": "d61", "title": "独立接单周（第1-2周）", "date": "M4 月初", "dot": "1", "tasks": ["独立承接 2-3 单常规客诉（不再依赖导师默认）", "每单走全流程：信息收集→排查→对策→闭环→归档", "建立个人客诉效率基线：首响时间/闭环周期/一次判准率", "每周五做客诉效率复盘，找出耗时环节"], "tools": "客户支持流程SOP、客诉跟踪表", "resources": [], "lectures": [{"title": "M4 独立接单：从跟跑到独跑", "html": "<h5>1. 独立 vs 跟单的差别</h5>\n<p>跟单时导师兜底，独立时<b>你要对结果负责</b>。差别在：主动信息收集（没人提醒你问全）、自主排期（没人帮你定 deadline）、对外沟通（客户直接找你）。</p>\n<h5>2. 独立接单 SOP</h5>\n<ol><li>接单登记（客诉单全字段）；</li>\n<li>信息收集模板发客户（一次问全）；</li>\n<li>建立个人跟进表（进度/下一步/截止）；</li>\n<li>每 1-2 天同步销售/客户；</li>\n<li>排查→对策→验证→闭环→归档。</li></ol>\n<h5>3. 效率基线</h5>\n<p>从第一单开始记录：<b>首响时间、信息收集耗时、闭环周期、一次判准率</b>。一个月后看趋势，就知道自己哪里慢。</p>\n<div class=\"warn\">⚠️ 独立≠单干：拿不准的该找导师/研发就问，但带着\"我已查到哪、卡在哪\"去问，而不是空手问。</div>"}], "out": "客诉效率基线表 + ≥3单闭环记录"}, {"id": "d62", "title": "QVL 与案例库维护（第3周）", "date": "M4 月中", "dot": "2", "tasks": ["按新平台/新BIOS版本维护 QVL 表（每月更新）", "案例库新增 ≥2例/月，覆盖不同故障类型", "把\"可复用的排查套路\"提炼进标准化手册草稿", "向团队同步一次本月知识点（10分钟小分享）"], "tools": "QVL、案例库、知识库", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1VhnF6yEDQ", "label": "▶ 爆肝测试100套组合·内存不兼容原因（和微论件 · 11.2万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1ua411L78Y", "label": "▶ 内存条兼容性·玄学问题（ZoveyChen · 11.8万播放）"}, {"type": "off", "url": "https://www.asus.com/support/", "label": "📄 华硕内存支持(QVL)"}, {"type": "off", "url": "https://www.msi.com/support", "label": "📄 微星内存支持列表"}], "lectures": [{"title": "QVL 解读：怎么查、怎么看、边界在哪", "html": "<h5>1. QVL 是什么</h5>\n<p>QVL（Qualified Vendor List）= 主板厂商实测过的内存型号兼容列表。它回答：\"这块主板配这些内存测过没问题。\"</p>\n<h5>2. QVL 表格怎么读（常见列）</h5>\n<ul><li><b>Vendor 厂商</b>：内存品牌（如 HOOE/三星/金士顿）；</li>\n<li><b>Part Number</b>：具体型号（关键，同名品牌不同型号也要看准）；</li>\n<li><b>Capacity 容量</b>：单条/套条容量；</li>\n<li><b>Speed 频率</b>：测试时达到的频率（XMP 档或 JEDEC）；</li>\n<li><b>Timing/Voltage</b>：对应时序与电压。</li></ul>\n<h5>3. 检索动作（标准流程）</h5>\n<ol><li>到华硕/微星/技嘉等官网 → 产品页 → 支持/规格 → 内存兼容性列表；</li>\n<li>搜品牌型号（用精确 Part Number，别只搜系列名）；</li>\n<li>记录该型号在哪些插槽/容量组合下验证通过。</li></ol>\n<h5>4. 边界理解（FAE 常被问）</h5>\n<ul><li>不在 QVL ≠ 一定不兼容——只是没测过；</li>\n<li>在 QVL ≠ 绝对没问题——QVL 基于特定 BIOS 版本/批次；</li>\n<li>判定\"兼容性问题\"要结合实测，不能只看列表。</li></ul>\n<div class=\"warn\">⚠️ 客户若用\"不在 QVL\"质疑，正确回应：\"QVL 是厂商测试基线，不代表全部；我们按实际平台做交叉验证来定位。\"</div>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。</p>\n<h5>2. 每例 <200 字的推荐格式</h5>\n<pre>案例编号：FAE-2026-XXX\n现象：一句话\n平台：主板/CPU/OS/内存型号\n根因：一句话\n证据：日志/截图路径\n对策：临时+永久\n状态：已闭环/复核中</pre>\n<h5>3. 什么案例值得记</h5>\n<ul><li>第一次遇到的故障类型；</li>\n<li>排查过程走弯路的（教训最值钱）；</li>\n<li>证据链完整、能当培训材料的；</li>\n<li>客户高频问题（同问必记）。</li></ul>\n<h5>4. 归档节奏</h5>\n<p>客诉闭环当天顺手记一例（30 秒的事），月底统一补标签和索引。目标：<b>12 周 ≥10 例，一年 ≥30 例</b>。</p>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。</div>"}], "out": "QVL更新记录 + 案例库增量 + 小分享记录"}, {"id": "d63", "title": "疑难客诉预备（第4周）", "date": "M4 月末", "dot": "3", "tasks": ["识别手头\"疑似NTF\"案例，按 NTF 方法论重新过一遍", "学习疑难案例的升级路径：什么时候上报导师/研发", "月度总结：本月经手客诉全景复盘 + M5 目标制定", "完成 M4 验收：独立承接常规业务、闭环效率达标"], "tools": "NTF方法论、月度复盘模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1PYkrBcE9H", "label": "▶ 如何高情商处理客户投诉（海纳集团视频号 · 7031播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19b4y1d7rg", "label": "▶ 处理顾客投诉五步曲（梁老师889 · 2032播放）"}], "lectures": [{"title": "客诉处理：从接单到闭环", "html": "<h5>1. 八步闭环（每一步都要有产出物）</h5>\n<p><b>信息收集→初判分级→复现测试→根因分析→临时对策→根因对策→验证→归档</b>。不要跳步：客户催得急也要把证据链走完，否则后患无穷。</p>\n<table><tr><th>步骤</th><th>关键动作</th><th>产出物</th></tr>\n<tr><td>①信息收集</td><td>按模板问全：机型/平台/BIOS/内存型号/现象/概率/环境/操作</td><td>信息收集表（一次问全）</td></tr>\n<tr><td>②初判分级</td><td>判断停线/重大/常规，定响应时效</td><td>问题分级 + 响应节点</td></tr>\n<tr><td>③复现测试</td><td>客户环境复现 + 本司平台复现（MemTest86/BurnInTest）</td><td>复现记录（截图/日志/视频）</td></tr>\n<tr><td>④根因分析</td><td>最小化/交叉替换/批次比对/电气测量，锁定层级</td><td>根因假设 + 证据</td></tr>\n<tr><td>⑤临时对策</td><td>先给客户能用的：换槽/降频/单条/关XMP</td><td>临时对策单</td></tr>\n<tr><td>⑥根因对策</td><td>联动研发/质量：换货/固件/工艺/来料管控</td><td>永久对策 + 责任方</td></tr>\n<tr><td>⑦验证</td><td>对策有效性验证（复测通过 + 客户确认）</td><td>验证报告</td></tr>\n<tr><td>⑧归档</td><td>编号入案例库，写清现象→根因→对策→可复用的排查思路</td><td>案例库条目</td></tr></table>\n<h5>2. 分级与响应时效（先响应，再解决）</h5>\n<ul><li><b>产线停线</b>：最高级，1 小时内响应，电话 + 群同步，24h 内给临时对策；</li>\n<li><b>客户升级/大客户</b>：当日响应，48h 内给初步结论；</li>\n<li><b>常规单</b>：1 个工作日内响应。</li></ul>\n<p>第一时间回复<b>\"已收到，正在排查，预计 X 时间给结论\"</b>——不是等有结论才回。客户的焦虑来自沉默，回复=\\\"确定性缓冲\\\"。</p>\n<h5>3. 客诉单要填的字段（对照你的模板逐一确认）</h5>\n<p>客户/机型/平台/BIOS版本/内存型号与SN/数量/故障现象（原话）/出现概率（必现/偶发/频率）/触发条件（开机/压力/冷机/热机）/环境（温度/电压/机箱风道）/客户期望（退货/换货/分析报告/赔偿）/紧急度。缺字段=后面必返工。</p>\n<h5>4. 临时对策 vs 永久对策（边界要分清）</h5>\n<p>临时对策是<b>给客户先能用</b>：换槽/降频/单条/关 XMP/清 CMOS；永久对策是<b>消除根因</b>：换货/固件/工艺/来料管控。\"权宜可用 ≠ 根因解决\"——临时对策单上要写清适用范围与有效期，避免客户把临时当永久。</p>\n<h5>5. 内部协同与对外口径</h5>\n<p>FAE 是窗口：销售/研发/客户三方信息都从你这里对齐。<b>对外口径统一</b>，别在客户群里互相矛盾——不确定的事先内部确认再回复；同时把客户的原始诉求完整带回内部（含情绪、期望、决策人）。</p>\n<h5>6. 客户预期管理话术（背熟直接可用）</h5>\n<ul><li>催结果：\"根因还在交叉验证，我先把已确认的部分同步给您，预计 X 确认完整结论\"；</li>\n<li>想退货：\"换货流程已启动，同时我建议先试临时对策避免影响生产，两条线并行\"；</li>\n<li>质疑结论：\"我用了 A/B 交叉和压力测试，数据如下...如果还有疑虑我们可以一起复现\"。</li></ul>\n<div class=\"tip\">💡 考核/面试点：能说出\"八步闭环\"还不够，要能随手举出每一\"步的产出物——纸上写不出来的流程不叫会。</div>"}, {"title": "疑难案例升级路径：什么时候上报", "html": "<h5>1. 升级的判断标准（满足任一条就升级，不要硬扛）</h5>\n<ul><li><b>时间红线</b>：超过 3 个工作日仍无法收敛方向；</li>\n<li><b>批量风险</b>：同一批次/同型号多根不良反应（不是孤例，可能是产线/物料问题）；</li>\n<li><b>客户升级/产线停线</b>：紧急度拉满，单靠 FAE 节奏不够；</li>\n<li><b>超出装备能力</b>：需要示波器/ATE/失效分析（FA）设备才能推进；</li>\n<li><b>结论影响大</b>：可能要判赔/退货/改设计，需要领导/研发拍板。</li></ul>\n<h5>2. 升级不等于认怂——是\"项目化推进\"</h5>\n<p>把疑难案例当作一个小项目管理：<b>目标（定位根因）/ 里程碑（每周结论）/ 资源（需要谁）/ 风险（卡在哪）</b>。升级 = 向组织申请资源，不是把问题甩出去。</p>\n<h5>3. 上报前的\"三句话\"准备（先说清楚再去敲门）</h5>\n<ol><li><b>已查到哪</b>：现象/平台/复现条件/已排除项（证明你做过功课）；</li>\n<li><b>卡在哪</b>：是信息不全？设备不够？还是结论互相矛盾？</li>\n<li><b>需要什么支持</b>：研发看板子？FA 做切片？还是客户补测？</li></ol>\n<p>带上<b>证据包</b>（日志/截图/复现视频/交叉替换表）再找研发/导师——空手求助和带料求助，得到的响应完全不同。</p>\n<h5>4. 升级流程动作规范</h5>\n<ol><li>同步销售 + 客户进展节奏（升级了 ≠ 通知变少，恰恰要更勤）；</li>\n<li>建立<b>升级单/疑难清单</b>，写明负责人、卡点、需要的支持、承诺时间；</li>\n<li>每周滚动更新状态，即使没有新进展也写上\"本周验证了 X 排除 Y\"；</li>\n<li>闭环后反向沉淀：升级卡点 → 进《疑难案例清单》，防止下次重复卡。</li></ol>\n<h5>5. 跟研发协作的话术</h5>\n<ul><li>\"我已经做了 X 和 Y 排除，现在剩 Z 需要您这边帮看\"（带已查记录）；</li>\n<li>\"客户现场可配合复现，时间您定，我协调\"（降低对方协作成本）；</li>\n<li>\"这个现象和您之前看过的 A 案例像，我对比了数据...\"（用研发语言沟通）。</li></ul>\n<div class=\"tip\">💡 判断升级时机的口诀：\"三天没进展、批量有风险、客户在升级、装备不够用\"——四条占一条就启动升级流程。</div>"}], "out": "M4 月报 + 疑难案例清单"}]}, {"id": "m5", "badge": "M5", "title": "深化期第二月：主导 NTF 与疑难闭环", "sub": "在岗深化 · 啃最硬的骨头", "accept": "主导 1 个以上疑难 NTF 闭环，输出完整证据链。", "tools": "疑难案例牵头、跨部门协调、NTF方法论实战、结论可复现", "phase": "M", "weekend": "", "days": [{"id": "d64", "title": "NTF 主导周（第1-2周）", "date": "M5 月初", "dot": "1", "tasks": ["认领 1 个疑难/NTF 案例，担任主导人", "搭建完整复现环境；设计压力复测/场景复现方案", "交叉验证 + 批次/版本对比，逐步缩小范围", "保持与销售/客户/研发的节奏同步"], "tools": "NTF方法论、复现实验模板、版本/批次对照表", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1gaFez8EFT", "label": "▶ 电脑不定时死机卡住重启怎么办（程工修笔记本 · 5683播放）"}], "lectures": [{"title": "NTF 方法论：找不到故障时的破案纪律", "html": "<h5>1. 什么是 NTF</h5>\n<p>NTF（No Trouble Found）＝客户报障但标准流程测不出问题。价值不在\"找到了\"，而在<b>证据链完整</b>，能对客户交代\"为什么没找到、怎么保证不是我们的问题\"。</p>\n<h5>2. 五板斧</h5>\n<ol><li><b>交叉验证</b>：多条同型号互相换机换槽，确认是否单条问题；</li>\n<li><b>复现环境搭建</b>：还原客户平台/BIOS/OS/负载/温度，不还原就复现不了；</li>\n<li><b>压力复测</b>：8h+ BurnInTest/MonitorMemtest、循环脚本；</li>\n<li><b>批次对比</b>：不同生产批次/颗粒批次交叉测；</li>\n<li><b>版本比对</b>：BIOS/驱动/固件版本差异是常见\"假凶手\"。</li></ol>\n<h5>3. 四类结论</h5>\n<ul><li><b>真不良</b>：有数据实证（MT86 地址、复测日志）；</li>\n<li><b>假性不良</b>：环境/驱动/设置问题（证据链指向非内存）；</li>\n<li><b>人为故障</b>：安装/操作不当（插反、超压、刷坏 SPD）；</li>\n<li><b>环境干扰</b>：ESD、电源质量、温度、电磁干扰。</li></ul>\n<div class=\"warn\">⚠️ NTF 报告切忌\"结论过度\"：没有证据不能说是真不良，也不能硬说没问题。给\"证据链 + 待验证项\"是最职业的写法。</div>"}, {"title": "NTF 专项：从\"复现不了\"到\"证据链完整\"", "html": "<h5>1. NTF 的本质</h5>\n<p>NTF（No Trouble Found）= 客户报障，但你在标准测试环境复现不出来。它不是\"白忙一场\"，而是<b>要求你有\"没有结论的结论\"</b>——即用证据链说明\"为什么没复现、问题可能在哪、下一步怎么办\"。</p>\n<h5>2. 关键误区</h5>\n<ul><li>❌ 复现不了就说\"内存没问题\"——证据不足，客户不信；</li>\n<li>❌ 复现不了就换一条给客户——掩盖问题，下次还来；</li>\n<li>✅ 正确的：完整记录复现条件和所有阴性结果，推导可能方向。</li></ul>\n<h5>3. NTF 五步法</h5>\n<ol><li><b>完整复现环境</b>：还原客户 BIOS/OS/场景/温度；</li>\n<li><b>压力复测</b>：8h+ 内存压力 + 循环脚本（S3/S4/Reboot）；</li>\n<li><b>交叉验证</b>：同型号多条、多平台互测；</li>\n<li><b>批次/版本对比</b>：不同批次、不同 BIOS 版本；</li>\n<li><b>证据链报告</b>：现象→环境→测试→阴性结果→推断→待验证。</li></ol>\n<h5>4. 四类定性</h5>\n<p><b>真不良</b>（复现到错误）/ <b>假性不良</b>（环境影响）/ <b>人为故障</b>（操作不当）/ <b>环境干扰</b>（ESD/电源）。每种都要有证据支撑，宁缺毋滥。</p>"}], "out": "NTF 主导记录 + 阶段性证据"}, {"id": "d65", "title": "疑难闭环周（第3-4周）", "date": "M5 月中", "dot": "2", "tasks": ["收敛结论：真不良/假性不良/人为/环境，证据链完整", "输出 NTF 报告（如涉及FA，按FA模板出报告）", "主导跨部门确认：研发/测试/PQE/生产对结论认同", "闭环后复盘：方法论哪些环节最有效、哪些要优化"], "tools": "FA/NTF报告模板、跨部门协同SOP", "resources": [], "lectures": [{"title": "M5 NTF 主导：把\"疑难\"变成\"可解释\"", "html": "<h5>1. 主导者的责任</h5>\n<p>疑难/NTF 案例的主导人 = 项目负责人：定义问题、安排实验、协调研发/测试/PQE、对客户交代。你不是\"跑测试的\"，你是\"推进闭环的\"。</p>\n<h5>2. 闭环周节奏</h5>\n<ul><li>第1周：问题定义+复现环境搭建 → 跑复测；</li>\n<li>第2周：交叉验证+批次/版本对比 → 缩小范围；</li>\n<li>第3周：写 NTF 报告/FA 报告（证据链）；</li>\n<li>第4周：跨部门确认结论 → 客户沟通 → 闭环复盘。</li></ul>\n<h5>3. 跨部门协调要点</h5>\n<ul><li>给研发的是\"可定位的线索\"，不是\"现象描述\"；</li>\n<li>给测试的是\"明确实验条件\"（工具/参数/时长）；</li>\n<li>给 PQE 的是\"判定依据\"（规范条款）；</li>\n<li>保持一张\"问题状态表\"全员可见。</li></ul>"}], "out": "NTF闭环报告 1 份（含证据链）"}, {"id": "d66", "title": "方法论沉淀（月末）", "date": "M5 月末", "dot": "3", "tasks": ["把 NTF 闭环中的新套路写进《标准化排查手册》", "FAQ 新增 2-3 条（来自本月的客户高频问题）", "月度复盘：疑难案例带给我什么新能力", "完成 M5 验收：NTF 主导闭环 + 准确率达标"], "tools": "排查手册、FAQ、月报模板", "resources": [], "lectures": [{"title": "M5 方法论沉淀：从解决一个问题到解决一类问题", "html": "<h5>1. 为什么要沉淀</h5>\n<p>一个人解决 10 个问题不算强，把 10 个问题的方法变成可复用的<a>套路</a>才算。沉淀物=别人照做也能 80% 复现你的思路。</p>\n<h5>2. 沉淀产品</h5>\n<ul><li><b>排查手册</b>：故障映射表升级、路径图更新、新增案例分支；</li>\n<li><b>FAQ</b>：把本月的客户高频 Q（含话术）写进去；</li>\n<li><b>模板</b>：NTF 报告/客诉周报模板补丁。</li></ul>\n<h5>3. 沉淀的质量标准</h5>\n<p>拿给新人看，新人能看懂并执行 → 达标。如果只有你自己能看懂，那只是笔记不是手册。</p>"}], "out": "M5 月报 + 手册/FAQ 增量"}]}, {"id": "m6", "badge": "M6", "title": "深化期第三月：沉淀手册 · 分享带教", "sub": "在岗深化 · 让能力变成团队的资产", "accept": "产出 1 套可复用资料，内部分享并尝试带教。", "tools": "标准化排查手册、FAQ、团队KPI对齐、半年述职", "phase": "M", "weekend": "", "days": [{"id": "d67", "title": "标准化排查手册 V1（第1-2周）", "date": "M6 月初", "dot": "1", "tasks": ["整理《标准化排查手册》V1：故障映射表→处置流程→模板引用", "整理《FAQ》V1：覆盖高频客诉问题（含话术模板）", "用\"新人视角\"测试手册：让没经验的人能看懂执行", "建立手册版本管理与更新机制"], "tools": "排查手册框架、FAQ模板", "resources": [], "lectures": [{"title": "M6 排查手册 V1：把个人经验变成团队资产", "html": "<h5>1. 手册结构建议（新人拿到就能上手）</h5>\n<ol><li><b>故障现象 → 候选根因（≥4 条 + 排序）→ 验证方法</b>：以现象为入口，不是以根因为条目（新人按现象查）；</li>\n<li><b>排查路径图（标准七层）</b>：信息收集 → 外观/接触 → 最小化 → 交叉替换 → BIOS/软设置 → 工具压测 → 深入分析；</li>\n<li><b>常用工具速查</b>：MT86/BurnInTest/HWiNFO 的最常用参数、判读方法、耗时预期；</li>\n<li><b>报告模板引用</b>：FA/测试/邮件模板的链接（不重复贴，指向标准文档）；</li>\n<li><b>案例索引</b>：按现象/平台检索案例库（附链接）。</li></ol>\n<h5>2. 写作要点（决定手册能不能被用起来）</h5>\n<ul><li>用<b>新人视角</b>检查：假设读者只会基本操作——操作步骤写到\"双击图标\"级别；</li>\n<li>每条结论给<b>判断依据</b>（为什么先查这个，而不是背顺序）——懂得原理才能灵活应变；</li>\n<li>每条验证方法给<b>预期结果</b>和<b>下一步分支</b>（如果 PASS 走 A，FAIL 走 B）；</li>\n<li>版本管理：V1 标日期、维护人，评审后发团队——后续变更走评审，别一两个人悄悄改。</li></ul>\n<h5>3. 写好手册的\"三查\"</h5>\n<ul><li><b>查完整</b>：十大客诉场景（无法开机/蓝屏/容量错/性能差/死机/不识别/NTF/混插/高温/报错）每个都有章节吗？</li>\n<li><b>查可执行</b>：每步都知道\"用什么工具、看什么参数、多久、判据是什么\"吗？</li>\n<li><b>查边界</b>：哪些情况要升级、哪些能自主处理，手册里有分界线吗？</li></ul>\n<h5>4. 手册与 FAQ/案例库的分工</h5>\n<table><tr><th>资产</th><th>定位</th><th>举例</th></tr>\n<tr><td>排查手册</td><td>方法论 + 路径（怎么想）</td><td>七层排查 SOP</td></tr>\n<tr><td>案例库</td><td>具体实例（以前遇到过）</td><td>某批次虚焊案例</td></tr>\n<tr><td>FAQ</td><td>高频问题标准答（怎么答）</td><td>\"内存条要插哪两个槽\"</td></tr></table>\n<div class=\"tip\">💡 手册的最终检验：\"今天来一个实习生，能拿你的手册独立处理常规客诉吗？\"能，手册就成功了。不能，继续改。</div>"}, {"title": "FAQ 怎么写才有人看", "html": "<h5>1. FAQ 的价值</h5>\n<p>FAQ = 把高频客诉问题与标准回答沉淀下来，让新人/销售/客户都能自助。省的是你和团队重复回答的时间。</p>\n<h5>2. 一条好 FAQ 的结构</h5>\n<ol><li><b>问题</b>：客户原话（不是技术术语）；</li>\n<li><b>背景</b>：什么平台/什么现象高频出现；</li>\n<li><b>标准回答</b>：可直接复制的话术；</li>\n<li><b>排查步骤</b>：若回答不够，附验证步骤；</li>\n<li><b>相关案例号</b>：指向案例库深入资料。</li></ol>\n<h5>3. FAQ 维护纪律</h5>\n<ul><li>每单客诉闭环时顺手上架/更新（30 秒的事）；</li>\n<li>按\"平台+现象\"打标签，方便检索；</li>\n<li>每月评审：哪些过时了、哪些还没覆盖。</li></ul>\n<div class=\"tip\">💡 FAQ V1 不求全，先从最近 10 单客诉里挑 5 条最高频的写起。</div>"}], "out": "排查手册 V1 + FAQ V1（可复用资料）"}, {"id": "d68", "title": "内部分享（第3周）", "date": "M6 月中", "dot": "2", "tasks": ["做 1 次内部分享（技术分享会/新人培训），分享手册+典型案例", "收集听众反馈，迭代手册", "尝试带教 1 个新人/实习生（带教记录）", "与导师对齐：离\"独当一面 FAE\"还差什么"], "tools": "分享PPT、反馈收集表", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV18z421Y7SY", "label": "▶ 如何做一次公开技术分享（axb · 1653播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1Tr4y1H7qA", "label": "▶ 培养演讲力·精彩演讲（成信听书 · 2.4万播放）"}], "lectures": [{"title": "内部分享与带教：让经验流动起来", "html": "<h5>1. 为什么要内部分享</h5>\n<p>分享＝把你踩过的坑、总结的方法变成团队的资产。对公司是知识沉淀，对你是<b>专业影响力的积累</b>（资深/主管晋升的重要证据）。</p>\n<h5>2. 技术分享的结构</h5>\n<ol><li>背景/痛点：这个坑是怎么遇到的；</li>\n<li>排查过程：错误尝试也讲，别人才能理解为什么；</li>\n<li>结论与方法：可复用的套路（路径图/清单/话术）；</li>\n<li>提问与答疑：提前准备 2-3 个常见追问。</li></ol>\n<h5>3. 带教新人的要点</h5>\n<ul><li>让新人先做再看：暴露问题才学得快；</li>\n<li>给\"怎么做\"也给\"为什么\"；</li>\n<li>带教记录：每周 10 分钟同步，及时纠偏。</li></ul>\n<div class=\"tip\">💡 分享素材来源：你的案例库。每闭环一单客诉就写 200 字复盘，攒一个月就是一次内部分享。</div>"}], "out": "分享记录 + 带教记录"}, {"id": "d69", "title": "半年复盘 + 述职（月末）", "date": "M6 月末", "dot": "3", "tasks": ["半年总结：12周+3月成果全景汇总（数据化）", "对齐团队 KPI：闭环效率/准确率/知识库产出", "制定下半年计划：升资深FAE的目标分解", "完成 M6 验收：1套可复用资料 + 内部分享 + 带教尝试"], "tools": "半年述职模板、KPI表", "resources": [], "lectures": [{"title": "M6 述职：把 6 个月做成 3 页纸", "html": "<h5>1. 述职报告结构</h5>\n<ol><li>数据总览：处理客诉 X 单、闭环率 Y%、NTF 主导 N 单、案例库 M 例；</li>\n<li>能力成长：从\"不会测\"到\"独立主导\"的 3 个里程碑；</li>\n<li>资产产出：排查手册/FAQ/模板/内部分享；</li>\n<li>不足与计划：最想补的 2 个短板 + 下半年目标。</li></ol>\n<h5>2. 述职技巧</h5>\n<ul><li>用数据说话，不用形容词（\"很多\"→具体数字）；</li>\n<li>讲 1-2 个代表性案例（过程+结果），别罗列流水账；</li>\n<li>主动提\"我需要什么支持\"（培训/工具/平台），比被动等安排强。</li></ul>\n<h5>3. 述职后的动作</h5>\n<p>根据反馈更新下半年计划；把述职中暴露的短板列入学习清单；确认 M4-M6 验收全部打勾。</p>"}], "out": "半年述职报告 + 可复用资料包"}]}];
